window.FURTHER_COURSE={"board": "Pearson Edexcel", "qualification": "9FM0", "checked": "2026-10-23", "modules": [{"id": "core", "title": "Core Pure Mathematics", "code": "Compulsory · both Core Pure papers"}, {"id": "fp1", "title": "Further Pure Mathematics 1", "code": "9FM0/3A"}, {"id": "fp2", "title": "Further Pure Mathematics 2", "code": "9FM0/4A"}, {"id": "fs1", "title": "Further Statistics 1", "code": "9FM0/3B"}, {"id": "fs2", "title": "Further Statistics 2", "code": "9FM0/4B"}, {"id": "fm1", "title": "Further Mechanics 1", "code": "9FM0/3C"}, {"id": "fm2", "title": "Further Mechanics 2", "code": "9FM0/4C"}, {"id": "d1", "title": "Decision Mathematics 1", "code": "9FM0/3D"}, {"id": "d2", "title": "Decision Mathematics 2", "code": "9FM0/4D"}], "lessons": [{"id": "cp-induction", "module": "core", "title": "Proof by induction", "refs": "1.1", "notes": ["Induction proves a statement for an infinite sequence of integer values using a base case and a conditional step. State the starting integer, assume the exact proposition for k, and use that assumption to establish the proposition for k + 1. The assumption is a temporary hypothesis, not the conclusion.", "For sums, add the new term to the assumed formula. For divisibility, separate the new expression into a multiple of the assumed expression and an explicitly divisible remainder. For matrix powers, multiply in the correct order. Finish by stating that the base case and implication establish the result for all integers in the stated domain."], "example": {"q": "Prove 1 + 3 + … + (2n − 1) = n² for n ≥ 1.", "steps": ["Base n = 1: 1 = 1².", "Assume the sum to k equals k².", "The sum to k + 1 is k² + (2k + 1).", "This equals (k + 1)².", "The statement holds for n = 1 and propagates from k to k + 1, so it holds for all integers n ≥ 1."]}, "practice": {"q": "Prove that 3ⁿ − 1 is divisible by 2 for every integer n ≥ 1.", "answer": null, "steps": ["Base n = 1: 3 − 1 = 2.", "Assume 3ᵏ − 1 = 2m for some integer m.", "3ᵏ⁺¹ − 1 = 3(3ᵏ − 1) + 2.", "This is 6m + 2 = 2(3m + 1), a multiple of 2.", "State the inductive conclusion."]}, "check": {"q": "Using 1+3+…+(2n−1)=n², what is the sum when n=6?", "a": 36}, "deep": {"tip": "State the proposition for n = k exactly as given, and make the step where the assumption is used visible. A proof that never uses the inductive hypothesis is not a proof by induction. Finish with a conclusion that mentions the base case, the step and the set of integers covered.", "examples": [{"title": "Divisibility", "q": "Prove by induction that 7ⁿ − 1 is divisible by 6 for all positive integers n.", "steps": ["n = 1: 7 − 1 = 6, which is divisible by 6.", "Assume 7ᵏ − 1 = 6m for some integer m.", "7ᵏ⁺¹ − 1 = 7(7ᵏ − 1) + 6.", "= 42m + 6 = 6(7m + 1), a multiple of 6.", "True for n = 1, and true for n = k implies true for n = k + 1, so true for all positive integers n."]}, {"title": "A matrix power", "q": "Prove by induction that [[1,1],[0,1]]ⁿ = [[1,n],[0,1]] for all positive integers n.", "steps": ["n = 1: both sides are [[1,1],[0,1]].", "Assume [[1,1],[0,1]]ᵏ = [[1,k],[0,1]].", "Multiply by one more factor: [[1,k],[0,1]][[1,1],[0,1]] = [[1,1 + k],[0,1]].", "This is the stated result with n = k + 1.", "True for n = 1 and the step holds, so the result is true for all positive integers n."]}, {"title": "A sum with a product term", "q": "Prove by induction that Σ r(r + 1) from r = 1 to n equals n(n + 1)(n + 2)/3.", "steps": ["n = 1: LHS = 2 and RHS = 1 × 2 × 3/3 = 2.", "Assume the sum to k is k(k + 1)(k + 2)/3.", "Sum to k + 1 = k(k + 1)(k + 2)/3 + (k + 1)(k + 2).", "= (k + 1)(k + 2)(k + 3)/3, taking out the common factor (k + 1)(k + 2)/3.", "This is the formula with n = k + 1; with the base case, it holds for all positive integers n."]}], "fills": [{"q": "Adding the next odd number.", "lines": ["k² + (2k + [[1]]) = (k + 1)²"]}, {"q": "Taking out a common factor.", "lines": ["k(k + 1)(k + 2)/3 + (k + 1)(k + 2) = (k + 1)(k + 2)(k + [[3]])/3"]}, {"q": "Setting up a divisibility step.", "lines": ["5ᵏ⁺¹ − 1 = 5(5ᵏ − 1) + [[4]]"]}], "exam": [{"stem": "", "parts": [{"q": "Prove by induction that, for all positive integers n, Σ r³ from r = 1 to n equals n²(n + 1)²/4.", "m": 6, "ms": [["B1", "n = 1: LHS = 1, RHS = 1 × 4/4 = 1"], ["M1", "assumes true for n = k and adds (k + 1)³"], ["M1", "takes out the factor (k + 1)²/4"], ["A1", "(k + 1)²(k² + 4k + 4)/4"], ["A1", "= (k + 1)²(k + 2)²/4, the result for n = k + 1"], ["A1", "complete conclusion: base case, inductive step, all positive integers"]]}]}, {"stem": "<p>f(n) = 4ⁿ + 6n − 1, where n is a positive integer.</p>", "parts": [{"q": "Find f(1) and f(2).", "m": 1, "ms": [["B1", "f(1) = 9 and f(2) = 27"]]}, {"q": "Prove by induction that f(n) is divisible by 9 for all positive integers n.", "m": 4, "ms": [["M1", "assumes f(k) = 9m and considers f(k + 1) = 4ᵏ⁺¹ + 6k + 5"], ["M1", "writes f(k + 1) = 4f(k) − 18k + 9"], ["A1", "= 9(4m − 2k + 1)"], ["A1", "conclusion using f(1) = 9 as the base case"]]}]}, {"stem": "<p>A sequence is defined by u₁ = 5 and uₙ₊₁ = 3uₙ − 4.</p>", "parts": [{"q": "Find u₂ and u₃.", "m": 1, "ms": [["B1", "u₂ = 11 and u₃ = 29"]]}, {"q": "Prove by induction that uₙ = 3ⁿ + 2.", "m": 4, "ms": [["B1", "n = 1: 3 + 2 = 5 = u₁"], ["M1", "assumes uₖ = 3ᵏ + 2 and substitutes into uₖ₊₁ = 3uₖ − 4"], ["A1", "uₖ₊₁ = 3ᵏ⁺¹ + 6 − 4 = 3ᵏ⁺¹ + 2"], ["A1", "complete conclusion"]]}]}]}}, {"id": "cp-complex", "module": "core", "title": "Complex arithmetic and polynomial roots", "refs": "2.1–2.3", "notes": ["The imaginary unit satisfies i² = −1. Combine real and imaginary parts separately in addition, and expand products before replacing i². To divide, multiply numerator and denominator by the conjugate of the denominator; the denominator becomes a real modulus squared.", "A polynomial with real coefficients has non-real roots in conjugate pairs. This conclusion depends on real coefficients: it is not true for an arbitrary complex-coefficient polynomial. A quadratic with negative discriminant still has two complex roots. Check a proposed root by substitution rather than by its appearance."], "example": {"q": "Solve z² − 4z + 13 = 0 and calculate the product of the roots.", "steps": ["Discriminant = 16 − 52 = −36.", "z = (4 ± 6i)/2 = 2 ± 3i.", "(2 + 3i)(2 − 3i) = 4 − 9i².", "The product is 13, agreeing with the constant term."]}, "practice": {"q": "Simplify (3 + 4i)/(1 − 2i), giving a + bi.", "answer": null, "steps": ["Multiply top and bottom by 1 + 2i.", "Numerator = 3 + 6i + 4i + 8i² = −5 + 10i.", "Denominator = 1 + 4 = 5.", "The result is −1 + 2i."]}, "check": {"q": "What is i²?", "a": -1}, "deep": {"tip": "Decide first whether the coefficients are real: only then do non-real roots come in conjugate pairs. When dividing, write the conjugate multiplication as a separate line so the real denominator is visible, and when finding square roots keep both sign choices until the final line.", "examples": [{"title": "Using a given complex root", "q": "Given that 1 + 2i is a root of z³ − 5z² + 11z − 15 = 0, solve the equation completely.", "steps": ["Real coefficients, so 1 − 2i is also a root.", "(z − 1 − 2i)(z − 1 + 2i) = z² − 2z + 5.", "z³ − 5z² + 11z − 15 = (z² − 2z + 5)(z − 3), comparing the z³ and constant terms.", "Check the z term: 6 + 5 = 11.", "The roots are 1 + 2i, 1 − 2i and 3."]}, {"title": "Square roots of a complex number", "q": "Find the square roots of 5 − 12i.", "steps": ["Let (a + bi)² = 5 − 12i with a, b real.", "Real and imaginary parts: a² − b² = 5 and 2ab = −12.", "Substituting b = −6/a gives a⁴ − 5a² − 36 = 0, so (a² − 9)(a² + 4) = 0.", "a is real, so a = ±3 and b = ∓2.", "The square roots are 3 − 2i and −3 + 2i."]}], "fills": [{"q": "Multiply.", "lines": ["(2 + 3i)(1 − i) = [[5]] + [[1]]i"]}, {"q": "Divide using the conjugate.", "lines": ["(4 + 2i)/(1 + i) = (4 + 2i)(1 − i)/[[2]] = [[3]] − i"]}, {"q": "z = 3 − 4i.", "lines": ["zz* = [[25]]"]}], "exam": [{"stem": "<p>f(z) = z⁴ − 6z³ + 23z² − 34z + 26. Given that 1 + i is a root of f(z) = 0:</p>", "parts": [{"q": "write down another complex root;", "m": 1, "ms": [["B1", "1 − i"]]}, {"q": "solve f(z) = 0 completely.", "m": 5, "ms": [["M1", "forms (z − 1 − i)(z − 1 + i)"], ["A1", "z² − 2z + 2"], ["M1", "divides or compares coefficients to find the other quadratic factor"], ["A1", "z² − 4z + 13"], ["A1", "z = 2 ± 3i (with 1 ± i)"]]}]}, {"stem": "<p>The complex number z satisfies (2 − i)z = 7 + 4i.</p>", "parts": [{"q": "Find z in the form a + bi.", "m": 3, "ms": [["M1", "multiplies numerator and denominator by 2 + i"], ["A1", "numerator 10 + 15i, denominator 5"], ["A1", "z = 2 + 3i"]]}, {"q": "z is a root of z² + pz + q = 0, where p and q are real. Find p and q.", "m": 2, "ms": [["M1", "uses the conjugate root 2 − 3i: sum 4, product 13"], ["A1", "p = −4, q = 13"]]}]}, {"stem": "", "parts": [{"q": "Find the square roots of −7 + 24i.", "m": 4, "ms": [["M1", "a² − b² = −7 and 2ab = 24"], ["M1", "eliminates to a⁴ + 7a² − 144 = 0"], ["A1", "a² = 9 (a² = −16 rejected)"], ["A1", "3 + 4i and −3 − 4i"]]}]}]}}, {"id": "cp-argand", "module": "core", "title": "Argand diagrams, loci and regions", "refs": "2.4, 2.7", "notes": ["An Argand point represents z = x + iy by coordinates (x,y). The distance |z − a| is the distance from the point for z to the point for a. Equality of distances gives a perpendicular bisector; a fixed distance gives a circle. An argument condition fixes a directed angle and usually describes a ray, not an entire line.", "Use an algebraic equation to check the geometry, and distinguish boundaries included by ≤ from boundaries excluded by <. The argument of zero is undefined, so a point making the argument expression zero is excluded. Intersections of regions must satisfy every original condition."], "example": {"q": "Describe |z − (2 + i)| = 3 and |z − 1| = |z + 3|.", "steps": ["The first locus is a circle with centre (2,1) and radius 3.", "For the second, points are equally far from (1,0) and (−3,0).", "The perpendicular bisector is x = −1.", "Algebra confirms (x − 1)² + y² = (x + 3)² + y² gives x = −1."]}, "practice": {"q": "Describe the locus |z − (1 − 2i)| = 4 and determine whether z = 1 + 2i lies on it.", "answer": null, "steps": ["Centre (1,−2), radius 4.", "At z = 1 + 2i the distance from the centre is 4.", "The point lies on the circle.", "A correct sketch labels both axes, centre and radius."]}, "check": {"q": "What is the radius of |z−(2+i)|=3?", "a": 3}, "deep": {"tip": "Translate each condition into geometry before any algebra: |z − a| is a distance from the point a, and arg(z − a) is a direction measured at a. Mark the fixed points first, state whether each boundary is included, and remember that a half-line from an arg condition does not include its starting point.", "examples": [{"title": "Greatest and least modulus on a circle", "q": "z satisfies |z − 3 − 4i| = 2. Find the least and greatest values of |z|.", "steps": ["The locus is a circle, centre (3, 4), radius 2.", "The centre is √(3² + 4²) = 5 from the origin.", "The nearest and farthest points lie on the line through the origin and the centre.", "Least |z| = 5 − 2 = 3; greatest |z| = 5 + 2 = 7."]}, {"title": "A half-line", "q": "Sketch the locus arg(z + 1 − i) = 3π/4 and give its Cartesian equation.", "steps": ["Write as arg(z − (−1 + i)) = 3π/4: a half-line starting at (−1, 1).", "The direction 3π/4 has gradient tan(3π/4) = −1 and points up and to the left.", "y − 1 = −(x + 1), so y = −x.", "The locus is y = −x for x < −1; the point (−1, 1) itself is excluded (open circle)."]}, {"title": "Area of a region", "q": "Find the area of the region defined by |z − 2| ≤ 2 and 0 ≤ arg z ≤ π/4.", "steps": ["The circle has centre (2, 0) and radius 2, so it passes through the origin; in polar form r = 4cos θ.", "The region is swept out from the origin for 0 ≤ θ ≤ π/4.", "Area = ½∫ 16cos²θ dθ = 4∫ (1 + cos 2θ) dθ from 0 to π/4.", "= 4[θ + ½ sin 2θ] = 4(π/4 + ½).", "Area = π + 2."]}], "fills": [{"q": "Read off the circle |z − 3 + 2i| = 5.", "lines": ["centre ([[3]], [[-2]]), radius [[5]]"]}, {"q": "Perpendicular bisector |z − 4| = |z + 2|.", "lines": ["the line x = [[1]]"]}, {"q": "Points on |z − 3 − 4i| = 2.", "lines": ["greatest |z| = 5 + 2 = [[7]]"]}], "exam": [{"stem": "<p>The complex number z satisfies |z + 2 − 2i| = √2.</p>", "parts": [{"q": "Describe the locus of z.", "m": 2, "ms": [["B1", "circle with centre (−2, 2)"], ["B1", "radius √2"]]}, {"q": "Find the greatest value of |z|.", "m": 2, "ms": [["M1", "distance of the centre from O is 2√2, then adds the radius"], ["A1", "3√2"]], "ans": {"a": 4.2426406871, "tol": 0.001, "unit": ""}}, {"q": "Find the greatest value of arg z, where −π &lt; arg z ≤ π.", "m": 3, "ms": [["M1", "uses the tangent from O: right angle between tangent and radius"], ["A1", "sin α = √2/(2√2), so α = π/6"], ["A1", "3π/4 + π/6 = 11π/12"]], "ans": {"a": 2.8797932658, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>The region R is defined by |z| ≤ 4 and π/6 ≤ arg z ≤ π/2.</p>", "parts": [{"q": "Find the exact area of R.", "m": 3, "ms": [["B1", "R is a sector of the circle centre O, radius 4"], ["M1", "½ × 4² × (π/2 − π/6)"], ["A1", "8π/3"]], "ans": {"a": 8.3775804096, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>The complex number z satisfies |z − 6| = |z − 2i|.</p>", "parts": [{"q": "Find a Cartesian equation of the locus of z.", "m": 3, "ms": [["M1", "(x − 6)² + y² = x² + (y − 2)²"], ["M1", "expands and simplifies: −12x + 36 = −4y + 4"], ["A1", "y = 3x − 8"]]}, {"q": "Find the least value of |z|.", "m": 2, "ms": [["M1", "perpendicular distance from O to 3x − y − 8 = 0"], ["A1", "8/√10 = 4√10/5"]], "ans": {"a": 2.5298221281, "tol": 0.001, "unit": ""}}]}]}}, {"id": "cp-exponential", "module": "core", "title": "Modulus, argument and exponential form", "refs": "2.5–2.6, 2.9", "notes": ["For z = x + iy, the modulus is √(x² + y²); choose the argument using the quadrant as well as a tangent ratio. Euler form z = re^(iθ) makes multiplication and division geometric: multiply or divide moduli and add or subtract arguments.", "Principal arguments are normally chosen in (−π,π]. Angles differing by 2π represent the same non-zero complex number. An exponential-form calculation must preserve the modulus; addition is generally easier in Cartesian form and does not add moduli and arguments separately."], "example": {"q": "Write −1 + i in exponential form and square it.", "steps": ["The modulus is √2.", "The point is in quadrant II, so arg z = 3π/4.", "z = √2 e^(3πi/4).", "z² = 2e^(3πi/2) = −2i; the principal argument is −π/2."]}, "practice": {"q": "Write −√3 − i in modulus-argument form.", "answer": null, "steps": ["Modulus = √(3 + 1) = 2.", "The point lies in quadrant III.", "A principal argument is −5π/6.", "z = 2[cos(−5π/6) + i sin(−5π/6)]."]}, "check": {"q": "What is the modulus of −3+4i?", "a": 5}, "deep": {"tip": "Plot the number before quoting an argument: the quadrant decides the angle, not the calculator value of arctan. Use exponential or modulus-argument form for products, quotients and powers, Cartesian form for sums, and bring every final argument back into (−π, π].", "examples": [{"title": "Products and quotients", "q": "z = 2e^(iπ/3) and w = 3e^(−iπ/4). Find zw and z/w in the form re^(iθ) with −π < θ ≤ π.", "steps": ["Multiply moduli and add arguments: zw = 6e^(i(π/3 − π/4)).", "zw = 6e^(iπ/12).", "Divide moduli and subtract arguments: z/w = (2/3)e^(i(π/3 + π/4)).", "z/w = (2/3)e^(7πi/12)."]}, {"title": "A power in Cartesian form", "q": "Find (1 + i√3)⁶ in the form a + bi.", "steps": ["|1 + i√3| = 2 and the point is in the first quadrant with arg = π/3.", "1 + i√3 = 2e^(iπ/3).", "(2e^(iπ/3))⁶ = 2⁶ e^(2πi).", "e^(2πi) = 1, so (1 + i√3)⁶ = 64."]}], "fills": [{"q": "Modulus.", "lines": ["|−5 + 12i| = [[13]]"]}, {"q": "Argument of a point on the negative imaginary axis.", "lines": ["arg(−2i) = −π/[[2]]"]}, {"q": "Euler.", "lines": ["e^(iπ) = [[-1]]"]}], "exam": [{"stem": "<p>z = −2 + 2√3 i.</p>", "parts": [{"q": "Find the modulus and the argument of z.", "m": 3, "ms": [["B1", "|z| = 4"], ["M1", "uses arctan(√3) with z in the second quadrant"], ["A1", "arg z = 2π/3"]]}, {"q": "Find z⁴ in the form a + bi.", "m": 3, "ms": [["M1", "4⁴ e^(8πi/3)"], ["M1", "reduces the argument to 2π/3"], ["A1", "−128 + 128√3 i"]]}]}, {"stem": "<p>z = 4(cos π/6 + i sin π/6) and w = 2(cos(−π/3) + i sin(−π/3)).</p>", "parts": [{"q": "Find zw in modulus-argument form.", "m": 2, "ms": [["M1", "multiplies moduli and adds arguments"], ["A1", "8(cos(−π/6) + i sin(−π/6))"]]}, {"q": "Find z/w in the form a + bi.", "m": 3, "ms": [["M1", "modulus 4 ÷ 2 = 2"], ["M1", "argument π/6 + π/3 = π/2"], ["A1", "2i"]]}]}, {"stem": "<p>w = (1 + i)/(√3 − i).</p>", "parts": [{"q": "Find |w| and arg w, giving exact answers.", "m": 4, "ms": [["B1", "|1 + i| = √2 with argument π/4"], ["B1", "|√3 − i| = 2 with argument −π/6"], ["M1", "divides the moduli and subtracts the arguments"], ["A1", "|w| = √2/2 and arg w = 5π/12"]]}]}]}}, {"id": "cp-demoivre", "module": "core", "title": "De Moivre, roots of unity and trigonometric identities", "refs": "2.8, 2.10–2.11", "notes": ["For an integer n, [r(cosθ + i sinθ)]ⁿ = rⁿ(cos nθ + i sin nθ). To find all nth roots, use every angle (θ + 2kπ)/n for k = 0,…,n − 1. These points are equally spaced on a circle, and omitting the 2kπ term loses roots.", "Expand (cosθ + i sinθ)ⁿ and compare real and imaginary parts to derive identities. For powers of sine and cosine, Euler forms convert products to sums of exponentials; pair conjugate terms to obtain a real result. Check the number of distinct roots and the modulus of each."], "example": {"q": "Find all cube roots of 8.", "steps": ["Write 8 = 8e^(2kπi).", "Each cube root has modulus 2 and angle 2kπ/3.", "For k = 0,1,2, the roots are 2, −1 + √3 i, −1 − √3 i.", "Cubing each gives 8; the roots are 120° apart."]}, "practice": {"q": "Find all fourth roots of −16.", "answer": null, "steps": ["Write −16 = 16e^((π+2kπ)i).", "The root modulus is 2.", "Angles are π/4, 3π/4, 5π/4 and 7π/4.", "The roots are ±√2 ± √2 i, with all four sign combinations.", "Plot four equally spaced points on the circle of radius 2."]}, "check": {"q": "How many distinct fifth roots does a non-zero complex number have?", "a": 5}, "deep": {"tip": "For roots, write the right-hand side with its general argument θ + 2kπ before dividing by n, and list exactly n values of k. For identities, decide whether you need real or imaginary parts before expanding, and convert everything to one trigonometric function at the end.", "examples": [{"title": "A multiple-angle identity", "q": "Use de Moivre’s theorem to show that cos 3θ = 4cos³θ − 3cos θ.", "steps": ["(cos θ + i sin θ)³ = cos 3θ + i sin 3θ.", "Expanding with c = cos θ, s = sin θ: c³ + 3ic²s − 3cs² − is³.", "Equate real parts: cos 3θ = c³ − 3cs².", "Replace s² by 1 − c²: cos 3θ = c³ − 3c(1 − c²).", "cos 3θ = 4cos³θ − 3cos θ."]}, {"title": "Fourth roots", "q": "Solve z⁴ = 8 + 8√3 i, giving the roots in the form re^(iθ) with −π < θ ≤ π.", "steps": ["|8 + 8√3 i| = 16 and the argument is π/3.", "z⁴ = 16e^(i(π/3 + 2kπ)).", "z = 2e^(i(π/12 + kπ/2)) for k = 0, 1, −1, −2.", "z = 2e^(iπ/12), 2e^(7πi/12), 2e^(−5πi/12), 2e^(−11πi/12)."]}, {"title": "A power of sine", "q": "Express sin⁴θ in terms of cos 4θ and cos 2θ.", "steps": ["With z = e^(iθ): z − 1/z = 2i sin θ and zⁿ + 1/zⁿ = 2cos nθ.", "(2i sin θ)⁴ = z⁴ − 4z² + 6 − 4/z² + 1/z⁴.", "16 sin⁴θ = (z⁴ + 1/z⁴) − 4(z² + 1/z²) + 6 = 2cos 4θ − 8cos 2θ + 6.", "sin⁴θ = (cos 4θ − 4cos 2θ + 3)/8."]}], "fills": [{"q": "De Moivre.", "lines": ["(cos θ + i sin θ)⁵ = cos [[5]]θ + i sin [[5]]θ"]}, {"q": "Roots of unity.", "lines": ["the sum of the n distinct nth roots of unity is [[0]]"]}, {"q": "Cube roots of 27.", "lines": ["each root has modulus [[3]]"]}], "exam": [{"stem": "", "parts": [{"q": "Use de Moivre’s theorem to show that sin 5θ = 16sin⁵θ − 20sin³θ + 5sin θ.", "m": 5, "ms": [["M1", "expands (c + is)⁵ with the binomial theorem"], ["M1", "takes imaginary parts: 5c⁴s − 10c²s³ + s⁵"], ["M1", "replaces c² by 1 − s²"], ["A1", "5s(1 − 2s² + s⁴) − 10s³(1 − s²) + s⁵"], ["A1", "16s⁵ − 20s³ + 5s"]]}, {"q": "Hence find all the solutions of 16x⁵ − 20x³ + 5x = 0, giving non-zero roots to 3 decimal places.", "m": 3, "ms": [["M1", "sets x = sin θ and solves sin 5θ = 0"], ["A1", "θ = kπ/5"], ["A1", "x = 0, ±0.588, ±0.951"]]}]}, {"stem": "", "parts": [{"q": "Solve z³ = −8i, giving the roots in the form re^(iθ) with −π &lt; θ ≤ π.", "m": 4, "ms": [["B1", "modulus 2"], ["M1", "arguments (−π/2 + 2kπ)/3"], ["A1", "2e^(−iπ/6)"], ["A1", "2e^(iπ/2) and 2e^(−5πi/6)"]]}, {"q": "The roots are the vertices of a triangle in the Argand diagram. Find its exact area.", "m": 2, "ms": [["M1", "equilateral triangle inscribed in a circle of radius 2: side 2√3"], ["A1", "3√3"]], "ans": {"a": 5.1961524227, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>ω = e^(2πi/5).</p>", "parts": [{"q": "Show that 1 + ω + ω² + ω³ + ω⁴ = 0.", "m": 2, "ms": [["M1", "geometric series: (ω⁵ − 1)/(ω − 1)"], ["A1", "ω⁵ = 1 and ω ≠ 1, so the sum is 0"]]}, {"q": "Hence find the exact value of cos(2π/5) + cos(4π/5).", "m": 2, "ms": [["M1", "takes real parts: 1 + 2cos(2π/5) + 2cos(4π/5) = 0"], ["A1", "−½"]], "ans": {"a": -0.5, "tol": 0.001, "unit": ""}}]}]}}, {"id": "cp-matrix", "module": "core", "title": "Matrix multiplication, determinants and inverses", "refs": "3.1–3.2, 3.5–3.6", "notes": ["A matrix product is defined only when the inner dimensions agree. Each entry is a row–column dot product, so AB and BA need not agree. The determinant of a 2×2 matrix [[a,b],[c,d]] is ad − bc; an inverse exists only when this is non-zero.", "For a 3×3 determinant, expand along a convenient row or column with alternating cofactor signs. Transpose the cofactor matrix to form the adjugate, then divide by the determinant. Check an inverse by multiplying to obtain I; a singular matrix cannot be rescued by dividing by zero."], "example": {"q": "Find the inverse of A = [[2,1],[3,2]].", "steps": ["det A = 4 − 3 = 1.", "Swap diagonal entries and negate the other two.", "A⁻¹ = [[2,−1],[−3,2]].", "Multiplying AA⁻¹ gives [[1,0],[0,1]]."]}, "practice": {"q": "Find the determinant and inverse of B = [[3,1],[2,1]].", "answer": null, "steps": ["det B = 3 − 2 = 1.", "B⁻¹ = [[1,−1],[−2,3]].", "Check BB⁻¹ = I.", "State that the non-zero determinant guarantees an inverse."]}, "check": {"q": "Find det([[2,1],[3,2]]).", "a": 1}, "deep": {"tip": "Check that the dimensions allow the product and keep the order: AB ≠ BA in general and (AB)⁻¹ = B⁻¹A⁻¹. For a 3 × 3 inverse, lay out minors, then cofactor signs, then the transpose, and confirm one row of AA⁻¹ before using the result.", "examples": [{"title": "A singular 3 × 3 matrix", "q": "A = [[1,2,0],[3,−1,2],[1,0,k]]. Find the value of k for which A is singular.", "steps": ["Expand along the first row: det A = 1(−k − 0) − 2(3k − 2) + 0.", "det A = −k − 6k + 4 = 4 − 7k.", "A is singular when det A = 0.", "k = 4/7."]}, {"title": "Inverse of a 3 × 3 matrix", "q": "Find the inverse of M = [[2,0,1],[1,1,0],[0,1,1]].", "steps": ["det M = 2(1 − 0) − 0 + 1(1 − 0) = 3.", "Matrix of minors: [[1,1,1],[−1,2,2],[−1,−1,2]].", "Apply the alternating signs: cofactors [[1,−1,1],[1,2,−2],[−1,1,2]].", "Transpose and divide by 3: M⁻¹ = ⅓[[1,1,−1],[−1,2,1],[1,−2,2]].", "Check the first row of MM⁻¹: ⅓(2 + 1, 2 − 2, −2 + 2) = (1, 0, 0)."]}], "fills": [{"q": "A 2 × 2 determinant.", "lines": ["det [[4,3],[2,5]] = 20 − 6 = [[14]]"]}, {"q": "Determinant of a product, with det A = 3 and det B = −2.", "lines": ["det(AB) = [[-6]]"]}, {"q": "Matrix times a column vector.", "lines": ["[[1,2],[3,4]] (2, 1)ᵀ = ([[4]], [[10]])ᵀ"]}], "exam": [{"stem": "<p>M = [[k,2],[3,k − 1]], where k is a constant.</p>", "parts": [{"q": "Find the values of k for which M is singular.", "m": 3, "ms": [["M1", "det M = k(k − 1) − 6"], ["M1", "solves k² − k − 6 = 0"], ["A1", "k = 3 or k = −2"]]}, {"q": "Given that k = 4, find M⁻¹.", "m": 2, "ms": [["M1", "det M = 6 and swaps/negates the entries"], ["A1", "⅙[[3,−2],[−3,4]]"]]}]}, {"stem": "<p>A = [[1,0,2],[2,1,0],[0,3,1]].</p>", "parts": [{"q": "Find det A.", "m": 2, "ms": [["M1", "1(1 − 0) − 0 + 2(6 − 0)"], ["A1", "13"]], "ans": {"a": 13.0, "tol": 0.001, "unit": ""}}, {"q": "Find A⁻¹.", "m": 4, "ms": [["M1", "finds the matrix of minors"], ["M1", "applies the cofactor signs"], ["M1", "transposes and divides by det A"], ["A1", "(1/13)[[1,6,−2],[−2,1,4],[6,−3,1]]"]]}, {"q": "Hence solve x + 2z = 5, 2x + y = 4, 3y + z = 8.", "m": 2, "ms": [["M1", "multiplies A⁻¹ by (5, 4, 8)ᵀ"], ["A1", "x = 1, y = 2, z = 2"]]}]}, {"stem": "<p>A = [[2,1],[5,3]] and AB = [[4,1],[11,2]].</p>", "parts": [{"q": "Find the matrix B.", "m": 3, "ms": [["B1", "det A = 1, so A⁻¹ = [[3,−1],[−5,2]]"], ["M1", "B = A⁻¹(AB), multiplying on the left"], ["A1", "B = [[1,1],[2,−1]]"]]}]}]}}, {"id": "cp-transform", "module": "core", "title": "Linear transformations and invariant objects", "refs": "3.3–3.4", "notes": ["The columns of a 2D transformation matrix are the images of the standard basis vectors. If B acts first and A second, the composite matrix is AB. A determinant gives signed area scale factor: its magnitude scales area and its sign records orientation.", "An invariant point satisfies Mx = x. A line can be invariant without every point on it being fixed. To test a proposed invariant line, transform a general point on the line and check that its image still satisfies the line equation. Rotations, reflections, stretches and shears should be interpreted geometrically as well as algebraically."], "example": {"q": "For M = [[1,2],[0,1]], describe the transformation and find its invariant points.", "steps": ["(x,y) maps to (x + 2y,y).", "This is a shear parallel to the x-axis, with shear factor 2.", "Invariant points satisfy x + 2y = x, so y = 0.", "Every point on the x-axis is fixed; det M = 1 preserves area."]}, "practice": {"q": "A maps (x,y) to (−y,x). Write A and find A².", "answer": null, "steps": ["Images of (1,0) and (0,1) are (0,1) and (−1,0).", "A = [[0,−1],[1,0]].", "A² = [[−1,0],[0,−1]].", "These represent anticlockwise 90° and 180° rotations about the origin."]}, "check": {"q": "For the shear (x,y)↦(x+2y,y), find the first coordinate of the image of (1,3).", "a": 7}, "deep": {"tip": "Read a matrix through its columns, the images of (1, 0) and (0, 1), and write composites right to left: the first transformation is the right-hand factor. For an invariant line, transform a general point (t, mt + c) and require the image to satisfy the same equation; do not confuse this with a line of invariant points.", "examples": [{"title": "Invariant lines through the origin", "q": "Find the invariant lines through the origin for M = [[4,−2],[1,1]].", "steps": ["A general point on y = mx is (t, mt); its image is (4t − 2mt, t + mt).", "The image lies on y = mx when t + mt = m(4t − 2mt).", "1 + m = 4m − 2m², so 2m² − 3m + 1 = 0.", "(2m − 1)(m − 1) = 0, giving m = ½ or m = 1.", "The invariant lines are y = ½x and y = x."]}, {"title": "A composite transformation", "q": "R is a rotation of 90° anticlockwise about O and S is a reflection in y = x. Find the single transformation equivalent to R followed by S.", "steps": ["R = [[0,−1],[1,0]] and S = [[0,1],[1,0]].", "R followed by S is the product SR.", "SR = [[0,1],[1,0]][[0,−1],[1,0]] = [[1,0],[0,−1]].", "This is a reflection in the x-axis."]}, {"title": "Area scale factor", "q": "A triangle of area 5 is transformed by [[3,1],[2,4]]. Find the area of its image.", "steps": ["det = 3 × 4 − 1 × 2 = 10.", "The area scale factor is |det| = 10.", "Image area = 5 × 10 = 50; the positive determinant means orientation is preserved."]}], "fills": [{"q": "Area scale factor of [[3,1],[2,4]].", "lines": ["det = [[10]]"]}, {"q": "Rotation of 180° about O.", "lines": ["the matrix is [[−1,0],[0,[[-1]]]]"]}, {"q": "Enlargement, scale factor 3, centre O.", "lines": ["determinant = [[9]]"]}], "exam": [{"stem": "<p>A = (1/√2)[[1,−1],[1,1]] and B = [[1,0],[0,−1]].</p>", "parts": [{"q": "Describe fully the transformation represented by A.", "m": 2, "ms": [["B1", "rotation about the origin"], ["B1", "45° anticlockwise"]]}, {"q": "Explain why A⁸ = I.", "m": 1, "ms": [["B1", "eight rotations of 45° make a full turn of 360°"]]}, {"q": "Find the matrix representing A followed by B.", "m": 2, "ms": [["M1", "forms the product BA"], ["A1", "(1/√2)[[1,−1],[−1,−1]]"]]}]}, {"stem": "<p>T = [[3,2],[1,4]].</p>", "parts": [{"q": "Show that the line y = x is invariant under T.", "m": 2, "ms": [["M1", "image of (t, t) is (5t, 5t)"], ["A1", "the image lies on y = x, so the line maps to itself"]]}, {"q": "Find the other invariant line through the origin.", "m": 4, "ms": [["M1", "image of (t, mt) is (3t + 2mt, t + 4mt)"], ["M1", "requires t + 4mt = m(3t + 2mt)"], ["A1", "2m² − m − 1 = 0"], ["A1", "y = −½x"]]}, {"q": "State, with a reason, whether y = x is a line of invariant points.", "m": 1, "ms": [["B1", "no: (t, t) maps to (5t, 5t), so only the origin is fixed"]]}]}, {"stem": "", "parts": [{"q": "The triangle with vertices (0, 0), (4, 0) and (0, 3) is transformed by [[2,−1],[3,5]]. Find the area of the image.", "m": 3, "ms": [["B1", "original area 6"], ["M1", "det = 10 + 3 = 13"], ["A1", "78"]], "ans": {"a": 78.0, "tol": 0.001, "unit": ""}}]}]}}, {"id": "cp-systems", "module": "core", "title": "Three-equation systems and singular geometry", "refs": "3.7–3.8", "notes": ["Write a linear system as Ax = b and use elimination or a matrix inverse when available. A zero determinant means a unique solution is not guaranteed: the system may be inconsistent or may have infinitely many solutions. Compare augmented rows to distinguish these cases.", "In three dimensions, each linear equation represents a plane. Three planes may meet at one point, share a line or plane, or have no common point. A determinant calculation alone does not distinguish an empty intersection from a non-unique intersection; interpret the equations and any free parameter."], "example": {"q": "Solve x + y + z = 6, x − y + z = 2, and 2x + y − z = 3.", "steps": ["Subtract the second equation from the first: 2y = 4, so y = 2.", "The first gives x + z = 4.", "The third gives 2x − z = 1.", "Adding gives 3x = 5: x = 5/3 and z = 7/3.", "Substitute all three values in the original equations."]}, "practice": {"q": "Explain the solution set of x + y + z = 2 and 2x + 2y + 2z = 5.", "answer": null, "steps": ["Doubling the first equation requires 2x + 2y + 2z = 4.", "This contradicts the second equation.", "There is no common solution.", "The planes are parallel and distinct."]}, "check": {"q": "If x+y+z=6 and x−y+z=2, what is y?", "a": 2}, "deep": {"tip": "Find the determinant first: non-zero means one point, zero means you must test consistency. When the determinant is zero, combine the equations to see whether they agree (a line or plane of solutions) or contradict (no common point), and name the configuration: sheaf, prism, or parallel planes.", "examples": [{"title": "A parameter and a sheaf", "q": "x + 2y − z = 3, 2x − y + 3z = 4 and 3x + y + 2z = k. Find k for which the equations are consistent and interpret the result.", "steps": ["The left side of the third equation is the sum of the first two left sides.", "So the coefficient determinant is 0: there is no unique solution.", "Adding the first two equations gives 3x + y + 2z = 7.", "The system is consistent only when k = 7.", "For k = 7 the three planes form a sheaf, meeting in a line; otherwise they form a triangular prism with no common point."]}, {"title": "A unique solution by elimination", "q": "Solve 2x + y − z = 1, x − y + 2z = 5 and 3x + 2y + z = 10.", "steps": ["Add the first two equations: 3x + z = 6.", "Twice the second plus the third: 5x + 5z = 20, so x + z = 4.", "Subtract: 2x = 2, so x = 1 and z = 3.", "From the first equation y = 1 − 2 + 3 = 2.", "(x, y, z) = (1, 2, 3); check in the third: 3 + 4 + 3 = 10."]}], "fills": [{"q": "Two equations: x + y = 5 and x − y = 1.", "lines": ["x = [[3]] and y = [[2]]"]}, {"q": "A singular 2 × 2 matrix.", "lines": ["det [[1,2],[2,4]] = [[0]]"]}, {"q": "The planes x + y + z = 1 and x + y + z = 4.", "lines": ["number of common points = [[0]]"]}], "exam": [{"stem": "<p>The equations x + y + 2z = 4, 2x − y + z = 3 and 3x + az = b are given, where a and b are constants.</p>", "parts": [{"q": "Find the determinant of the coefficient matrix in terms of a.", "m": 2, "ms": [["M1", "expands a 3 × 3 determinant"], ["A1", "9 − 3a"]]}, {"q": "State the value of a for which there is no unique solution.", "m": 1, "ms": [["B1", "a = 3"]]}, {"q": "Given a = 3 and b = 7, show that the equations are consistent and interpret this geometrically.", "m": 3, "ms": [["M1", "adds the first two equations: 3x + 3z = 7"], ["A1", "this is the third equation, so the system is consistent"], ["B1", "the three planes form a sheaf: they meet in a line"]]}]}, {"stem": "", "parts": [{"q": "Solve the simultaneous equations x + y + z = 6, 2x − y + 3z = 9 and x + 2y − z = 2.", "m": 4, "ms": [["M1", "eliminates one variable from two pairs of equations"], ["M1", "solves the resulting pair"], ["A1", "one correct value"], ["A1", "x = 1, y = 2, z = 3"]]}]}, {"stem": "<p>Π₁: x − 2y + z = 3, Π₂: 2x − 4y + 2z = 1 and Π₃: x + y − z = 0.</p>", "parts": [{"q": "Describe the configuration of the three planes.", "m": 2, "ms": [["B1", "Π₁ and Π₂ are parallel and distinct: normals proportional, constants not"], ["B1", "no common point; Π₃ cuts them in two parallel lines"]]}]}]}}, {"id": "cp-roots", "module": "core", "title": "Polynomial roots and transformations of roots", "refs": "4.1–4.2", "notes": ["For a monic cubic with roots α, β, γ, the coefficients give α+β+γ, αβ+βγ+γα and αβγ with alternating signs. Use these relations to build a polynomial or evaluate symmetric expressions without solving the original equation.", "If new roots are a transformation of the old ones, introduce a new variable and substitute its inverse relation into the original polynomial. Clear denominators and check degree and leading coefficient. Squaring a sum includes cross terms; Σα² is not (Σα)²."], "example": {"q": "Roots α,β,γ satisfy x³ − 6x² + 11x − 6 = 0. Find α² + β² + γ².", "steps": ["α + β + γ = 6.", "αβ + βγ + γα = 11.", "The sum of squares is 6² − 2×11.", "The result is 14."]}, "practice": {"q": "Find a monic polynomial whose roots are twice the roots of x³ − 3x + 1 = 0.", "answer": null, "steps": ["Let y = 2x, so x = y/2.", "Substitute: y³/8 − 3y/2 + 1 = 0.", "Multiply by 8: y³ − 12y + 8 = 0.", "The degree and number of roots are unchanged."]}, "check": {"q": "For roots of x³−6x²+11x−6=0, what is their sum?", "a": 6}, "deep": {"tip": "Write the equation with its leading coefficient visible before quoting sums and products, since each is divided by that coefficient and the signs alternate. For a transformed equation, substitute the inverse relationship and clear fractions; for powers of roots, use the equation itself to reduce α³ rather than expanding brackets.", "examples": [{"title": "Symmetric functions of a cubic", "q": "α, β, γ are the roots of 2x³ − 5x² + 4x − 3 = 0. Find Σ1/α and Σα².", "steps": ["Σα = 5/2, Σαβ = 4/2 = 2 and αβγ = 3/2.", "Σ1/α = Σαβ/αβγ = 2 ÷ 3/2.", "Σ1/α = 4/3.", "Σα² = (Σα)² − 2Σαβ = 25/4 − 4.", "Σα² = 9/4."]}, {"title": "A linear transformation of the roots", "q": "The roots of x³ − 3x² + 4 = 0 are α, β, γ. Find the cubic with roots α + 2, β + 2, γ + 2.", "steps": ["Let w = x + 2, so x = w − 2.", "(w − 2)³ − 3(w − 2)² + 4 = 0.", "w³ − 6w² + 12w − 8 − 3w² + 12w − 12 + 4 = 0.", "w³ − 9w² + 24w − 16 = 0.", "Check: the sum of the new roots is 3 + 6 = 9, matching the w² coefficient."]}, {"title": "What a sum of squares can show", "q": "α, β, γ, δ are the roots of x⁴ − 2x³ + 3x² + 4x − 5 = 0. Find Σα² and explain what it shows.", "steps": ["Σα = 2 and Σαβ = 3.", "Σα² = (Σα)² − 2Σαβ = 4 − 6.", "Σα² = −2.", "A sum of squares of real numbers cannot be negative, so the roots are not all real."]}], "fills": [{"q": "For x³ − 7x² + 2x + 5 = 0.", "lines": ["Σα = [[7]] and αβγ = [[-5]]"]}, {"q": "Sum of squares.", "lines": ["Σα² = (Σα)² − [[2]]Σαβ"]}, {"q": "New roots 3α.", "lines": ["substitute x = w/[[3]]"]}], "exam": [{"stem": "<p>The roots of x³ + 2x² − 3x + 4 = 0 are α, β and γ.</p>", "parts": [{"q": "Write down the values of α + β + γ, αβ + βγ + γα and αβγ.", "m": 2, "ms": [["B1", "two correct"], ["B1", "−2, −3 and −4"]]}, {"q": "Find α² + β² + γ².", "m": 2, "ms": [["M1", "(−2)² − 2(−3)"], ["A1", "10"]], "ans": {"a": 10.0, "tol": 0.001, "unit": ""}}, {"q": "Find α³ + β³ + γ³.", "m": 3, "ms": [["M1", "uses α³ = −2α² + 3α − 4 for each root"], ["M1", "−2(10) + 3(−2) − 12"], ["A1", "−38"]], "ans": {"a": -38.0, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>The roots of x³ − 4x² + x + 6 = 0 are α, β and γ.</p>", "parts": [{"q": "Find a cubic equation with integer coefficients whose roots are 2α − 1, 2β − 1 and 2γ − 1.", "m": 4, "ms": [["M1", "substitutes x = (w + 1)/2"], ["M1", "multiplies through by 8 and expands"], ["A1", "at least three correct coefficients"], ["A1", "w³ − 5w² − 9w + 45 = 0"]]}]}, {"stem": "<p>The roots of 2x² − 6x + 7 = 0 are α and β.</p>", "parts": [{"q": "Find a quadratic equation with integer coefficients whose roots are α² and β².", "m": 4, "ms": [["B1", "α + β = 3 and αβ = 7/2"], ["M1", "α² + β² = 9 − 7 = 2"], ["M1", "α²β² = 49/4"], ["A1", "4x² − 8x + 49 = 0"]]}]}]}}, {"id": "cp-series", "module": "core", "title": "Power sums and the method of differences", "refs": "4.3–4.4", "notes": ["Use standard sums of r, r² and r³ to simplify a polynomial term before summing. The method of differences works by expressing a term as consecutive differences; nearly all interior terms then cancel. Write the first few and last few terms so the uncancelled endpoints are visible.", "Partial fractions can reveal a telescoping form. A finite identity and an infinite sum are different statements: to pass to infinity, show that the remaining endpoint tends to a finite limit. Keep the starting index consistent."], "example": {"q": "Find the sum from r = 1 to n of 1/[r(r + 1)].", "steps": ["1/[r(r + 1)] = 1/r − 1/(r + 1).", "The sum is (1 − 1/2) + (1/2 − 1/3) + … + (1/n − 1/(n + 1)).", "Everything cancels except 1 − 1/(n + 1).", "The sum is n/(n + 1); its limit is 1."]}, "practice": {"q": "Find the sum from r = 1 to n of 2r² + 3r.", "answer": null, "steps": ["Use Σr² = n(n+1)(2n+1)/6.", "Use Σr = n(n+1)/2.", "The result is n(n+1)(4n+11)/6.", "Check n = 1: the result is 5."]}, "check": {"q": "Find Σr from r=1 to 10.", "a": 55}, "deep": {"tip": "Split a polynomial summand into standard sums and factorise as early as possible: n(n + 1) is almost always a common factor. For the method of differences, write out the first two and last two rows so the cancelling pattern is visible, and check the final formula with n = 1.", "examples": [{"title": "Standard results", "q": "Show that Σ r(2r − 1) from r = 1 to n equals n(n + 1)(4n − 1)/6.", "steps": ["Σ r(2r − 1) = 2Σr² − Σr.", "= 2n(n + 1)(2n + 1)/6 − n(n + 1)/2.", "= n(n + 1)[2(2n + 1) − 3]/6.", "= n(n + 1)(4n − 1)/6; check n = 1: 1 × 2 × 3/6 = 1."]}, {"title": "Method of differences", "q": "Find Σ 2/[(2r − 1)(2r + 1)] from r = 1 to n.", "steps": ["2/[(2r − 1)(2r + 1)] = 1/(2r − 1) − 1/(2r + 1).", "r = 1: 1 − 1/3; r = 2: 1/3 − 1/5; … ; r = n: 1/(2n − 1) − 1/(2n + 1).", "All the middle terms cancel.", "Sum = 1 − 1/(2n + 1) = 2n/(2n + 1)."]}, {"title": "A sum that does not start at 1", "q": "Find Σ r² from r = n + 1 to 2n in factorised form.", "steps": ["Sum = S(2n) − S(n), where S(n) = n(n + 1)(2n + 1)/6.", "= 2n(2n + 1)(4n + 1)/6 − n(n + 1)(2n + 1)/6.", "= n(2n + 1)[2(4n + 1) − (n + 1)]/6.", "= n(2n + 1)(7n + 1)/6."]}], "fills": [{"q": "Sum of the first 20 integers.", "lines": ["Σr = ½ × 20 × 21 = [[210]]"]}, {"q": "Sum of the first 10 squares.", "lines": ["Σr² = 10 × 11 × 21/6 = [[385]]"]}, {"q": "Sum of the first 5 cubes.", "lines": ["Σr³ = ¼ × 25 × 36 = [[225]]"]}], "exam": [{"stem": "", "parts": [{"q": "Show that Σ r(r + 3) from r = 1 to n equals n(n + 1)(n + 5)/3.", "m": 4, "ms": [["M1", "splits into Σr² + 3Σr"], ["M1", "substitutes both standard results"], ["M1", "takes out the factor n(n + 1)/6"], ["A1", "n(n + 1)(2n + 10)/6 = n(n + 1)(n + 5)/3"]]}, {"q": "Hence evaluate Σ r(r + 3) from r = 11 to 30.", "m": 2, "ms": [["M1", "S(30) − S(10) = 10 850 − 550"], ["A1", "10 300"]], "ans": {"a": 10300.0, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Express 1/[r(r + 2)] in partial fractions.", "m": 2, "ms": [["M1", "A/r + B/(r + 2)"], ["A1", "½[1/r − 1/(r + 2)]"]]}, {"q": "Hence show that Σ 1/[r(r + 2)] from r = 1 to n equals ¾ − (2n + 3)/[2(n + 1)(n + 2)].", "m": 4, "ms": [["M1", "writes out the first and last terms"], ["M1", "identifies the terms that do not cancel"], ["A1", "½[1 + ½ − 1/(n + 1) − 1/(n + 2)]"], ["A1", "combines to the given form"]]}, {"q": "State the sum to infinity.", "m": 1, "ms": [["B1", "¾"]], "ans": {"a": 0.75, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Show that Σ (r³ − r) from r = 1 to n equals ¼(n − 1)n(n + 1)(n + 2).", "m": 3, "ms": [["M1", "¼n²(n + 1)² − ½n(n + 1)"], ["M1", "takes out ¼n(n + 1): n(n + 1)(n² + n − 2)/4"], ["A1", "factorises n² + n − 2 = (n − 1)(n + 2)"]]}]}]}}, {"id": "cp-maclaurin", "module": "core", "title": "Maclaurin expansions and approximation", "refs": "4.5–4.6", "notes": ["A Maclaurin expansion uses derivatives at zero: f(0)+f′(0)x+f″(0)x²/2!+… . Recognise the expansions of eˣ, sin x, cos x and ln(1+x), and substitute a complete expression carefully into a known series. Calculate derivatives through the requested order before evaluating them at zero.", "A truncated series approximates a function near its expansion point. State the terms retained and any domain or convergence restriction. Terms with the same power must be collected after multiplying series, and powers discarded only after all products contributing to the requested order have been included."], "example": {"q": "Expand e^(2x) through the x³ term.", "steps": ["Use eᵘ = 1 + u + u²/2 + u³/6 + … .", "Substitute u = 2x.", "e^(2x) = 1 + 2x + 2x² + (4/3)x³ + … .", "At x = 0.05, the cubic approximation is 1.105166… ."]}, "practice": {"q": "Expand sin(2x) through the x⁵ term.", "answer": null, "steps": ["Use sin u = u − u³/6 + u⁵/120 + … .", "Substitute u = 2x.", "sin(2x) = 2x − (4/3)x³ + (4/15)x⁵ + … .", "The approximation is local to x = 0."]}, "check": {"q": "What is the coefficient of x³ in the Maclaurin expansion of e^(2x)?", "a": 1.3333333333333333}, "deep": {"tip": "Decide whether to differentiate repeatedly or to build the series from standard results: a composite of standard functions is usually quicker by substitution. Keep terms only up to the required power when multiplying, and quote the interval of validity when a logarithm or binomial series is involved.", "examples": [{"title": "A logarithmic series", "q": "Find the Maclaurin series for ln(1 + 2x) up to the term in x³, stating the values of x for which it is valid.", "steps": ["ln(1 + u) = u − u²/2 + u³/3 − …, valid for −1 < u ≤ 1.", "Replace u by 2x: 2x − (2x)²/2 + (2x)³/3.", "ln(1 + 2x) = 2x − 2x² + (8/3)x³ − …", "Valid when −1 < 2x ≤ 1, that is −½ < x ≤ ½."]}, {"title": "Multiplying two series", "q": "Find the series expansion of eˣ cos x up to the term in x³.", "steps": ["eˣ = 1 + x + x²/2 + x³/6 + … and cos x = 1 − x²/2 + …", "Multiply, keeping terms up to x³: (1 + x + x²/2 + x³/6) − x²/2 − x³/2.", "The x² terms cancel; x³: 1/6 − 1/2 = −1/3.", "eˣ cos x = 1 + x − x³/3 + …"]}, {"title": "A limit from a series", "q": "Use a series expansion to find the limit of (1 − cos 2x)/x² as x → 0.", "steps": ["cos 2x = 1 − (2x)²/2 + (2x)⁴/24 − …", "1 − cos 2x = 2x² − (2/3)x⁴ + …", "(1 − cos 2x)/x² = 2 − (2/3)x² + …", "As x → 0 the limit is 2."]}], "fills": [{"q": "The x² coefficient in e^(3x).", "lines": ["3²/2! = [[4.5]]"]}, {"q": "The first two terms of sin x.", "lines": ["sin x ≈ x − x³/[[6]]"]}, {"q": "Validity of ln(1 + x).", "lines": ["−1 < x ≤ [[1]]"]}], "exam": [{"stem": "<p>f(x) = ln(1 + sin x), for −π/2 &lt; x &lt; π/2.</p>", "parts": [{"q": "Show that f″(x) = −1/(1 + sin x).", "m": 3, "ms": [["M1", "f′(x) = cos x/(1 + sin x) and applies the quotient rule"], ["M1", "uses sin²x + cos²x = 1 in the numerator: −(1 + sin x)"], ["A1", "cancels to −1/(1 + sin x)"]]}, {"q": "Find the Maclaurin series for f(x) up to and including the term in x³.", "m": 3, "ms": [["M1", "f‴(x) = cos x/(1 + sin x)²"], ["M1", "f(0) = 0, f′(0) = 1, f″(0) = −1, f‴(0) = 1"], ["A1", "x − x²/2 + x³/6"]]}]}, {"stem": "", "parts": [{"q": "Write down the series expansion of e^(−2x) up to and including the term in x³.", "m": 2, "ms": [["M1", "replaces x by −2x in the series for eˣ"], ["A1", "1 − 2x + 2x² − (4/3)x³"]]}, {"q": "Hence find the series expansion of (1 + 3x)e^(−2x) up to and including the term in x³.", "m": 3, "ms": [["M1", "multiplies and collects terms up to x³"], ["A1", "1 + x − 4x²"], ["A1", "+ (14/3)x³"]]}]}, {"stem": "", "parts": [{"q": "Use the first three non-zero terms of the series for cos x to estimate ∫ cos(x²) dx from 0 to 0.5, giving your answer to 4 decimal places.", "m": 4, "ms": [["M1", "replaces x by x² in the cosine series"], ["A1", "1 − x⁴/2 + x⁸/24"], ["M1", "integrates term by term: x − x⁵/10 + x⁹/216"], ["A1", "0.4969"]], "ans": {"a": 0.4969, "tol": 0.0002, "unit": ""}}]}]}}, {"id": "cp-improper", "module": "core", "title": "Improper integrals and volumes of revolution", "refs": "5.1–5.2", "notes": ["An improper integral has an infinite limit or an unbounded integrand at a boundary. Replace the problematic endpoint by a variable and take a one-sided limit after integrating. Writing infinity directly into an antiderivative is not a justification of convergence.", "A solid formed by rotating y = f(x) about the x-axis has volume π∫y² dx over the specified interval. Rotation about the y-axis can use π∫x² dy. The squared radius and the integration variable must match the slices."], "example": {"q": "Evaluate the integral from 1 to infinity of 1/x² dx.", "steps": ["Use a finite upper limit R.", "The integral from 1 to R is [−1/x] = 1 − 1/R.", "As R tends to infinity, 1/R tends to zero.", "The improper integral converges to 1."]}, "practice": {"q": "The curve y = √x for 0 ≤ x ≤ 4 is rotated about the x-axis. Find the volume.", "answer": null, "steps": ["Cross-sectional area = πy² = πx.", "V = π∫₀⁴ x dx.", "V = π[x²/2]₀⁴ = 8π.", "State cubic units if x and y are measured in a length unit."]}, "check": {"q": "Evaluate the convergent integral from 1 to infinity of x⁻².", "a": 1}, "deep": {"tip": "Name what makes the integral improper, an infinite limit or an unbounded integrand, and replace that limit by a letter before integrating. Convergence is decided by the limit of the evaluated expression, so write that limit step explicitly; for volumes, square the function first and keep π outside.", "examples": [{"title": "An unbounded integrand", "q": "Evaluate ∫ x^(−1/2) dx from 0 to 1.", "steps": ["The integrand is unbounded at x = 0, so use the lower limit a and let a → 0⁺.", "∫ x^(−1/2) dx from a to 1 = [2√x] = 2 − 2√a.", "As a → 0⁺, 2√a → 0.", "The integral converges to 2."]}, {"title": "An infinite limit with integration by parts", "q": "Evaluate ∫ xe^(−x) dx from 0 to ∞.", "steps": ["By parts with u = x, dv/dx = e^(−x): ∫ xe^(−x) dx = −xe^(−x) − e^(−x).", "From 0 to t: −te^(−t) − e^(−t) + 1.", "As t → ∞, te^(−t) → 0 and e^(−t) → 0.", "The integral converges to 1."]}, {"title": "Rotation about the y-axis", "q": "The region bounded by y = x², the y-axis and y = 4 (x ≥ 0) is rotated through 2π about the y-axis. Find the volume.", "steps": ["About the y-axis, V = π∫ x² dy.", "Here x² = y, so V = π∫ y dy from 0 to 4.", "= π[y²/2] = π × 8.", "V = 8π."]}], "fills": [{"q": "An infinite limit.", "lines": ["∫ x⁻³ dx from 1 to ∞ = [[0.5]]"]}, {"q": "An exponential tail.", "lines": ["∫ e^(−2x) dx from 0 to ∞ = [[0.5]]"]}, {"q": "Mean value of x² on [0, 3].", "lines": ["(1/3) × 9 = [[3]]"]}], "exam": [{"stem": "", "parts": [{"q": "Show that ∫ 1/[x(x + 1)] dx from 1 to ∞ converges and find its exact value.", "m": 5, "ms": [["M1", "partial fractions: 1/x − 1/(x + 1)"], ["A1", "ln x − ln(x + 1) = ln[x/(x + 1)]"], ["M1", "considers the limit as the upper limit t → ∞"], ["A1", "ln[t/(t + 1)] → ln 1 = 0"], ["A1", "0 − ln ½ = ln 2"]], "ans": {"a": 0.6931471806, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>The region R lies under the curve y = 1/x for x ≥ 1 and above the x-axis.</p>", "parts": [{"q": "Show that the area of R is not finite.", "m": 2, "ms": [["M1", "∫ 1/x dx from 1 to t = ln t"], ["A1", "ln t → ∞ as t → ∞, so the integral diverges"]]}, {"q": "R is rotated through 2π about the x-axis. Show that the volume generated is finite and find it.", "m": 3, "ms": [["M1", "π∫ x⁻² dx from 1 to t"], ["A1", "π(1 − 1/t)"], ["A1", "limit π"]], "ans": {"a": 3.1415926536, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Find the mean value of sin²x over the interval 0 ≤ x ≤ π.", "m": 3, "ms": [["M1", "(1/π)∫ sin²x dx from 0 to π"], ["M1", "uses sin²x = ½(1 − cos 2x)"], ["A1", "½"]], "ans": {"a": 0.5, "tol": 0.001, "unit": ""}}, {"q": "The curve y = e^(−x), 0 ≤ x ≤ ln 2, is rotated through 2π about the x-axis. Find the exact volume generated.", "m": 3, "ms": [["M1", "π∫ e^(−2x) dx"], ["A1", "π[−½e^(−2x)] from 0 to ln 2"], ["A1", "3π/8"]], "ans": {"a": 1.1780972451, "tol": 0.001, "unit": ""}}]}]}}, {"id": "cp-inverse-calculus", "module": "core", "title": "Inverse trigonometric calculus and substitutions", "refs": "5.3–5.6", "notes": ["Differentiate inverse sine by implicit differentiation, respecting its principal range. The standard forms ∫1/√(a²−x²) dx and ∫1/(a²+x²) dx lead to inverse trigonometric functions with scale factors. A substitution must transform dx as well as the integrand.", "For x = a sinθ, choose a range for θ that makes the square root sign consistent. Other algebraic and trigonometric substitutions can simplify roots or rational functions. Differentiate your antiderivative to check the constant factors."], "example": {"q": "Evaluate ∫1/(9 + x²) dx.", "steps": ["Match a² + x² with a = 3.", "The result is (1/3) arctan(x/3) + C.", "Differentiating gives (1/3)(1/3)/(1+x²/9).", "This simplifies to 1/(9+x²), confirming the scale."]}, "practice": {"q": "Find ∫1/√(16 − x²) dx and state an appropriate real domain.", "answer": null, "steps": ["Use a = 4 in the inverse-sine form.", "The antiderivative is arcsin(x/4) + C.", "It applies on an interval inside −4 < x < 4.", "Differentiate to recover 1/√(16−x²)."]}, "check": {"q": "What is the coefficient multiplying arctan(x/3) in ∫dx/(9+x²)?", "a": 0.3333333333333333}, "deep": {"tip": "Match the integrand to a standard form before anything else: a² + x² leads to arctan, √(a² − x²) to arcsin. Complete the square to create that form, take any constant factor out so the coefficient of x² is 1, and check the answer by differentiating.", "examples": [{"title": "Differentiating an inverse sine", "q": "Differentiate arcsin 2x with respect to x.", "steps": ["Let y = arcsin 2x, so sin y = 2x.", "cos y dy/dx = 2.", "cos y = √(1 − sin²y) = √(1 − 4x²), positive because −π/2 ≤ y ≤ π/2.", "dy/dx = 2/√(1 − 4x²)."]}, {"title": "Completing the square", "q": "Find ∫ 1/(x² + 4x + 13) dx.", "steps": ["x² + 4x + 13 = (x + 2)² + 9.", "This is 1/(u² + a²) with u = x + 2 and a = 3.", "∫ 1/(u² + 3²) du = ⅓ arctan(u/3).", "⅓ arctan((x + 2)/3) + c."]}, {"title": "A definite inverse-sine integral", "q": "Evaluate ∫ 1/√(4 − x²) dx from 0 to 1.", "steps": ["∫ 1/√(a² − x²) dx = arcsin(x/a) with a = 2.", "[arcsin(x/2)] from 0 to 1 = arcsin ½ − arcsin 0.", "= π/6."]}], "fills": [{"q": "Gradient of y = arctan x at x = 1.", "lines": ["1/(1 + 1²) = [[0.5]]"]}, {"q": "A standard definite integral.", "lines": ["∫ 1/(1 + x²) dx from 0 to 1 = π/[[4]]"]}, {"q": "Completing the square.", "lines": ["x² + 6x + 13 = (x + [[3]])² + [[4]]"]}], "exam": [{"stem": "", "parts": [{"q": "Show that d/dx(arctan x) = 1/(1 + x²).", "m": 3, "ms": [["M1", "tan y = x, so sec²y dy/dx = 1"], ["M1", "uses sec²y = 1 + tan²y = 1 + x²"], ["A1", "dy/dx = 1/(1 + x²)"]]}, {"q": "Find the gradient of the curve y = arctan 3x at the point where x = ⅓.", "m": 2, "ms": [["M1", "dy/dx = 3/(1 + 9x²)"], ["A1", "3/2"]], "ans": {"a": 1.5, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Find the exact value of ∫ 1/√(9 − 4x²) dx from 0 to ¾.", "m": 4, "ms": [["M1", "obtains k arcsin(2x/3)"], ["A1", "k = ½"], ["M1", "substitutes the limits: ½ arcsin ½"], ["A1", "π/12"]], "ans": {"a": 0.2617993878, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Find ∫ (2x + 3)/(x² + 9) dx.", "m": 4, "ms": [["M1", "splits into 2x/(x² + 9) + 3/(x² + 9)"], ["A1", "ln(x² + 9)"], ["M1", "k arctan(x/3)"], ["A1", "ln(x² + 9) + arctan(x/3) + c"]]}, {"q": "Hence find the exact value of the integral from 0 to 3.", "m": 2, "ms": [["M1", "ln 18 − ln 9 + arctan 1"], ["A1", "ln 2 + π/4"]], "ans": {"a": 1.478545344, "tol": 0.001, "unit": ""}}]}]}}, {"id": "cp-vector-lines", "module": "core", "title": "Vector lines, scalar products and angles", "refs": "6.1–6.4", "notes": ["A line has vector equation r = a + λd, where a locates a point and d is a non-zero direction vector. Intersections require all three coordinates to agree for the same parameter pair. In 3D, non-parallel lines can be skew rather than intersecting.", "The scalar product a·b = |a||b|cosθ gives angles and perpendicularity. For the acute angle between unoriented lines use the absolute value of the dot product. A shortest point-to-line distance can be found by locating the perpendicular foot and solving the scalar-product condition."], "example": {"q": "Find the angle between direction vectors (1,1,0) and (1,0,1).", "steps": ["The dot product is 1.", "Each magnitude is √2.", "cosθ = 1/2.", "θ = 60°."]}, "practice": {"q": "Find where r = (1,0,2) + λ(1,2,−1) intersects the plane x + y + z = 6.", "answer": null, "steps": ["Coordinates are (1+λ,2λ,2−λ).", "Substitute: 3 + 2λ = 6.", "λ = 3/2.", "The intersection is (5/2,3,1/2)."]}, "check": {"q": "Find the scalar product (1,1,0)·(1,0,1).", "a": 1}, "deep": {"tip": "Use different parameters for different lines and solve two component equations before testing the third: that test is what separates intersecting from skew lines. Angles between lines come from direction vectors only, and the shortest distance from a point to a line uses a perpendicular, found with a zero scalar product.", "examples": [{"title": "Do two lines meet?", "q": "l₁: r = (1,2,3) + λ(1,−1,2) and l₂: r = (4,1,6) + μ(1,1,−1). Show that the lines intersect and find the point of intersection.", "steps": ["x: 1 + λ = 4 + μ; y: 2 − λ = 1 + μ.", "Adding: 3 = 5 + 2μ, so μ = −1 and λ = 2.", "z: 3 + 2λ = 7 and 6 − μ = 7, so the third equation is satisfied.", "The lines meet at (3, 0, 7)."]}, {"title": "Angle between two lines", "q": "Find the acute angle between the lines in the previous example.", "steps": ["Use the directions a = (1,−1,2) and b = (1,1,−1).", "a·b = 1 − 1 − 2 = −2, |a| = √6 and |b| = √3.", "cos θ = |−2|/(√6 √3) = 2/√18, taking the modulus for the acute angle.", "θ = 61.9° (1 d.p.)."]}, {"title": "Distance from a point to a line", "q": "Find the shortest distance from P(3,1,2) to the line r = (1,0,−1) + t(2,1,2).", "steps": ["With A(1,0,−1): AP = (2,1,3) and d = (2,1,2).", "The foot of the perpendicular has t = AP·d/|d|² = 11/9.", "Distance² = |AP|² − (AP·d)²/|d|² = 14 − 121/9 = 5/9.", "Shortest distance = √5/3 ≈ 0.745."]}], "fills": [{"q": "Scalar product.", "lines": ["(2,−1,3)·(1,4,2) = [[4]]"]}, {"q": "Magnitude.", "lines": ["|(2,3,6)| = [[7]]"]}, {"q": "Perpendicular vectors: (1,2,−2)·(2,1,k) = 0.", "lines": ["k = [[2]]"]}], "exam": [{"stem": "<p>l₁: r = (2,−1,0) + λ(1,2,−1) and l₂: r = (5,2,−3) + μ(2,1,−2).</p>", "parts": [{"q": "Show that l₁ and l₂ intersect and find the coordinates of the point of intersection.", "m": 5, "ms": [["M1", "equates two components"], ["M1", "solves the pair of equations"], ["A1", "λ = 1, μ = −1"], ["M1", "checks the third component"], ["A1", "(3, 1, −1)"]]}, {"q": "Find the acute angle between l₁ and l₂, to 1 decimal place.", "m": 3, "ms": [["M1", "scalar product of the directions: 2 + 2 + 2 = 6"], ["A1", "cos θ = 6/(3√6)"], ["A1", "35.3°"]], "ans": {"a": 35.3, "tol": 0.002, "unit": "°"}}]}, {"stem": "<p>A has coordinates (1, 2, −1) and B has coordinates (3, 0, 3).</p>", "parts": [{"q": "Find a vector equation of the line AB.", "m": 2, "ms": [["M1", "direction AB = (2,−2,4)"], ["A1", "r = (1,2,−1) + t(1,−1,2), or equivalent"]]}, {"q": "Find the coordinates of the point P on AB that is closest to the origin, and the distance OP.", "m": 4, "ms": [["M1", "general point (1 + t, 2 − t, −1 + 2t)"], ["M1", "OP·(1,−1,2) = 0"], ["A1", "t = ½"], ["A1", "P(3/2, 3/2, 0) and OP = 3/√2"]]}]}, {"stem": "<p>l₁: r = (1,0,0) + λ(1,1,0) and l₂: r = (0,1,3) + μ(0,1,1).</p>", "parts": [{"q": "Show that l₁ and l₂ are skew.", "m": 4, "ms": [["M1", "equates components: 1 + λ = 0, λ = 1 + μ, 0 = 3 + μ"], ["M1", "solves two of them: λ = −1, μ = −2"], ["A1", "the third gives μ = −3, a contradiction"], ["A1", "directions are not parallel, so the lines are skew"]]}]}]}}, {"id": "cp-planes", "module": "core", "title": "Planes, intersections and distances", "refs": "6.2–6.5", "notes": ["A plane with normal n through a satisfies (r−a)·n = 0. In Cartesian form ax+by+cz=d, the vector (a,b,c) is normal to the plane. The angle between planes is obtained from their normals; the acute line–plane angle is complementary to the acute line–normal angle.", "The perpendicular distance from (x₀,y₀,z₀) to ax+by+cz=d is |ax₀+by₀+cz₀−d|/√(a²+b²+c²). For intersections, substitute a line into a plane or solve two plane equations with a free parameter. Check whether parallel objects are coincident before describing a distance."], "example": {"q": "Find the distance from (1,2,3) to 2x − y + 2z = 3.", "steps": ["Normal vector is (2,−1,2), with magnitude 3.", "The signed numerator is 2−2+6−3 = 3.", "Distance = |3|/3 = 1."]}, "practice": {"q": "Find a Cartesian equation of the plane through (1,0,2) with normal (2,3,−1).", "answer": null, "steps": ["Use 2(x−1)+3y−(z−2)=0.", "Expand to 2x+3y−z=0.", "The given point satisfies the equation.", "The coefficient vector matches the specified normal."]}, "check": {"q": "Find the magnitude of the normal (2,−1,2).", "a": 3}, "deep": {"tip": "Identify the normal vector first, because it controls every plane calculation: the equation r·n = a·n, the angle with a line (90° minus the angle with the normal) and the perpendicular distance. Substituting a line into a plane gives one linear equation in the parameter, so interpret the outcome: one value, none or all.", "examples": [{"title": "A plane through three points", "q": "Find a Cartesian equation of the plane through A(1,0,1), B(2,1,0) and C(0,2,3).", "steps": ["AB = (1,1,−1) and AC = (−1,2,2).", "A normal n = (a,b,c) satisfies a + b − c = 0 and −a + 2b + 2c = 0.", "Adding: 3b + c = 0; taking b = −1 gives c = 3 and a = 4, so n = (4,−1,3).", "r·n = a·n: 4x − y + 3z = 4 + 0 + 3.", "4x − y + 3z = 7; check B: 8 − 1 + 0 = 7 and C: 0 − 2 + 9 = 7."]}, {"title": "Angle between a line and a plane", "q": "Find the angle between the line with direction (1,2,2) and the plane 2x − y + 2z = 5.", "steps": ["The normal to the plane is n = (2,−1,2).", "The angle φ between the line and the normal has cos φ = |2 − 2 + 4|/(3 × 3) = 4/9.", "The angle between the line and the plane is θ = 90° − φ, so sin θ = 4/9.", "θ = 26.4° (1 d.p.)."]}, {"title": "Line of intersection of two planes", "q": "Find a vector equation of the line in which x + y + z = 3 and x − y + 2z = 2 meet.", "steps": ["A direction d is perpendicular to both normals: d·(1,1,1) = 0 and d·(1,−1,2) = 0.", "Solving gives d = (3,−1,−2).", "A common point: put z = 0, then x + y = 3 and x − y = 2, so x = 5/2, y = 1/2.", "r = (5/2, 1/2, 0) + t(3,−1,−2)."]}], "fills": [{"q": "Distance from the origin to 2x + 3y + 6z = 14.", "lines": ["14/√(4 + 9 + 36) = [[2]]"]}, {"q": "Planes with normals (1,0,0) and (0,1,0).", "lines": ["angle between them = [[90]]°"]}, {"q": "The point (1, 2, 3) lies on x + y + z = d.", "lines": ["d = [[6]]"]}], "exam": [{"stem": "<p>The plane Π has equation 2x − y + 2z = 5 and the line l has equation r = (1,3,−2) + λ(2,1,1).</p>", "parts": [{"q": "Find the coordinates of the point where l meets Π.", "m": 3, "ms": [["M1", "substitutes: 2(1 + 2λ) − (3 + λ) + 2(−2 + λ) = 5"], ["A1", "λ = 2"], ["A1", "(5, 5, 0)"]]}, {"q": "Find the acute angle between l and Π, to 1 decimal place.", "m": 3, "ms": [["M1", "scalar product of (2,1,1) with the normal (2,−1,2): 5"], ["M1", "sin θ = 5/(3√6)"], ["A1", "42.9°"]], "ans": {"a": 42.9, "tol": 0.002, "unit": "°"}}, {"q": "Find the perpendicular distance from the point (1, 3, −2) to Π.", "m": 2, "ms": [["M1", "|2 − 3 − 4 − 5|/√(4 + 1 + 4)"], ["A1", "10/3"]], "ans": {"a": 3.3333333333, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Find the acute angle between the planes x + 2y − 2z = 5 and 2x − y + 2z = 1, to 1 decimal place.", "m": 3, "ms": [["M1", "scalar product of the normals: 2 − 2 − 4 = −4"], ["A1", "cos θ = 4/9"], ["A1", "63.6°"]], "ans": {"a": 63.6, "tol": 0.002, "unit": "°"}}]}, {"stem": "<p>The plane Π passes through A(2, 1, −1) and is perpendicular to the vector (1,−2,3).</p>", "parts": [{"q": "Find a Cartesian equation of Π.", "m": 2, "ms": [["M1", "x − 2y + 3z = (2,1,−1)·(1,−2,3)"], ["A1", "x − 2y + 3z = −3"]]}, {"q": "Find the coordinates of the foot of the perpendicular from Q(4, −3, 5) to Π.", "m": 3, "ms": [["M1", "line through Q along the normal: (4 + t, −3 − 2t, 5 + 3t)"], ["M1", "substitutes into Π: 25 + 14t = −3"], ["A1", "t = −2, giving (2, 1, −1)"]]}]}]}}, {"id": "cp-polar", "module": "core", "title": "Polar curves, tangents and enclosed area", "refs": "7.1–7.3", "notes": ["Polar coordinates use x=r cosθ and y=r sinθ. A sketch should consider symmetry, zeros of r and the interval over which a loop is traced once. Negative r places a point on the opposite ray, so it must be interpreted rather than silently discarded.", "The polar area is ½∫r² dθ. Check the bounds carefully to avoid counting a loop twice. For tangents, differentiate x(θ) and y(θ), then use dy/dx=(dy/dθ)/(dx/dθ); horizontal and vertical tangent tests must also consider points where both derivatives vanish."], "example": {"q": "Find the area of the circle r = 2cosθ, using −π/2 ≤ θ ≤ π/2.", "steps": ["The interval traces the circle once.", "A = (1/2)∫₋π/₂^π/₂ 4cos²θ dθ.", "Use cos²θ = (1+cos2θ)/2.", "A = [θ + (1/2)sin2θ]₋π/₂^π/₂ = π.", "This agrees with a circle of radius 1 centred at (1,0)."]}, "practice": {"q": "Convert r = 4sinθ to Cartesian form and identify the curve.", "answer": null, "steps": ["Multiply by r: r² = 4r sinθ.", "x²+y² = 4y.", "Complete the square: x²+(y−2)² = 4.", "It is a circle with centre (0,2) and radius 2."]}, "check": {"q": "For r=4sinθ, what is the circle radius in Cartesian coordinates?", "a": 2}, "deep": {"tip": "Sketch the curve from a short table of θ and r before integrating, so that the limits describe the region once and only once. Area uses ½∫r² dθ, tangents parallel to the initial line come from d(r sin θ)/dθ = 0, and tangents perpendicular to it from d(r cos θ)/dθ = 0.", "examples": [{"title": "Area of a cardioid", "q": "Find the area enclosed by the cardioid r = 2(1 + cos θ).", "steps": ["Area = ½∫ r² dθ from 0 to 2π = 2∫ (1 + 2cos θ + cos²θ) dθ.", "cos²θ = ½(1 + cos 2θ), so the integrand is 3/2 + 2cos θ + ½cos 2θ.", "Over a full turn the cosine terms integrate to 0.", "Area = 2 × (3/2)(2π) = 6π."]}, {"title": "Tangents parallel to the initial line", "q": "Find the points on r = 1 + cos θ where the tangent is parallel to the initial line.", "steps": ["y = r sin θ = sin θ + sin θ cos θ.", "dy/dθ = cos θ + cos 2θ = 2cos²θ + cos θ − 1.", "(2cos θ − 1)(cos θ + 1) = 0, so cos θ = ½ or cos θ = −1.", "θ = ±π/3, where r = 3/2; θ = π is the pole, where the curve has a cusp."]}, {"title": "Where two curves meet", "q": "Find the polar coordinates of the points where r = 1 + cos θ meets r = 3cos θ.", "steps": ["1 + cos θ = 3cos θ.", "cos θ = ½, so θ = ±π/3.", "r = 3 × ½ = 3/2.", "The curves meet at (3/2, π/3) and (3/2, −π/3); both also pass through the pole, for different values of θ."]}], "fills": [{"q": "The circle r = 2 in Cartesian form.", "lines": ["x² + y² = [[4]]"]}, {"q": "Area inside r = 3 for 0 ≤ θ ≤ π/2.", "lines": ["½ × 9 × π/2 = [[2.25]]π"]}, {"q": "The circle r = 4cos θ at θ = π/3.", "lines": ["r = [[2]]"]}], "exam": [{"stem": "<p>The curve C has polar equation r = 3 + 2cos θ, 0 ≤ θ &lt; 2π.</p>", "parts": [{"q": "State the greatest and least values of r and the values of θ at which they occur.", "m": 2, "ms": [["B1", "greatest r = 5 at θ = 0"], ["B1", "least r = 1 at θ = π"]]}, {"q": "Find the exact area enclosed by C.", "m": 5, "ms": [["M1", "½∫ (3 + 2cos θ)² dθ from 0 to 2π"], ["M1", "expands: 9 + 12cos θ + 4cos²θ"], ["M1", "uses cos²θ = ½(1 + cos 2θ)"], ["A1", "½[11θ + 12sin θ + sin 2θ] from 0 to 2π"], ["A1", "11π"]], "ans": {"a": 34.5575191895, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>The curve C has polar equation r = 2sin 2θ, 0 ≤ θ ≤ π/2.</p>", "parts": [{"q": "Find the exact area enclosed by this loop of C.", "m": 4, "ms": [["M1", "½∫ 4sin²2θ dθ from 0 to π/2"], ["M1", "uses sin²2θ = ½(1 − cos 4θ)"], ["A1", "[θ − ¼sin 4θ] from 0 to π/2"], ["A1", "π/2"]], "ans": {"a": 1.5707963268, "tol": 0.001, "unit": ""}}, {"q": "State the greatest value of r on the loop and the value of θ at which it occurs.", "m": 1, "ms": [["B1", "r = 2 at θ = π/4"]]}]}, {"stem": "", "parts": [{"q": "Find the polar coordinates of the points on the curve r = 2(1 + cos θ), −π &lt; θ ≤ π, at which the tangent is perpendicular to the initial line.", "m": 5, "ms": [["M1", "x = r cos θ = 2cos θ + 2cos²θ"], ["M1", "differentiates with respect to θ"], ["A1", "−2sin θ(1 + 2cos θ) = 0"], ["A1", "(4, 0)"], ["A1", "(1, 2π/3) and (1, −2π/3); θ = π is the cusp at the pole"]]}]}]}}, {"id": "cp-hyperbolic", "module": "core", "title": "Hyperbolic functions, identities and inverses", "refs": "8.1–8.4", "notes": ["Define sinh x=(eˣ−e⁻ˣ)/2 and cosh x=(eˣ+e⁻ˣ)/2. Their identity is cosh²x−sinh²x=1, with a minus sign. Differentiation gives d(sinh x)/dx=cosh x and d(cosh x)/dx=sinh x; use the chain rule for a scaled argument.", "The inverse of cosh requires a domain restriction, commonly x≥0. Logarithmic inverse forms follow by solving an exponential equation. For arcosh x the real domain is x≥1; for artanh x it is |x|<1. Keep the required real domain when simplifying logarithms."], "example": {"q": "Solve cosh x = 5/3 for real x.", "steps": ["Let u = eˣ > 0. Then (u+1/u)/2 = 5/3.", "3u²−10u+3=0, so (3u−1)(u−3)=0.", "u=3 or 1/3.", "x=ln3 or −ln3, consistent with cosh being even."]}, "practice": {"q": "Differentiate sinh(3x) and integrate cosh(2x).", "answer": null, "steps": ["By the chain rule, d[sinh(3x)]/dx = 3cosh(3x).", "An antiderivative of cosh(2x) is (1/2)sinh(2x)+C.", "Differentiating the proposed integral restores cosh(2x).", "Include the integration constant."]}, "check": {"q": "Evaluate cosh(0).", "a": 1}, "deep": {"tip": "Most equations become a quadratic in eˣ once the definitions are substituted, so multiply through by eˣ and reject any non-positive value of eˣ. Remember that cosh is even, so cosh x = k gives two solutions when k > 1, and that the identities differ from the trigonometric ones by the sign attached to sinh².", "examples": [{"title": "An equation in sinh and cosh", "q": "Solve 2cosh x − sinh x = 2.", "steps": ["(eˣ + e⁻ˣ) − ½(eˣ − e⁻ˣ) = 2.", "½eˣ + (3/2)e⁻ˣ = 2; multiply by 2eˣ: e²ˣ − 4eˣ + 3 = 0.", "(eˣ − 1)(eˣ − 3) = 0.", "x = 0 or x = ln 3."]}, {"title": "Proving an identity", "q": "Prove that cosh²x − sinh²x = 1.", "steps": ["cosh²x = ¼(e²ˣ + 2 + e⁻²ˣ).", "sinh²x = ¼(e²ˣ − 2 + e⁻²ˣ).", "Subtracting: ¼(2 + 2).", "cosh²x − sinh²x = 1."]}, {"title": "An inverse hyperbolic value", "q": "Find the exact value of arsinh(¾).", "steps": ["arsinh x = ln(x + √(x² + 1)).", "√(9/16 + 1) = 5/4.", "arsinh(¾) = ln(¾ + 5/4).", "= ln 2."]}], "fills": [{"q": "Value at the origin.", "lines": ["cosh 0 = [[1]]"]}, {"q": "From the definition.", "lines": ["sinh(ln 2) = ½(2 − ½) = [[0.75]]"]}, {"q": "Logarithmic form.", "lines": ["arcosh(5/4) = ln(5/4 + ¾) = ln [[2]]"]}], "exam": [{"stem": "", "parts": [{"q": "Using the definitions in terms of exponentials, prove that sinh 2x = 2sinh x cosh x.", "m": 3, "ms": [["M1", "substitutes the exponential definitions"], ["M1", "multiplies: 2 × ¼(eˣ − e⁻ˣ)(eˣ + e⁻ˣ)"], ["A1", "½(e²ˣ − e⁻²ˣ) = sinh 2x"]]}, {"q": "Hence solve sinh 2x = 3sinh x, giving non-zero answers as exact logarithms.", "m": 4, "ms": [["M1", "sinh x(2cosh x − 3) = 0"], ["A1", "x = 0"], ["M1", "cosh x = 3/2 and uses arcosh x = ln(x + √(x² − 1))"], ["A1", "x = ±ln[(3 + √5)/2]"]]}]}, {"stem": "", "parts": [{"q": "Solve 5cosh x + 3sinh x = 4, giving your answer as an exact logarithm.", "m": 4, "ms": [["M1", "substitutes the exponential definitions"], ["A1", "4e²ˣ − 4eˣ + 1 = 0"], ["M1", "(2eˣ − 1)² = 0"], ["A1", "x = −ln 2"]], "ans": {"a": -0.6931471806, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Show that d/dx(arsinh x) = 1/√(1 + x²).", "m": 3, "ms": [["M1", "sinh y = x, so cosh y dy/dx = 1"], ["M1", "cosh y = √(1 + sinh²y), positive"], ["A1", "dy/dx = 1/√(1 + x²)"]]}, {"q": "Hence find the exact value of ∫ 1/√(1 + x²) dx from 0 to ¾.", "m": 2, "ms": [["M1", "[arsinh x] from 0 to ¾"], ["A1", "ln 2"]], "ans": {"a": 0.6931471806, "tol": 0.001, "unit": ""}}]}]}}, {"id": "cp-de-first", "module": "core", "title": "First-order differential equations and modelling", "refs": "9.1–9.2", "notes": ["A linear first-order equation y′+P(x)y=Q(x) has integrating factor exp(∫P dx). Multiplying every term makes the left side a product derivative. Apply an initial condition only after finding the general solution and keep the independent variable consistent.", "In a model, identify what the variables and rate constants mean and whether the limiting behaviour is sensible. An initial value selects a particular solution; it does not prove that the model remains accurate indefinitely. A separable equation is a special convenient case, not the only first-order form."], "example": {"q": "Solve y′ + 2y = 6, given y(0)=1.", "steps": ["Integrating factor = e^(2x).", "d(e^(2x)y)/dx = 6e^(2x).", "e^(2x)y = 3e^(2x)+C.", "y = 3+Ce^(−2x).", "The initial condition gives C=−2, so y=3−2e^(−2x)."]}, "practice": {"q": "Solve y′ + y = 4 with y(0)=2.", "answer": null, "steps": ["Multiply by the integrating factor eˣ.", "d(eˣy)/dx = 4eˣ.", "y=4+Ce⁻ˣ.", "At x=0, C=−2, so y=4−2e⁻ˣ.", "The solution approaches 4 as x increases."]}, "check": {"q": "What is the equilibrium solution of y′+2y=6?", "a": 3}, "deep": {"tip": "Rearrange to dy/dx + P(x)y = Q(x) with coefficient 1 on dy/dx before finding the integrating factor e^(∫P dx). Recognise the left side as the derivative of (integrating factor × y), integrate once with a constant, and apply the boundary condition only after that constant is in place.", "examples": [{"title": "Integrating factor with a power of x", "q": "Find the general solution of dy/dx + y/x = x², x > 0.", "steps": ["P = 1/x, so the integrating factor is e^(ln x) = x.", "x dy/dx + y = x³, that is d(xy)/dx = x³.", "xy = x⁴/4 + C.", "y = x³/4 + C/x."]}, {"title": "Integrating factor with an exponential", "q": "Find the general solution of dy/dx − 2y = e^(3x).", "steps": ["Integrating factor e^(−2x).", "d(ye^(−2x))/dx = e^(3x) e^(−2x) = eˣ.", "ye^(−2x) = eˣ + C.", "y = e^(3x) + Ce^(2x)."]}, {"title": "A mixing model", "q": "A tank holds 100 litres of water. Brine containing 2 g of salt per litre flows in at 3 litres per minute and the mixture flows out at the same rate. Initially there is no salt. Find the mass m grams of salt after t minutes.", "steps": ["Rate in = 6 g/min; rate out = 3 × m/100 g/min, so dm/dt = 6 − 0.03m.", "dm/dt + 0.03m = 6 has integrating factor e^(0.03t).", "me^(0.03t) = 200e^(0.03t) + C.", "m(0) = 0 gives C = −200.", "m = 200(1 − e^(−0.03t)); the mass approaches 200 g."]}], "fills": [{"q": "Integrating factor for y′ + 3y = x.", "lines": ["e^([[3]]x)"]}, {"q": "Integrating factor for y′ + (2/x)y = 1, x > 0.", "lines": ["x to the power [[2]]"]}, {"q": "y′ + y = 0 with y(0) = 5.", "lines": ["y = 5e^(−x), so y(ln 5) = [[1]]"]}], "exam": [{"stem": "<p>dy/dx + 2y/x = 4x, x &gt; 0.</p>", "parts": [{"q": "Find the general solution of the differential equation.", "m": 4, "ms": [["B1", "integrating factor x²"], ["M1", "d(x²y)/dx = 4x³"], ["A1", "x²y = x⁴ + C"], ["A1", "y = x² + C/x²"]]}, {"q": "Given that y = 3 when x = 1, find the value of y when x = 2.", "m": 2, "ms": [["M1", "C = 2"], ["A1", "4.5"]], "ans": {"a": 4.5, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>dy/dx + y tan x = cos x, with y = 2 when x = 0.</p>", "parts": [{"q": "Find y in terms of x and hence the value of y when x = π.", "m": 6, "ms": [["B1", "integrating factor sec x"], ["M1", "d(y sec x)/dx = 1"], ["A1", "y sec x = x + C"], ["M1", "uses y(0) = 2"], ["A1", "y = (x + 2)cos x"], ["A1", "y(π) = −(π + 2)"]], "ans": {"a": -5.1415926536, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>A particle falls from rest. Its speed v m s⁻¹ after t seconds satisfies dv/dt = 9.8 − 0.2v.</p>", "parts": [{"q": "Find v in terms of t.", "m": 4, "ms": [["B1", "integrating factor e^(0.2t)"], ["M1", "ve^(0.2t) = 49e^(0.2t) + C"], ["A1", "C = −49 from v(0) = 0"], ["A1", "v = 49(1 − e^(−0.2t))"]]}, {"q": "State the terminal speed.", "m": 1, "ms": [["B1", "49 m s⁻¹"]], "ans": {"a": 49.0, "tol": 0.001, "unit": "m s⁻¹"}}, {"q": "Find the time taken to reach half the terminal speed, to 3 significant figures.", "m": 2, "ms": [["M1", "e^(−0.2t) = ½"], ["A1", "t = 5 ln 2 = 3.47 s"]], "ans": {"a": 3.4657359028, "tol": 0.002, "unit": "s"}}]}]}}, {"id": "cp-de-second", "module": "core", "title": "Second-order equations and complementary functions", "refs": "9.3–9.5", "notes": ["For ay″+by′+cy=0, solve the auxiliary equation ar²+br+c=0, obtained by trying y=e^(rx). Distinct real roots give a sum of exponentials; a repeated root requires (A+Bx)e^(rx). Complex roots α±iβ give e^(αx)(Acosβx+Bsinβx).", "For a non-zero forcing term, add a particular integral to the complementary function. If a trial form duplicates a term of the complementary function, multiply it by a sufficient power of x. Verify by substitution before applying the two initial or boundary conditions."], "example": {"q": "Solve y″−3y′+2y=0 with y(0)=0 and y′(0)=1.", "steps": ["Auxiliary equation (r−1)(r−2)=0.", "y=Aeˣ+Be^(2x).", "At x=0, A+B=0.", "y′=Aeˣ+2Be^(2x), so A+2B=1.", "B=1, A=−1; hence y=e^(2x)−eˣ."]}, "practice": {"q": "Find the general solution of y″+4y=8.", "answer": null, "steps": ["Auxiliary roots are ±2i.", "Complementary function = Acos2x+Bsin2x.", "Try a constant particular integral K; 4K=8 gives K=2.", "y=Acos2x+Bsin2x+2.", "Substitution confirms y″+4y=8."]}, "check": {"q": "For y″−3y′+2y=0, what is the larger auxiliary root?", "a": 2}, "deep": {"tip": "Solve the auxiliary equation and classify its roots before writing anything else: two real roots, a repeated root and complex roots each have their own form of complementary function. Choose a particular integral that matches the right-hand side, and apply initial conditions only to the full general solution.", "examples": [{"title": "A repeated root", "q": "Solve y″ + 4y′ + 4y = 0 given that y = 1 and y′ = 0 when x = 0.", "steps": ["Auxiliary equation m² + 4m + 4 = 0 has the repeated root m = −2.", "y = (A + Bx)e^(−2x).", "y(0) = 1 gives A = 1.", "y′ = (B − 2A − 2Bx)e^(−2x), so y′(0) = B − 2 = 0 and B = 2.", "y = (1 + 2x)e^(−2x)."]}, {"title": "Complex roots", "q": "Find the general solution of y″ + 2y′ + 5y = 0.", "steps": ["m² + 2m + 5 = 0 gives m = −1 ± 2i.", "The real part gives the exponential factor and the imaginary part the frequency.", "y = e^(−x)(A cos 2x + B sin 2x)."]}, {"title": "A polynomial particular integral", "q": "Find the general solution of y″ − 3y′ + 2y = 4x.", "steps": ["m² − 3m + 2 = 0 gives m = 1, 2, so the complementary function is Aeˣ + Be^(2x).", "Try y = ax + b: then y′ = a and y″ = 0.", "−3a + 2ax + 2b = 4x gives a = 2 and b = 3.", "y = Aeˣ + Be^(2x) + 2x + 3."]}], "fills": [{"q": "Auxiliary equation m² − 5m + 6 = 0.", "lines": ["m = [[2]] or m = [[3]]"]}, {"q": "General solution of y″ + 9y = 0.", "lines": ["y = A cos [[3]]x + B sin [[3]]x"]}, {"q": "Particular integral for y″ + y = 10.", "lines": ["y = [[10]]"]}], "exam": [{"stem": "<p>y″ − 4y′ + 3y = 6x − 5.</p>", "parts": [{"q": "Find the complementary function.", "m": 2, "ms": [["M1", "m² − 4m + 3 = 0, m = 1 or 3"], ["A1", "Aeˣ + Be^(3x)"]]}, {"q": "Find a particular integral.", "m": 3, "ms": [["M1", "tries y = ax + b"], ["M1", "−4a + 3ax + 3b = 6x − 5"], ["A1", "y = 2x + 1"]]}, {"q": "Given that y = 3 and y′ = 6 when x = 0, find y in terms of x.", "m": 3, "ms": [["M1", "A + B + 1 = 3 and A + 3B + 2 = 6"], ["A1", "A = 1, B = 1"], ["A1", "y = eˣ + e^(3x) + 2x + 1"]]}]}, {"stem": "<p>y″ + 2y′ + 10y = 0.</p>", "parts": [{"q": "Find the general solution.", "m": 3, "ms": [["M1", "m² + 2m + 10 = 0"], ["A1", "m = −1 ± 3i"], ["A1", "y = e^(−x)(A cos 3x + B sin 3x)"]]}, {"q": "Describe the behaviour of y as x → ∞.", "m": 1, "ms": [["B1", "oscillations whose amplitude decays to zero"]]}]}, {"stem": "", "parts": [{"q": "Solve y″ + 4y = 12sin x, given that y = 0 and y′ = 6 when x = 0.", "m": 6, "ms": [["M1", "complementary function from m² + 4 = 0"], ["A1", "A cos 2x + B sin 2x"], ["M1", "particular integral of the form λ sin x + μ cos x"], ["A1", "4sin x"], ["M1", "applies both conditions to the general solution"], ["A1", "y = sin 2x + 4sin x"]]}]}]}}, {"id": "cp-coupled", "module": "core", "title": "Coupled equations and physical interpretations", "refs": "9.6–9.9", "notes": ["Differentiate one of a pair of first-order linear equations and eliminate the other dependent variable to obtain a second-order equation. Solve it and use the original first-order relation to recover the second variable. The initial conditions for a derivative may come from the other variable.", "Interpret damping and forcing through the roots and particular integral. A negative real part in the complementary function corresponds to decay; purely imaginary roots give undamped oscillation. Boundary values and units should support the model, and any small-angle or proportional-resistance assumption must be stated."], "example": {"q": "Solve x′=y and y′=−4x with x(0)=1 and y(0)=0.", "steps": ["Differentiate x′=y to obtain x″=y′=−4x.", "x=Acos2t+Bsin2t.", "x(0)=1 gives A=1.", "y=x′=−2sin2t+2Bcos2t.", "y(0)=0 gives B=0; x=cos2t and y=−2sin2t."]}, "practice": {"q": "For x′=y and y′=−9x, find x and y when x(0)=0 and y(0)=3.", "answer": null, "steps": ["x″+9x=0.", "x=Acos3t+Bsin3t.", "x(0)=0 gives A=0; y(0)=3B=3 gives B=1.", "x=sin3t and y=3cos3t.", "Both original equations and both initial values are satisfied."]}, "check": {"q": "For x″=−9x, what is the positive angular frequency?", "a": 3}, "deep": {"tip": "For a coupled pair, differentiate one equation and use the other to eliminate one variable, giving a single second-order equation; then recover the second variable from the original first-order equation rather than solving again. In a damped model, compare the discriminant of the auxiliary equation with zero to name the type of damping.", "examples": [{"title": "Eliminating one variable", "q": "Solve dx/dt = 3x − y and dy/dt = 2x for x and y in terms of t.", "steps": ["Differentiate the first equation: x″ = 3x′ − y′ = 3x′ − 2x.", "x″ − 3x′ + 2x = 0 has auxiliary roots 1 and 2.", "x = Aeᵗ + Be^(2t).", "From the first equation y = 3x − x′.", "y = 2Aeᵗ + Be^(2t)."]}, {"title": "Simple harmonic motion", "q": "A particle moves so that x″ = −9x, with x = 2 and x′ = 0 when t = 0. Find x, the period and the maximum speed.", "steps": ["x″ + 9x = 0 gives x = A cos 3t + B sin 3t.", "x(0) = 2 gives A = 2 and x′(0) = 0 gives B = 0.", "x = 2cos 3t, with period 2π/3.", "x′ = −6sin 3t, so the maximum speed is 6."]}, {"title": "Classifying damping", "q": "Classify the damping in x″ + 6x′ + 9x = 0 and in x″ + 2x′ + 9x = 0.", "steps": ["First equation: m² + 6m + 9 = 0 has discriminant 36 − 36 = 0.", "A repeated root: critical damping, x = (A + Bt)e^(−3t), with no oscillation.", "Second equation: discriminant 4 − 36 < 0.", "Complex roots −1 ± 2√2 i: light damping, oscillations with decaying amplitude."]}], "fills": [{"q": "Period of x″ + 16x = 0.", "lines": ["2π/[[4]]"]}, {"q": "x″ + 2kx′ + 25x = 0 is critically damped when", "lines": ["k = [[5]]"]}, {"q": "For x = 3cos 2t.", "lines": ["maximum speed = [[6]]"]}], "exam": [{"stem": "<p>dx/dt = 4x − 2y and dy/dt = x + y, with x = 3 and y = 2 when t = 0.</p>", "parts": [{"q": "Show that d²x/dt² − 5 dx/dt + 6x = 0.", "m": 3, "ms": [["M1", "differentiates: x″ = 4x′ − 2y′ = 4x′ − 2x − 2y"], ["M1", "eliminates y using 2y = 4x − x′"], ["A1", "x″ − 5x′ + 6x = 0"]]}, {"q": "Find x and y in terms of t.", "m": 5, "ms": [["M1", "auxiliary roots 2 and 3"], ["A1", "x = Ae^(2t) + Be^(3t)"], ["M1", "y = ½(4x − x′) = Ae^(2t) + ½Be^(3t)"], ["M1", "A + B = 3 and A + ½B = 2"], ["A1", "x = e^(2t) + 2e^(3t) and y = e^(2t) + e^(3t)"]]}]}, {"stem": "<p>The displacement x of a damped oscillator satisfies x″ + 4x′ + 13x = 0, with x = 0 and x′ = 6 when t = 0.</p>", "parts": [{"q": "Find x in terms of t.", "m": 5, "ms": [["M1", "m² + 4m + 13 = 0"], ["A1", "m = −2 ± 3i"], ["M1", "applies both initial conditions to e^(−2t)(A cos 3t + B sin 3t)"], ["A1", "A = 0"], ["A1", "x = 2e^(−2t) sin 3t"]]}, {"q": "State the type of damping.", "m": 1, "ms": [["B1", "light damping (underdamped)"]]}, {"q": "Find the first time after t = 0 at which x = 0.", "m": 1, "ms": [["B1", "t = π/3"]], "ans": {"a": 1.0471975512, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>A particle moves on a line so that x″ = −4x, with x = 3 and x′ = 8 when t = 0.</p>", "parts": [{"q": "Find x in terms of t and the amplitude of the motion.", "m": 3, "ms": [["M1", "x = A cos 2t + B sin 2t"], ["A1", "x = 3cos 2t + 4sin 2t"], ["A1", "amplitude √(3² + 4²) = 5"]]}, {"q": "Find the maximum speed.", "m": 1, "ms": [["B1", "2 × 5 = 10"]], "ans": {"a": 10.0, "tol": 0.001, "unit": ""}}]}]}}, {"id": "fp1-tformula", "module": "fp1", "title": "Half-angle substitutions and trigonometric equations", "refs": "1", "notes": ["With t=tan(θ/2), sinθ=2t/(1+t²), cosθ=(1−t²)/(1+t²) and tanθ=2t/(1−t²). These rational forms turn many trigonometric equations into polynomial equations in t. Derive them from double-angle identities rather than treating t as tanθ.", "The substitution misses angles at which tan(θ/2) is undefined. Test those angles in the original equation. Map every t-root back into the stated θ-interval, and reject values introduced by multiplying a denominator that can be zero."], "example": {"q": "Solve sinθ=cosθ for 0≤θ<2π using t=tan(θ/2).", "steps": ["2t=1−t², so t²+2t−1=0.", "t=−1±√2.", "Converting to θ gives π/4 and 5π/4.", "The missing substitution point θ=π is not a solution."]}, "practice": {"q": "Use the t-formulae to solve sinθ=1−cosθ for 0≤θ<2π.", "answer": null, "steps": ["2t=2t², so t(t−1)=0.", "t=0 gives θ=0; t=1 gives θ=π/2.", "Test θ=π separately: 0≠2.", "The two solutions are 0 and π/2."]}, "check": {"q": "If t=tan(θ/2)=1, what is sinθ?", "a": 1}, "deep": {"tip": "Substitute for every trigonometric function at once and multiply through by 1 + t² straight away, so the equation becomes a polynomial in t. The substitution cannot represent θ = π (where t is undefined), so test that value separately, and convert each t back with θ = 2arctan t, adjusting into the required interval.", "examples": [{"title": "A repeated root in t", "q": "Solve 3cos θ + 4sin θ = 5 for 0 ≤ θ < 2π, using t = tan(θ/2).", "steps": ["3(1 − t²)/(1 + t²) + 8t/(1 + t²) = 5.", "3 − 3t² + 8t = 5 + 5t², so 8t² − 8t + 2 = 0.", "(2t − 1)² = 0, so t = ½.", "θ = 2arctan ½ = 0.927 (3 s.f.); θ = π gives −3 ≠ 5, so nothing is lost."]}, {"title": "Proving an identity", "q": "Use t = tan(θ/2) to prove that (1 − cos θ)/sin θ = tan(θ/2).", "steps": ["1 − cos θ = 1 − (1 − t²)/(1 + t²) = 2t²/(1 + t²).", "sin θ = 2t/(1 + t²).", "The quotient is 2t²/2t = t.", "So (1 − cos θ)/sin θ = tan(θ/2), for sin θ ≠ 0."]}], "fills": [{"q": "t = 1.", "lines": ["sin θ = 2t/(1 + t²) = [[1]]"]}, {"q": "t = ½.", "lines": ["cos θ = (1 − t²)/(1 + t²) = [[0.6]]"]}, {"q": "t = ⅓.", "lines": ["tan θ = 2t/(1 − t²) = [[0.75]]"]}], "exam": [{"stem": "<p>The equation sin θ + 2cos θ = 1 is to be solved for 0 ≤ θ &lt; 2π.</p>", "parts": [{"q": "Using t = tan(θ/2), show that 3t² − 2t − 1 = 0.", "m": 3, "ms": [["M1", "substitutes 2t/(1 + t²) and (1 − t²)/(1 + t²)"], ["M1", "multiplies through by 1 + t²: 2t + 2 − 2t² = 1 + t²"], ["A1", "3t² − 2t − 1 = 0"]]}, {"q": "Hence solve the equation, giving answers to 3 significant figures where appropriate.", "m": 4, "ms": [["M1", "(3t + 1)(t − 1) = 0"], ["A1", "t = 1 or t = −⅓"], ["A1", "θ = π/2 (1.57)"], ["A1", "θ = 2π + 2arctan(−⅓) = 5.64"]]}]}, {"stem": "", "parts": [{"q": "Use t = tan(θ/2) to prove that sin θ/(1 + cos θ) = tan(θ/2).", "m": 3, "ms": [["M1", "1 + cos θ = 2/(1 + t²)"], ["M1", "divides 2t/(1 + t²) by 2/(1 + t²)"], ["A1", "= t = tan(θ/2)"]]}]}, {"stem": "", "parts": [{"q": "Show that sec θ + tan θ = (1 + t)/(1 − t), where t = tan(θ/2).", "m": 3, "ms": [["M1", "(1 + t²)/(1 − t²) + 2t/(1 − t²)"], ["A1", "(1 + t)²/[(1 − t)(1 + t)]"], ["A1", "(1 + t)/(1 − t)"]]}, {"q": "Hence solve sec θ + tan θ = 3 for 0 &lt; θ &lt; π/2.", "m": 2, "ms": [["M1", "1 + t = 3 − 3t, so t = ½"], ["A1", "θ = 2arctan ½ = 0.927"]], "ans": {"a": 0.927295218, "tol": 0.002, "unit": ""}}]}]}}, {"id": "fp1-taylor", "module": "fp1", "title": "Taylor expansions about a non-zero point", "refs": "2.1–2.2", "notes": ["Taylor expansion about x=a uses h=x−a and derivatives evaluated at a. The expansion is f(a)+hf′(a)+h²f″(a)/2!+… . Retain enough terms before dividing by a power of h or taking a limit, and identify any interval required for convergence.", "A numerical approximation should state the expansion point, retained order and why the input is close to that point. A truncated series is not an equality valid for every x. The leading neglected term can give a useful indication of error, but is not automatically a rigorous error bound."], "example": {"q": "Expand ln x about x=1 through (x−1)³.", "steps": ["Let h=x−1.", "At 1, f=0, f′=1, f″=−1 and f‴=2.", "ln x = h−h²/2+h³/3+… .", "The power series converges for |h|<1; endpoints require separate checks."]}, "practice": {"q": "Find the quadratic Taylor approximation to √x about x=4.", "answer": null, "steps": ["f(4)=2, f′(4)=1/4 and f″(4)=−1/32.", "Let h=x−4.", "√x≈2+h/4−h²/64.", "Use the approximation close to x=4 and distinguish it from an exact identity."]}, "check": {"q": "What is the coefficient of (x−1)² in the Taylor expansion of ln x about 1?", "a": -0.5}, "deep": {"tip": "Set h = x − a and tabulate f(a), f′(a), f″(a), … before writing the series, remembering the factorial under each derivative. A Taylor polynomial is only reliable near x = a, so choose the centre closest to the value you want and say how far from it you are.", "examples": [{"title": "Expanding about π/6", "q": "Find the Taylor series of sin x in ascending powers of (x − π/6) up to the term in (x − π/6)².", "steps": ["f(x) = sin x, f′(x) = cos x, f″(x) = −sin x.", "At x = π/6: f = ½, f′ = √3/2, f″ = −½.", "f(x) ≈ f(a) + f′(a)h + f″(a)h²/2 with h = x − π/6.", "sin x ≈ ½ + (√3/2)(x − π/6) − ¼(x − π/6)²."]}, {"title": "An exponential about x = 1", "q": "Find the Taylor series of eˣ about x = 1 up to the term in (x − 1)³.", "steps": ["Every derivative of eˣ is eˣ, so each equals e at x = 1.", "eˣ ≈ e + e(x − 1) + e(x − 1)²/2! + e(x − 1)³/3!.", "eˣ ≈ e[1 + (x − 1) + ½(x − 1)² + ⅙(x − 1)³]."]}], "fills": [{"q": "f(x) = x³ about x = 2.", "lines": ["f(2) = [[8]] and f′(2) = [[12]]"]}, {"q": "ln x about x = 1.", "lines": ["the coefficient of (x − 1)² is −1/[[2]]"]}, {"q": "cos x about x = π/2.", "lines": ["the coefficient of (x − π/2) is [[-1]]"]}], "exam": [{"stem": "<p>f(x) = tan x.</p>", "parts": [{"q": "Show that f″(x) = 2sec²x tan x.", "m": 2, "ms": [["M1", "f′(x) = sec²x and uses the chain rule"], ["A1", "2sec x × sec x tan x = 2sec²x tan x"]]}, {"q": "Find the Taylor series of tan x in ascending powers of (x − π/4) up to the term in (x − π/4)².", "m": 3, "ms": [["M1", "f(π/4) = 1, f′(π/4) = 2, f″(π/4) = 4"], ["A1", "1 + 2(x − π/4)"], ["A1", "+ 2(x − π/4)²"]]}, {"q": "Use your series to estimate tan 0.8, to 4 decimal places.", "m": 2, "ms": [["M1", "h = 0.8 − π/4 = 0.0146…"], ["A1", "1.0296"]], "ans": {"a": 1.0296, "tol": 0.0001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Find the Taylor series of 1/x about x = 2 up to and including the term in (x − 2)³.", "m": 4, "ms": [["M1", "derivatives −x⁻², 2x⁻³, −6x⁻⁴"], ["A1", "f(2) = ½ and f′(2) = −¼"], ["A1", "f″(2) = ¼ and f‴(2) = −⅜"], ["A1", "½ − ¼(x − 2) + ⅛(x − 2)² − (1/16)(x − 2)³"]]}]}, {"stem": "", "parts": [{"q": "Find the Taylor series of ln x about x = e up to and including the term in (x − e)².", "m": 3, "ms": [["M1", "f(e) = 1, f′(e) = 1/e, f″(e) = −1/e²"], ["A1", "1 + (x − e)/e"], ["A1", "− (x − e)²/(2e²)"]]}]}]}}, {"id": "fp1-leibniz", "module": "fp1", "title": "Leibniz differentiation and indeterminate limits", "refs": "2.3–2.4", "notes": ["Leibniz’s theorem gives the nth derivative of a product as a binomial sum of derivatives of its factors. When one factor is a low-degree polynomial, most terms vanish. Check the derivative orders and binomial coefficients explicitly.", "L’Hospital’s rule applies to suitable 0/0 or infinity/infinity limits when its hypotheses are met. Differentiate numerator and denominator separately, not the quotient as one function. Recheck the indeterminate form before applying the rule again; it is not a replacement for ordinary substitution in a determinate limit."], "example": {"q": "Find the nth derivative of x eˣ and evaluate the limit of (eˣ−1−x)/x² as x→0.", "steps": ["Only the zeroth and first derivatives of x are non-zero.", "Leibniz gives eˣ(x+n).", "The limit is 0/0; apply L’Hospital to obtain (eˣ−1)/(2x).", "It remains 0/0; apply the rule again to obtain eˣ/2.", "The limit is 1/2."]}, "practice": {"q": "Find the nth derivative of x²eˣ.", "answer": null, "steps": ["The surviving derivatives of x² are x², 2x and 2.", "Leibniz gives eˣ[x²+2nx+n(n−1)].", "The expression also works for n=0 and n=1.", "Check n=2 by differentiating twice."]}, "check": {"q": "Evaluate the limit of (eˣ−1−x)/x² as x tends to 0.", "a": 0.5}, "deep": {"tip": "For a product, let u be the factor whose derivatives vanish after a few steps, so the Leibniz sum stops early; write the binomial coefficients first. Before using L’Hôpital’s rule, confirm that the limit really has the form 0/0 or ∞/∞, and re-check that form each time you apply the rule again.", "examples": [{"title": "Leibniz’s theorem", "q": "Find the fourth derivative of x² sin x.", "steps": ["Take u = x² (derivatives 2x, 2, 0) and v = sin x.", "Fourth derivative = u v⁗ + 4u′v‴ + 6u″v″, the later terms being zero.", "= x² sin x + 4(2x)(−cos x) + 6(2)(−sin x).", "= x² sin x − 8x cos x − 12 sin x."]}, {"title": "L’Hôpital’s rule used three times", "q": "Find the limit of (sin x − x)/x³ as x → 0.", "steps": ["The form is 0/0: differentiate top and bottom to get (cos x − 1)/3x².", "Still 0/0: differentiate again to get −sin x/6x.", "Still 0/0: differentiate again to get −cos x/6.", "The limit is −1/6."]}], "fills": [{"q": "A binomial coefficient in Leibniz’s theorem.", "lines": ["⁵C₂ = [[10]]"]}, {"q": "A standard limit.", "lines": ["the limit of sin 3x / x as x → 0 is [[3]]"]}, {"q": "The third derivative of e^(2x) at x = 0.", "lines": ["2³ = [[8]]"]}], "exam": [{"stem": "", "parts": [{"q": "Use Leibniz’s theorem to find the fifth derivative of x³e^(2x).", "m": 4, "ms": [["M1", "Leibniz with u = x³, v = e^(2x), terms r = 0 to 3"], ["M1", "uses 3x², 6x, 6 and powers of 2 from e^(2x)"], ["A1", "32x³e^(2x) + 240x²e^(2x)"], ["A1", "e^(2x)(32x³ + 240x² + 480x + 240)"]]}]}, {"stem": "", "parts": [{"q": "Find the limit of (e^(2x) − 1 − 2x)/x² as x → 0.", "m": 3, "ms": [["M1", "L’Hôpital: (2e^(2x) − 2)/2x"], ["M1", "applies the rule again: 4e^(2x)/2"], ["A1", "2"]], "ans": {"a": 2.0, "tol": 0.001, "unit": ""}}, {"q": "Find the limit of [x − ln(1 + x)]/(1 − cos x) as x → 0.", "m": 3, "ms": [["M1", "[1 − 1/(1 + x)]/sin x"], ["M1", "applies the rule again: (1 + x)⁻²/cos x"], ["A1", "1"]], "ans": {"a": 1.0, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Find the limit of (1 − sin x)/cos²x as x → π/2.", "m": 3, "ms": [["M1", "form 0/0; differentiates: −cos x/(−2cos x sin x)"], ["M1", "cancels cos x: 1/(2sin x)"], ["A1", "½"]], "ans": {"a": 0.5, "tol": 0.001, "unit": ""}}]}]}}, {"id": "fp1-weierstrass", "module": "fp1", "title": "Weierstrass substitution in integration", "refs": "2.5", "notes": ["The substitution t=tan(x/2) makes sine and cosine rational: sin x=2t/(1+t²), cos x=(1−t²)/(1+t²), and dx=2dt/(1+t²). Transform the differential as well as the integrand and apply ordinary rational integration.", "The substitution is local to an interval avoiding its singular points. An antiderivative may have different equivalent inverse-trigonometric forms on different intervals. For a definite integral, transform the limits carefully and check whether the interval crosses a substitution discontinuity."], "example": {"q": "Find ∫dx/(2+cos x) using t=tan(x/2).", "steps": ["2+cos x=(3+t²)/(1+t²).", "The integral becomes ∫2dt/(t²+3).", "An antiderivative is (2/√3)arctan(t/√3)+C.", "Replace t by tan(x/2), on an interval where the substitution is valid."]}, "practice": {"q": "Use the same substitution to find ∫dx/(3+2cos x).", "answer": null, "steps": ["3+2cos x=(5+t²)/(1+t²).", "The integral becomes ∫2dt/(t²+5).", "The result is (2/√5)arctan[tan(x/2)/√5]+C.", "State that a suitable continuous branch is used."]}, "check": {"q": "For t=tan(x/2), what is dt/dx at x=0?", "a": 0.5}, "deep": {"tip": "Replace dx as well as the trigonometric functions: dx = 2dt/(1 + t²). The factor 1 + t² usually cancels, leaving a rational function of t. Change the limits to values of t, or substitute back, and keep to an interval of x on which tan(x/2) is continuous.", "examples": [{"title": "A denominator that becomes a perfect square", "q": "Find ∫ 1/(1 + sin x) dx using t = tan(x/2).", "steps": ["1 + sin x = 1 + 2t/(1 + t²) = (1 + t)²/(1 + t²).", "dx = 2dt/(1 + t²), so the integral is ∫ 2/(1 + t)² dt.", "= −2/(1 + t) + c.", "= −2/(1 + tan(x/2)) + c."]}, {"title": "A definite integral with new limits", "q": "Evaluate ∫ 1/(5 + 4cos x) dx from 0 to π/2.", "steps": ["5 + 4cos x = [5(1 + t²) + 4(1 − t²)]/(1 + t²) = (9 + t²)/(1 + t²).", "The integral becomes ∫ 2/(9 + t²) dt.", "Limits: x = 0 gives t = 0 and x = π/2 gives t = 1.", "[⅔ arctan(t/3)] from 0 to 1 = ⅔ arctan ⅓ ≈ 0.2145."]}], "fills": [{"q": "The differential.", "lines": ["dx = [[2]] dt/(1 + t²)"]}, {"q": "Changing a limit.", "lines": ["x = π/2 gives t = [[1]]"]}, {"q": "A useful combination.", "lines": ["1 + cos x = [[2]]/(1 + t²)"]}], "exam": [{"stem": "", "parts": [{"q": "Using t = tan(x/2), show that ∫ 1/(1 + sin x + cos x) dx = ∫ 1/(1 + t) dt.", "m": 3, "ms": [["M1", "substitutes for sin x, cos x and dx"], ["M1", "denominator (2 + 2t)/(1 + t²)"], ["A1", "∫ 2/(2 + 2t) dt = ∫ 1/(1 + t) dt"]]}, {"q": "Hence find the exact value of the integral from 0 to π/2.", "m": 2, "ms": [["M1", "[ln(1 + t)] from 0 to 1"], ["A1", "ln 2"]], "ans": {"a": 0.6931471806, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Use the substitution t = tan(x/2) to find the exact value of ∫ 1/(2 − cos x) dx from 0 to π/2.", "m": 5, "ms": [["M1", "substitutes for cos x and dx"], ["A1", "∫ 2/(1 + 3t²) dt"], ["M1", "k arctan(√3 t)"], ["A1", "(2/√3) arctan(√3 t) from 0 to 1"], ["A1", "2π/(3√3) = 2√3π/9"]], "ans": {"a": 1.2091995762, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Use the substitution t = tan(x/2) to show that ∫ cosec x dx = ln|tan(x/2)| + c.", "m": 3, "ms": [["M1", "cosec x = (1 + t²)/2t and dx = 2dt/(1 + t²)"], ["A1", "∫ 1/t dt"], ["A1", "ln|t| + c = ln|tan(x/2)| + c"]]}]}]}}, {"id": "fp1-de-series", "module": "fp1", "title": "Taylor methods and substitutions for differential equations", "refs": "3", "notes": ["Successive derivatives of a differential equation can produce a local Taylor solution from initial data. Calculate each derivative from the original relation before evaluating it at the starting point. A transformed dependent variable can also make a non-linear-looking equation separable or linear.", "The resulting finite polynomial is an approximation near the initial point, not the complete exact solution. In an exact substitution, recover the original dependent variable and apply its original initial condition. Always test whether a substitution introduces restrictions or excludes a constant solution."], "example": {"q": "For y′=x+y and y(0)=1, find the cubic Taylor approximation at zero.", "steps": ["y′(0)=1.", "Differentiate: y″=1+y′, so y″(0)=2.", "Then y‴=y″, so y‴(0)=2.", "y≈1+x+x²+x³/3."]}, "practice": {"q": "For y′=y² and y(0)=1, find the cubic Taylor polynomial.", "answer": null, "steps": ["y′(0)=1.", "y″=2yy′=2y³, giving y″(0)=2.", "y‴=6y²y′=6y⁴, giving y‴(0)=6.", "The polynomial is 1+x+x²+x³.", "It agrees locally with the exact solution 1/(1−x)."]}, "check": {"q": "For y′=x+y and y(0)=1, find y″(0).", "a": 2}, "deep": {"tip": "For a series solution, differentiate the differential equation itself to obtain each higher derivative, and evaluate at the initial point after every differentiation. For a substitution, differentiate the substitution first, replace dy/dx completely, and only then solve; return to the original variables at the end.", "examples": [{"title": "A series solution of a second-order equation", "q": "y″ = 2y′ − xy with y = 1 and y′ = 2 at x = 0. Find the series solution up to the term in x³.", "steps": ["At x = 0: y″ = 2(2) − 0 = 4.", "Differentiate: y‴ = 2y″ − y − xy′.", "At x = 0: y‴ = 8 − 1 − 0 = 7.", "y ≈ 1 + 2x + (4/2!)x² + (7/3!)x³ = 1 + 2x + 2x² + (7/6)x³."]}, {"title": "A substitution that separates the variables", "q": "Use u = x + y to solve dy/dx = (x + y)².", "steps": ["du/dx = 1 + dy/dx, so du/dx = 1 + u².", "∫ du/(1 + u²) = ∫ dx gives arctan u = x + c.", "u = tan(x + c).", "y = tan(x + c) − x."]}], "fills": [{"q": "y′ = x² + y with y(0) = 2.", "lines": ["y′(0) = [[2]] and, since y″ = 2x + y′, y″(0) = [[2]]"]}, {"q": "y′ = 1 + y² with y(0) = 0.", "lines": ["y″ = 2yy′ and y‴ = 2(y′)² + 2yy″, so y‴(0) = [[2]]"]}, {"q": "The substitution z = y².", "lines": ["dz/dx = [[2]]y dy/dx"]}], "exam": [{"stem": "<p>d²y/dx² + x dy/dx + y = 0, with y = 1 and dy/dx = 0 at x = 0.</p>", "parts": [{"q": "Find the value of d²y/dx² at x = 0.", "m": 1, "ms": [["B1", "−1"]], "ans": {"a": -1.0, "tol": 0.001, "unit": ""}}, {"q": "Show that d³y/dx³ + x d²y/dx² + 2 dy/dx = 0.", "m": 2, "ms": [["M1", "differentiates, using the product rule on x dy/dx"], ["A1", "y‴ + xy″ + y′ + y′ = 0"]]}, {"q": "Find the series solution for y up to and including the term in x⁴.", "m": 4, "ms": [["M1", "differentiates again: y⁗ + xy‴ + 3y″ = 0"], ["A1", "y‴(0) = 0 and y⁗(0) = 3"], ["M1", "uses the Taylor formula with 2! and 4!"], ["A1", "y = 1 − x²/2 + x⁴/8"]]}]}, {"stem": "<p>dy/dx = (x² + y²)/(xy), x &gt; 0.</p>", "parts": [{"q": "Use the substitution y = ux to show that x du/dx = 1/u.", "m": 3, "ms": [["M1", "dy/dx = u + x du/dx"], ["M1", "right-hand side becomes (1 + u²)/u"], ["A1", "x du/dx = 1/u"]]}, {"q": "Given that y = 2 when x = 1, find y² in terms of x.", "m": 4, "ms": [["M1", "separates: ∫ u du = ∫ dx/x"], ["A1", "½u² = ln x + c"], ["M1", "uses u = 2 when x = 1: c = 2"], ["A1", "y² = 2x²(ln x + 2)"]]}]}, {"stem": "<p>dy/dx = x² − y², with y = 1 at x = 0.</p>", "parts": [{"q": "Find a series solution for y up to and including the term in x³.", "m": 4, "ms": [["M1", "y′(0) = −1 and y″ = 2x − 2yy′"], ["A1", "y″(0) = 2"], ["M1", "y‴ = 2 − 2(y′)² − 2yy″, giving −4"], ["A1", "y = 1 − x + x² − ⅔x³"]]}, {"q": "Use your series to estimate y when x = 0.1, to 4 decimal places.", "m": 1, "ms": [["B1", "0.9093"]], "ans": {"a": 0.9093, "tol": 0.0001, "unit": ""}}]}]}}, {"id": "fp1-conics", "module": "fp1", "title": "Conics, eccentricity, tangents and loci", "refs": "4", "notes": ["Parabolas, ellipses and hyperbolas can be described by focus–directrix relationships. For x²/a²+y²/b²=1 with a>b>0, the foci are (±ae,0), e²=1−b²/a² and the directrices are x=±a/e. A hyperbola instead has e²=1+b²/a².", "Use implicit or parametric differentiation to obtain a tangent. At a point on an ellipse, the tangent is xx₁/a²+yy₁/b²=1. Check that the point lies on the curve before using a tangent formula. A parabola y²=4ax has focus (a,0) and directrix x=−a."], "example": {"q": "For x²/25+y²/9=1, find the eccentricity, foci and tangent at (3,12/5).", "steps": ["a=5 and b=3, so e²=1−9/25=16/25.", "e=4/5; the foci are (±4,0).", "The point satisfies 9/25+144/225=1.", "The tangent is 3x/25+(12/5)y/9=1.", "Equivalently 9x+20y=75."]}, "practice": {"q": "For y²=12x, find the focus, directrix and tangent at (3,6).", "answer": null, "steps": ["4a=12 gives a=3.", "Focus (3,0); directrix x=−3.", "Differentiate: 2y y′=12, so at the point the gradient is 1.", "The tangent is y−6=x−3, or y=x+3."]}, "check": {"q": "For x²/25+y²/9=1, find the positive x-coordinate of a focus.", "a": 4}, "deep": {"tip": "Identify the conic and its parameters (a, b, e or the focal length) before any calculus. Parametric points such as (at², 2at), (a cos θ, b sin θ) and (ct, c/t) make gradients short: dy/dx = (dy/dt)/(dx/dt). For a locus, eliminate the parameter at the very end.", "examples": [{"title": "A hyperbola and its features", "q": "For the hyperbola x²/16 − y²/9 = 1, find the eccentricity, the foci, the directrices and the asymptotes.", "steps": ["a = 4, b = 3 and b² = a²(e² − 1), so e² = 1 + 9/16.", "e = 5/4.", "Foci (±ae, 0) = (±5, 0); directrices x = ±a/e = ±16/5.", "Asymptotes y = ±(b/a)x = ±¾x."]}, {"title": "Tangent and normal to a parabola", "q": "The point P on y² = 8x has parameter t = 3. Find the tangent and the normal at P.", "steps": ["y² = 4ax with a = 2, so P = (at², 2at) = (18, 12).", "dy/dx = (2a)/(2at) = 1/t = ⅓.", "Tangent: y − 12 = ⅓(x − 18), that is 3y = x + 18.", "Normal has gradient −3: y − 12 = −3(x − 18), that is y + 3x = 66."]}, {"title": "Tangent to a rectangular hyperbola", "q": "Find the equation of the tangent to xy = 16 at the point (4t, 4/t).", "steps": ["y = 16/x, so dy/dx = −16/x² = −1/t² at x = 4t.", "y − 4/t = −(1/t²)(x − 4t).", "Multiply by t²: t²y − 4t = −x + 4t.", "x + t²y = 8t."]}], "fills": [{"q": "Ellipse x²/25 + y²/16 = 1.", "lines": ["e = √(1 − 16/25) = [[0.6]]"]}, {"q": "Parabola y² = 20x.", "lines": ["focus ([[5]], 0)"]}, {"q": "Rectangular hyperbola xy = 9.", "lines": ["c = [[3]]"]}], "exam": [{"stem": "<p>The ellipse E has equation x²/9 + y²/4 = 1.</p>", "parts": [{"q": "Find the eccentricity of E.", "m": 2, "ms": [["M1", "b² = a²(1 − e²): 4 = 9(1 − e²)"], ["A1", "e = √5/3"]], "ans": {"a": 0.7453559925, "tol": 0.001, "unit": ""}}, {"q": "Write down the coordinates of the foci and the equations of the directrices.", "m": 2, "ms": [["B1", "foci (±√5, 0)"], ["B1", "directrices x = ±9/√5"]]}, {"q": "Show that the tangent to E at P(3cos θ, 2sin θ) has equation 2x cos θ + 3y sin θ = 6.", "m": 4, "ms": [["M1", "dy/dx = (2cos θ)/(−3sin θ)"], ["A1", "gradient −2cos θ/(3sin θ)"], ["M1", "y − 2sin θ = m(x − 3cos θ)"], ["A1", "uses cos²θ + sin²θ = 1 to reach the given equation"]]}]}, {"stem": "<p>The point P(t², 2t) lies on the parabola y² = 4x.</p>", "parts": [{"q": "Show that the normal at P has equation y + tx = 2t + t³.", "m": 4, "ms": [["M1", "dy/dx = 1/t"], ["M1", "normal gradient −t"], ["M1", "y − 2t = −t(x − t²)"], ["A1", "y + tx = 2t + t³"]]}, {"q": "The normal at the point where t = 1 meets the parabola again at Q. Find the coordinates of Q.", "m": 3, "ms": [["M1", "normal y + x = 3 with (s², 2s): s² + 2s − 3 = 0"], ["A1", "s = −3"], ["A1", "Q(9, −6)"]]}]}, {"stem": "<p>The point P(4p, 4/p), p &gt; 0, lies on the rectangular hyperbola xy = 16. The tangent at P meets the axes at A and B.</p>", "parts": [{"q": "Show that the area of triangle OAB is the same for every position of P.", "m": 5, "ms": [["M1", "dy/dx = −1/p²"], ["A1", "tangent x + p²y = 8p"], ["M1", "sets y = 0 and x = 0"], ["A1", "A(8p, 0) and B(0, 8/p)"], ["A1", "area = ½ × 8p × 8/p = 32, independent of p"]]}]}]}}, {"id": "fp1-cross", "module": "fp1", "title": "Vector products, areas and triple products", "refs": "5", "notes": ["The vector product a×b is perpendicular to both vectors; its magnitude is the area of their parallelogram. Its order matters because b×a=−a×b. Use components with a consistent cofactor-sign pattern and check that the result has zero scalar product with each original vector.", "The absolute scalar triple product |a·(b×c)| is a parallelepiped volume; divide by 6 for the tetrahedron formed by the three edges from a common vertex. A zero triple product indicates coplanarity, provided the geometrical interpretation uses the correct common origin."], "example": {"q": "For a=(1,0,1), b=(0,2,0), find a×b and the triangle area.", "steps": ["a×b=(−2,0,2).", "Its magnitude is √8=2√2.", "The triangle area is half the parallelogram area: √2.", "Both a·(a×b) and b·(a×b) equal zero."]}, "practice": {"q": "Find the volume of the tetrahedron with edge vectors (2,0,0), (0,3,0), (0,0,4) from the same vertex.", "answer": 4, "steps": ["The scalar triple product has magnitude 2×3×4=24.", "A tetrahedron occupies one sixth of that parallelepiped.", "Volume=24/6=4."]}, "check": {"q": "Find the volume of a parallelepiped with perpendicular edge lengths 2,3,4.", "a": 24}, "deep": {"tip": "Set the vector product out as a determinant and check it with two scalar products, both of which must be zero. Its magnitude is the area of a parallelogram, so halve it for a triangle; the scalar triple product gives the volume of a parallelepiped, so divide by 6 for a tetrahedron.", "examples": [{"title": "A vector product and an area", "q": "a = (2,1,−1) and b = (1,3,2). Find a × b and the area of the parallelogram with sides a and b.", "steps": ["a × b = (1×2 − (−1)×3, (−1)×1 − 2×2, 2×3 − 1×1).", "= (5, −5, 5).", "Check: a·(a × b) = 10 − 5 − 5 = 0 and b·(a × b) = 5 − 15 + 10 = 0.", "Area = |a × b| = 5√3."]}, {"title": "A plane from three points", "q": "Find a Cartesian equation of the plane through A(1,1,0), B(2,0,1) and C(0,2,3).", "steps": ["AB = (1,−1,1) and AC = (−1,1,3).", "AB × AC = (−3 − 1, −1 − 3, 1 − 1) = (−4, −4, 0).", "A normal is (1, 1, 0), so the plane is x + y = d.", "Using A: d = 2, so x + y = 2; B and C both satisfy this."]}, {"title": "A scalar triple product", "q": "Find the volume of the parallelepiped with edges a = (1,2,0), b = (0,1,3) and c = (2,0,1).", "steps": ["Volume = |a·(b × c)|, the determinant with rows a, b, c.", "= 1(1 − 0) − 2(0 − 6) + 0.", "= 13."]}], "fills": [{"q": "Unit vectors.", "lines": ["(1,0,0) × (0,1,0) = (0, 0, [[1]])"]}, {"q": "|a| = 3, |b| = 4 and the angle between them is 30°.", "lines": ["|a × b| = 3 × 4 × ½ = [[6]]"]}, {"q": "A vector product is perpendicular to both factors.", "lines": ["a·(a × b) = [[0]]"]}], "exam": [{"stem": "<p>A(1, 0, 2), B(3, 1, 1) and C(2, −1, 4).</p>", "parts": [{"q": "Find AB × AC.", "m": 3, "ms": [["M1", "AB = (2,1,−1) and AC = (1,−1,2)"], ["A1", "two correct components"], ["A1", "(1, −5, −3)"]]}, {"q": "Find the exact area of triangle ABC.", "m": 2, "ms": [["M1", "½|AB × AC|"], ["A1", "½√35"]], "ans": {"a": 2.9580398915, "tol": 0.001, "unit": ""}}, {"q": "Find a Cartesian equation of the plane ABC.", "m": 2, "ms": [["M1", "x − 5y − 3z = d with a point substituted"], ["A1", "x − 5y − 3z = −5"]]}]}, {"stem": "", "parts": [{"q": "The tetrahedron OABC has OA = (2,1,0), OB = (1,3,1) and OC = (0,1,4). Find its volume.", "m": 3, "ms": [["M1", "scalar triple product as a 3 × 3 determinant"], ["A1", "18"], ["A1", "volume = 18/6 = 3"]], "ans": {"a": 3.0, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>The line l passes through the point with position vector a = (1,2,−1) and has direction d = (2,1,2).</p>", "parts": [{"q": "Write down an equation of l in the form (r − a) × d = 0.", "m": 1, "ms": [["B1", "(r − (1,2,−1)) × (2,1,2) = 0"]]}, {"q": "Find the shortest distance from the origin to l.", "m": 4, "ms": [["M1", "a × d"], ["A1", "(5, −4, −3)"], ["M1", "|a × d|/|d| = √50/3"], ["A1", "5√2/3"]], "ans": {"a": 2.357022604, "tol": 0.001, "unit": ""}}]}]}}, {"id": "fp1-numerical", "module": "fp1", "title": "Simpson, numerical differential equations and inequalities", "refs": "6–7", "notes": ["Simpson’s rule uses an even number of equal subintervals and alternating weights 1,4,2,4,…,2,4,1. Its estimate is h/3 times the weighted sum. State the interval and spacing before inserting values. Euler and central-difference methods require equally careful indexing of the point or derivative being approximated.", "For rational or modulus inequalities, locate zeros and excluded denominator values before testing sign intervals. Multiplying through by an expression of unknown sign is unsafe. A numerical approximation can suggest a solution, but algebra and sign checks establish the inequality intervals."], "example": {"q": "Use Simpson’s rule with 2 intervals to estimate ∫₀²x² dx, then solve (x−1)/(x+2)>0.", "steps": ["h=1 and ordinates are 0,1,4.", "Simpson estimate=(1/3)(0+4×1+4)=8/3, exact here.", "The sign boundaries are x=−2 and x=1.", "The quotient is positive when x<−2 or x>1.", "Exclude −2 because the expression is undefined, and 1 because the inequality is strict."]}, "practice": {"q": "Use one Euler step of length 0.1 for y′=x+y from (0,1).", "answer": 1.1, "steps": ["Initial gradient=0+1=1.", "y₁=1+0.1×1=1.1 at x₁=0.1.", "This is a numerical estimate, not an exact solution."]}, "check": {"q": "How many subintervals are used when Simpson ordinates are y₀,y₁,y₂,y₃,y₄?", "a": 4}, "deep": {"tip": "Tabulate ordinates to at least one more decimal place than the answer needs, and check that Simpson’s rule has an even number of strips. For an inequality, never multiply by an expression whose sign is unknown: collect everything on one side as a single fraction, find the critical values and test each region.", "examples": [{"title": "Simpson’s rule with four strips", "q": "Use Simpson’s rule with 4 strips to estimate ∫ ln x dx from 1 to 3.", "steps": ["h = 0.5; ordinates 0, 0.405465, 0.693147, 0.916291, 1.098612.", "Estimate = (h/3)[y₀ + y₄ + 4(y₁ + y₃) + 2y₂].", "= (0.5/3)[1.098612 + 5.287024 + 1.386294].", "= 1.2953 (4 d.p.); the exact value 3ln 3 − 2 is 1.2958."]}, {"title": "A rational inequality", "q": "Solve 2x/(x − 1) < 3.", "steps": ["2x/(x − 1) − 3 < 0.", "(2x − 3x + 3)/(x − 1) < 0, that is (3 − x)/(x − 1) < 0.", "Critical values x = 1 and x = 3; test a value in each region.", "x < 1 or x > 3."]}, {"title": "A two-step numerical solution", "q": "dy/dx = x − y² with y = 1 at x = 0. Use h = 0.1 with y₁ ≈ y₀ + hf(x₀, y₀) and then y₂ ≈ y₀ + 2hf(x₁, y₁) to estimate y at x = 0.2.", "steps": ["f(0, 1) = −1, so y₁ ≈ 1 − 0.1 = 0.9.", "f(0.1, 0.9) = 0.1 − 0.81 = −0.71.", "y₂ ≈ 1 + 0.2 × (−0.71).", "y(0.2) ≈ 0.858."]}], "fills": [{"q": "Simpson’s rule weights for four strips.", "lines": ["1, 4, [[2]], 4, 1"]}, {"q": "One Euler step for y′ = 2x + y from (0, 1) with h = 0.1.", "lines": ["y₁ = [[1.1]]"]}, {"q": "Solve x² > 4.", "lines": ["x > 2 or x < [[-2]]"]}], "exam": [{"stem": "", "parts": [{"q": "Use Simpson’s rule with 4 strips to estimate ∫ 1/(1 + x²) dx from 0 to 1, giving your answer to 4 decimal places.", "m": 3, "ms": [["M1", "h = 0.25 with ordinates 1, 0.941176, 0.8, 0.64, 0.5"], ["M1", "(0.25/3)[1.5 + 4(1.581176) + 2(0.8)]"], ["A1", "0.7854"]], "ans": {"a": 0.7854, "tol": 0.0001, "unit": ""}}, {"q": "Hence obtain an estimate for π.", "m": 1, "ms": [["B1", "4 × 0.7854 = 3.1416"]], "ans": {"a": 3.1416, "tol": 0.0001, "unit": ""}}]}, {"stem": "<p>dy/dx = x² + y, with y = 1 at x = 0. Use a step length of 0.1.</p>", "parts": [{"q": "Use y₁ ≈ y₀ + h(dy/dx)₀ to estimate y at x = 0.1.", "m": 2, "ms": [["M1", "1 + 0.1 × (0 + 1)"], ["A1", "1.1"]], "ans": {"a": 1.1, "tol": 0.001, "unit": ""}}, {"q": "Use y₂ ≈ y₀ + 2h(dy/dx)₁ to estimate y at x = 0.2.", "m": 2, "ms": [["M1", "1 + 0.2 × (0.01 + 1.1)"], ["A1", "1.222"]], "ans": {"a": 1.222, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "Solve (x + 3)/(x − 2) ≥ 2.", "m": 4, "ms": [["M1", "brings 2 to the left-hand side"], ["M1", "single fraction (7 − x)/(x − 2) ≥ 0"], ["A1", "critical values 2 and 7"], ["A1", "2 &lt; x ≤ 7"]]}, {"q": "Solve |2x − 1| &lt; x + 4.", "m": 3, "ms": [["M1", "2x − 1 &lt; x + 4, giving x &lt; 5"], ["M1", "−(2x − 1) &lt; x + 4, giving x &gt; −1"], ["A1", "−1 &lt; x &lt; 5"]]}]}]}}, {"id": "fp2-groups", "module": "fp2", "title": "Groups, subgroups, orders and isomorphisms", "refs": "1", "notes": ["A group has a closed associative operation, an identity and an inverse for every element. Commutativity is an additional property, not a group axiom. A Cayley table can establish closure, identity and inverses in a finite example, but associativity needs justification beyond a visual pattern.", "The order of a finite group is its number of elements; an element’s order is the least positive power giving the identity. Lagrange’s theorem makes subgroup orders divide the group order, but divisibility alone does not prove a subset is a subgroup. An isomorphism is a bijection preserving the operation."], "example": {"q": "In the additive group of integers modulo 6, find the order of 2 and its generated subgroup.", "steps": ["The identity is 0.", "2+2=4 and 2+2+2=0 modulo 6.", "The order of 2 is 3.", "Its generated subgroup is {0,2,4}.", "The subgroup order 3 divides the group order 6."]}, "practice": {"q": "Find the orders of 1 and 3 in the additive group modulo 8.", "answer": null, "steps": ["Repeatedly adding 1 reaches 0 after 8 steps.", "For 3, 8×3=24≡0 modulo 8 and no smaller positive multiple is 0.", "Both elements have order 8.", "Each generates the entire group."]}, "check": {"q": "Find the order of 2 in the additive group modulo 6.", "a": 3}, "deep": {"tip": "Check the four axioms in order: closure, associativity (often inherited from ordinary arithmetic or composition), identity and inverses. Lagrange’s theorem limits the possible orders of subgroups and elements to divisors of the group order; a group is cyclic exactly when some element has order equal to the group order.", "examples": [{"title": "A multiplicative group modulo 8", "q": "Show that G = {1, 3, 5, 7} under multiplication modulo 8 is a group, and find the order of each element.", "steps": ["Closure: 3 × 5 = 15 ≡ 7, 3 × 7 = 21 ≡ 5, 5 × 7 = 35 ≡ 3, and every square is ≡ 1.", "Multiplication modulo 8 is associative; the identity is 1.", "Each element is its own inverse, since a² ≡ 1 for every a in G.", "So G is a group; 1 has order 1 and 3, 5, 7 each have order 2.", "No element has order 4, so G is not cyclic: it is isomorphic to the Klein four-group."]}, {"title": "Lagrange’s theorem", "q": "In the group of integers modulo 12 under addition, find the order of 8 and the subgroup it generates, and list the possible orders of subgroups.", "steps": ["8 + 8 = 16 ≡ 4 and 8 + 8 + 8 = 24 ≡ 0.", "So 8 has order 3 and generates {0, 4, 8}.", "By Lagrange’s theorem the order of any subgroup divides 12.", "Possible orders: 1, 2, 3, 4, 6, 12."]}], "fills": [{"q": "Integers modulo 12 under addition.", "lines": ["the order of 3 is [[4]]"]}, {"q": "Multiplication modulo 7.", "lines": ["the inverse of 5 is [[3]]"]}, {"q": "A group of prime order 7.", "lines": ["the number of subgroups is [[2]]"]}], "exam": [{"stem": "<p>G = {1, 2, 4, 5, 7, 8} under multiplication modulo 9.</p>", "parts": [{"q": "Show that 2 is a generator of G.", "m": 2, "ms": [["M1", "calculates successive powers of 2 modulo 9"], ["A1", "2, 4, 8, 7, 5, 1: all six elements"]]}, {"q": "Find the order of 4.", "m": 1, "ms": [["B1", "3, since 4² ≡ 7 and 4³ ≡ 1"]], "ans": {"a": 3.0, "tol": 0.001, "unit": ""}}, {"q": "Write down a subgroup of G of order 2.", "m": 1, "ms": [["B1", "{1, 8}"]]}, {"q": "State, with a reason, whether G is isomorphic to the integers modulo 6 under addition.", "m": 2, "ms": [["B1", "both groups are cyclic of order 6"], ["B1", "yes: for example 2ᵏ ↦ k"]]}]}, {"stem": "<p>D₃ is the group of symmetries of an equilateral triangle under composition.</p>", "parts": [{"q": "State the possible orders of subgroups of D₃.", "m": 1, "ms": [["B1", "1, 2, 3 and 6"]]}, {"q": "Explain why D₃ is not cyclic.", "m": 2, "ms": [["B1", "the rotations have order 3 or 1 and the reflections order 2"], ["B1", "no element has order 6, so no single element generates the group"]]}, {"q": "State, with a reason, whether D₃ is abelian.", "m": 1, "ms": [["B1", "no: two different reflections composed in opposite orders give different rotations"]]}]}, {"stem": "<p>The operation ∗ is defined on S = {x ∈ ℝ : x ≠ −1} by a ∗ b = a + b + ab.</p>", "parts": [{"q": "Show that a ∗ b = (1 + a)(1 + b) − 1, and hence show that S is closed under ∗.", "m": 2, "ms": [["M1", "expands (1 + a)(1 + b) − 1"], ["A1", "(1 + a)(1 + b) ≠ 0, so a ∗ b ≠ −1"]]}, {"q": "Show that ∗ is associative.", "m": 2, "ms": [["M1", "writes (a ∗ b) ∗ c using the product form"], ["A1", "both bracketings equal (1 + a)(1 + b)(1 + c) − 1"]]}, {"q": "Find the identity element and the inverse of 3.", "m": 3, "ms": [["B1", "identity 0"], ["M1", "(1 + 3)(1 + b) = 1"], ["A1", "b = −3/4"]]}]}]}}, {"id": "fp2-reduction", "module": "fp2", "title": "Reduction formulae, arc length and surface area", "refs": "2", "notes": ["Integration by parts can connect Iₙ to Iₙ₋₂ or another simpler member of a family. Keep boundary terms until they have been evaluated; a recurrence for definite integrals need not have the same boundary term as one for indefinite integrals.", "Cartesian arc length is ∫√(1+y′²) dx. Surface area around the x-axis is 2π∫y√(1+y′²) dx when the radius is y≥0. Parametric and polar forms use the corresponding element of arc length. The radius factor distinguishes surface area from arc length."], "example": {"q": "Find the length of y=(2/3)x^(3/2) from x=0 to x=3.", "steps": ["y′=√x.", "L=∫₀³√(1+x) dx.", "L=[(2/3)(1+x)^(3/2)]₀³.", "L=(2/3)(8−1)=14/3."]}, "practice": {"q": "If Iₙ=∫₀^(π/2)sinⁿx dx and Iₙ=(n−1)Iₙ₋₂/n, calculate I₄.", "answer": null, "steps": ["I₀=π/2.", "I₂=(1/2)I₀=π/4.", "I₄=(3/4)I₂=3π/16.", "The given recurrence is used only for n≥2."]}, "check": {"q": "If I₀=π/2 and I₂=I₀/2, find I₂/π.", "a": 0.25}, "deep": {"tip": "Integrate by parts so that the power drops, and write the result in terms of Iₙ₋₁ or Iₙ₋₂ before substituting any limits. Evaluate the boundary terms carefully, find the starting integral I₀ or I₁ directly, and step up one index at a time. For arc length and surface area, simplify 1 + (dy/dx)² before integrating; it is often a perfect square.", "examples": [{"title": "A reduction formula with an exponential", "q": "Iₙ = ∫ xⁿeˣ dx from 0 to 1. Show that Iₙ = e − nIₙ₋₁ and find I₃.", "steps": ["By parts: Iₙ = [xⁿeˣ] from 0 to 1 − n∫ xⁿ⁻¹eˣ dx.", "The boundary term is e − 0, so Iₙ = e − nIₙ₋₁ for n ≥ 1.", "I₀ = e − 1, I₁ = e − (e − 1) = 1 and I₂ = e − 2.", "I₃ = e − 3(e − 2) = 6 − 2e."]}, {"title": "Arc length of a catenary", "q": "Find the length of the curve y = cosh x from x = 0 to x = ln 2.", "steps": ["dy/dx = sinh x, so 1 + (dy/dx)² = 1 + sinh²x = cosh²x.", "s = ∫ cosh x dx from 0 to ln 2 = sinh(ln 2).", "sinh(ln 2) = ½(2 − ½).", "s = ¾."]}, {"title": "A surface of revolution", "q": "The arc of y = x³ from x = 0 to x = 1 is rotated through 2π about the x-axis. Find the exact surface area.", "steps": ["S = 2π∫ y√(1 + (dy/dx)²) dx = 2π∫ x³√(1 + 9x⁴) dx.", "By inspection the integral is (1/36) × (2/3)(1 + 9x⁴)^(3/2).", "S = (2π/54)[(1 + 9x⁴)^(3/2)] from 0 to 1.", "S = (π/27)(10√10 − 1)."]}], "fills": [{"q": "Iₙ = ∫ cosⁿx dx from 0 to π/2, with Iₙ = ((n − 1)/n)Iₙ₋₂ and I₀ = π/2.", "lines": ["I₂ = π/[[4]]"]}, {"q": "Arc length of y = x from x = 0 to x = 1.", "lines": ["√[[2]]"]}, {"q": "Arc length of y = cosh x from −ln 2 to ln 2.", "lines": ["2 × ¾ = [[1.5]]"]}], "exam": [{"stem": "<p>Iₙ = ∫ xⁿ sin x dx from 0 to π/2, n ≥ 0.</p>", "parts": [{"q": "Show that Iₙ = n(π/2)ⁿ⁻¹ − n(n − 1)Iₙ₋₂ for n ≥ 2.", "m": 4, "ms": [["M1", "integrates by parts once: [−xⁿ cos x] + n∫ xⁿ⁻¹ cos x dx"], ["A1", "the boundary term is 0"], ["M1", "integrates by parts again"], ["A1", "reaches the given formula"]]}, {"q": "Find the exact value of I₄.", "m": 3, "ms": [["B1", "I₀ = 1"], ["M1", "I₂ = π − 2"], ["A1", "I₄ = π³/2 − 12π + 24"]], "ans": {"a": 1.8040264971, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "A curve has parametric equations x = t², y = ⅔t³, 0 ≤ t ≤ √3. Find the length of the curve.", "m": 4, "ms": [["M1", "dx/dt = 2t and dy/dt = 2t²"], ["M1", "√(4t² + 4t⁴) = 2t√(1 + t²)"], ["M1", "integrates: ⅔(1 + t²)^(3/2)"], ["A1", "14/3"]], "ans": {"a": 4.6666666667, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "The arc of y = √(4 − x²) between x = 0 and x = 1 is rotated through 2π about the x-axis. Find the exact area of the surface generated.", "m": 3, "ms": [["M1", "1 + (dy/dx)² = 4/(4 − x²)"], ["M1", "y√(1 + (dy/dx)²) = 2"], ["A1", "2π∫ 2 dx from 0 to 1 = 4π"]], "ans": {"a": 12.5663706144, "tol": 0.001, "unit": ""}}]}]}}, {"id": "fp2-eigen", "module": "fp2", "title": "Eigenvalues, eigenvectors and diagonalisation", "refs": "3.1–3.2", "notes": ["An eigenvector v is non-zero and satisfies Av=λv. Eigenvalues solve det(A−λI)=0; then solve (A−λI)v=0 for each eigenspace. In 3×3 work, repeated eigenvalues do not automatically provide enough independent eigenvectors for diagonalisation.", "Put independent eigenvectors into the columns of P in the same order as eigenvalues in D, so A=PDP⁻¹. Real symmetric matrices admit orthogonal diagonalisation with a suitable orthonormal eigenbasis. Normalisation changes an eigenvector’s length, not its direction or eigenvalue."], "example": {"q": "Diagonalise A=[[2,1],[1,2]].", "steps": ["det(A−λI)=(2−λ)²−1=(λ−3)(λ−1).", "For λ=3, choose v₁=(1,1).", "For λ=1, choose v₂=(1,−1).", "P=[[1,1],[1,−1]] and D=diag(3,1).", "A=PDP⁻¹; normalised columns would give an orthogonal P."]}, "practice": {"q": "Find the eigenvalues and two independent eigenvectors of [[4,0],[0,−2]].", "answer": null, "steps": ["The characteristic equation is (4−λ)(−2−λ)=0.", "Eigenvalues are 4 and −2.", "Corresponding eigenvectors include (1,0) and (0,1).", "The matrix is already diagonal in this basis."]}, "check": {"q": "What is the larger eigenvalue of [[2,1],[1,2]]?", "a": 3}, "deep": {"tip": "Form det(A − λI) = 0, solve for the eigenvalues, then solve (A − λI)v = 0 separately for each one; any non-zero multiple of an eigenvector is acceptable. Check with trace = sum of eigenvalues and determinant = product. For a symmetric matrix, normalise orthogonal eigenvectors so that P is orthogonal and PᵀAP = D.", "examples": [{"title": "Diagonalising a 2 × 2 matrix", "q": "Find P and D such that P⁻¹AP = D for A = [[3,1],[2,2]].", "steps": ["det(A − λI) = (3 − λ)(2 − λ) − 2 = λ² − 5λ + 4 = 0, so λ = 1 or 4.", "λ = 4: −x + y = 0 gives (1, 1).", "λ = 1: 2x + y = 0 gives (1, −2).", "P = [[1,1],[1,−2]] and D = [[4,0],[0,1]]; check: trace 5 = 4 + 1 and det 4 = 4 × 1."]}, {"title": "Orthogonal diagonalisation", "q": "A = [[2,0,0],[0,3,1],[0,1,3]]. Find an orthogonal matrix P and a diagonal matrix D with PᵀAP = D.", "steps": ["det(A − λI) = (2 − λ)[(3 − λ)² − 1] = (2 − λ)²(4 − λ), so λ = 2 (twice) and 4.", "λ = 2: y + z = 0 gives two orthogonal vectors (1, 0, 0) and (0, 1, −1).", "λ = 4: (0, 1, 1).", "Normalise: P has columns (1,0,0), (0,1,−1)/√2 and (0,1,1)/√2.", "D = diag(2, 2, 4)."]}], "fills": [{"q": "A = [[2,5],[1,4]].", "lines": ["sum of eigenvalues = [[6]] and product = [[3]]"]}, {"q": "A triangular matrix [[5,2],[0,−1]].", "lines": ["eigenvalues 5 and [[-1]]"]}, {"q": "Eigenvalue 3 with eigenvector v.", "lines": ["A²v = [[9]]v"]}], "exam": [{"stem": "<p>A = [[4,1],[2,3]].</p>", "parts": [{"q": "Find the eigenvalues of A.", "m": 3, "ms": [["M1", "det(A − λI) = 0"], ["M1", "λ² − 7λ + 10 = 0"], ["A1", "λ = 2 and λ = 5"]]}, {"q": "Find a corresponding eigenvector for each eigenvalue.", "m": 2, "ms": [["M1", "solves (A − λI)v = 0 for one eigenvalue"], ["A1", "(1, 1) for 5 and (1, −2) for 2"]]}, {"q": "Write down matrices P and D such that P⁻¹AP = D.", "m": 1, "ms": [["B1", "P = [[1,1],[1,−2]] with D = [[5,0],[0,2]] in the matching order"]]}, {"q": "Hence find A⁴.", "m": 3, "ms": [["M1", "A⁴ = PD⁴P⁻¹"], ["M1", "P⁻¹ = ⅓[[2,1],[1,−1]]"], ["A1", "[[422,203],[406,219]]"]]}]}, {"stem": "<p>C = [[1,2,0],[2,1,0],[0,0,3]].</p>", "parts": [{"q": "Show that (1, 1, 0) is an eigenvector of C and state its eigenvalue.", "m": 2, "ms": [["M1", "C(1,1,0)ᵀ = (3,3,0)ᵀ"], ["A1", "eigenvalue 3"]]}, {"q": "Find the other eigenvalues of C.", "m": 3, "ms": [["M1", "(3 − λ)[(1 − λ)² − 4] = 0"], ["A1", "λ = 3 again"], ["A1", "λ = −1"]]}, {"q": "Find an orthogonal matrix P and a diagonal matrix D such that PᵀCP = D.", "m": 3, "ms": [["M1", "orthogonal eigenvectors (1,1,0), (1,−1,0) and (0,0,1)"], ["A1", "normalised columns (1,1,0)/√2, (1,−1,0)/√2, (0,0,1)"], ["A1", "D = diag(3, −1, 3) in the matching order"]]}]}, {"stem": "", "parts": [{"q": "A 2 × 2 matrix A has eigenvalues 2 and −3 with corresponding eigenvectors (1, 0) and (1, 1). Find A.", "m": 3, "ms": [["M1", "A = PDP⁻¹ with P = [[1,1],[0,1]]"], ["M1", "P⁻¹ = [[1,−1],[0,1]]"], ["A1", "A = [[2,−5],[0,−3]]"]]}]}]}}, {"id": "fp2-cayley", "module": "fp2", "title": "Cayley–Hamilton and matrix powers", "refs": "3.3", "notes": ["Cayley–Hamilton states that a square matrix satisfies its own characteristic polynomial. Replace the scalar variable by A and the constant term by a multiple of I. This gives recurrences for higher powers and can also express an inverse as a polynomial in A when the determinant is non-zero.", "Check the sign convention used for the characteristic polynomial. Matrices generally do not commute, but powers of the same matrix do, so polynomial rearrangements in A are valid. Keep I in constant terms; subtracting a scalar from every entry is not matrix subtraction by a scalar multiple of I."], "example": {"q": "If A has characteristic polynomial λ²−5λ+6, express A³ in terms of A and I.", "steps": ["A²−5A+6I=0.", "A³=5A²−6A.", "Replace A² by 5A−6I.", "A³=19A−30I."]}, "practice": {"q": "For the same nonsingular A, express A⁻¹ in terms of A and I.", "answer": null, "steps": ["Multiply A²−5A+6I=0 by A⁻¹.", "A−5I+6A⁻¹=0.", "A⁻¹=(5I−A)/6.", "The non-zero determinant 6 is consistent with invertibility."]}, "check": {"q": "If A²−5A+6I=0, find the coefficient of A in A³ expressed using only A and I.", "a": 19}, "deep": {"tip": "Write the characteristic equation with λ replaced by A and the constant term multiplied by I. To reach a higher power, multiply through by A and substitute for A² repeatedly; to find an inverse, multiply through by A⁻¹, which is possible exactly when the constant term is non-zero.", "examples": [{"title": "A square and an inverse", "q": "A = [[2,1],[1,3]]. Use the Cayley–Hamilton theorem to express A² and A⁻¹ in terms of A and I.", "steps": ["det(A − λI) = (2 − λ)(3 − λ) − 1 = λ² − 5λ + 5.", "Cayley–Hamilton: A² − 5A + 5I = 0, so A² = 5A − 5I.", "Multiply by A⁻¹: A − 5I + 5A⁻¹ = 0.", "A⁻¹ = (5I − A)/5 = ⅕[[3,−1],[−1,2]]."]}, {"title": "A 3 × 3 matrix", "q": "A = [[1,1,0],[0,2,1],[0,0,3]]. Express A³ and A⁻¹ in terms of A², A and I.", "steps": ["A is triangular, so its eigenvalues are 1, 2, 3 and the characteristic equation is (λ − 1)(λ − 2)(λ − 3) = 0.", "λ³ − 6λ² + 11λ − 6 = 0, so A³ = 6A² − 11A + 6I.", "Multiply by A⁻¹: A² − 6A + 11I − 6A⁻¹ = 0.", "A⁻¹ = (A² − 6A + 11I)/6."]}], "fills": [{"q": "A = [[1,2],[3,4]].", "lines": ["characteristic polynomial λ² − [[5]]λ − [[2]]"]}, {"q": "A² = 3A − 2I.", "lines": ["A³ = 3A² − 2A = [[7]]A − [[6]]I"]}, {"q": "A² = 4A − 3I.", "lines": ["A⁻¹ = (4I − A)/[[3]]"]}], "exam": [{"stem": "<p>A = [[3,−1],[2,0]].</p>", "parts": [{"q": "Find the characteristic equation of A.", "m": 2, "ms": [["M1", "(3 − λ)(−λ) + 2"], ["A1", "λ² − 3λ + 2 = 0"]]}, {"q": "Hence express A⁴ in the form pA + qI.", "m": 3, "ms": [["M1", "A² = 3A − 2I"], ["M1", "A³ = 7A − 6I"], ["A1", "A⁴ = 15A − 14I"]]}, {"q": "Express A⁻¹ in the form rA + sI.", "m": 2, "ms": [["M1", "multiplies A² − 3A + 2I = 0 by A⁻¹"], ["A1", "A⁻¹ = −½A + (3/2)I"]]}]}, {"stem": "<p>A = [[2,0,1],[0,1,0],[1,0,2]].</p>", "parts": [{"q": "Show that the characteristic equation of A is λ³ − 5λ² + 7λ − 3 = 0.", "m": 3, "ms": [["M1", "expands det(A − λI)"], ["M1", "(1 − λ)[(2 − λ)² − 1]"], ["A1", "expands to the given cubic"]]}, {"q": "Hence find A⁻¹ in terms of A², A and I.", "m": 3, "ms": [["M1", "A³ − 5A² + 7A − 3I = 0"], ["M1", "multiplies by A⁻¹"], ["A1", "A⁻¹ = ⅓(A² − 5A + 7I)"]]}]}, {"stem": "<p>A 2 × 2 matrix A satisfies A² − 4A + 3I = 0.</p>", "parts": [{"q": "Find A⁴ in the form pA + qI.", "m": 3, "ms": [["M1", "A³ = 4A² − 3A = 13A − 12I"], ["M1", "A⁴ = 13A² − 12A"], ["A1", "40A − 39I"]]}, {"q": "Explain why A is non-singular and find A⁻¹ in terms of A and I.", "m": 2, "ms": [["B1", "A(4I − A) = 3I, and 3 ≠ 0"], ["B1", "A⁻¹ = ⅓(4I − A)"]]}]}]}}, {"id": "fp2-mapping", "module": "fp2", "title": "Complex mappings and transformed regions", "refs": "4", "notes": ["A complex mapping w=f(z) transforms points and loci between two Argand planes. Write z=x+iy or invert the mapping in a useful form, substitute into the original locus and identify any excluded points. Fractional linear mappings can turn lines and circles into lines or circles.", "The equation |z−a|=k|z−b| is an Apollonius locus, usually a circle when k≠1 and a perpendicular bisector when k=1. Argument inequalities select regions or angular sectors and require attention to branch boundaries and points where the relevant quotient is undefined."], "example": {"q": "Under w=1/z, find the image of the line Re(z)=1.", "steps": ["Let w=u+iv; then z=(u−iv)/(u²+v²).", "Re(z)=u/(u²+v²)=1.", "u²+v²=u, so (u−1/2)²+v²=1/4.", "The image is that circle excluding w=0, since 1/z cannot be zero for finite z."]}, "practice": {"q": "Under w=z², find the image of z=iy with y real.", "answer": null, "steps": ["w=(iy)²=−y².", "The imaginary part is zero.", "The real part is non-positive.", "The image is the non-positive real axis, including zero."]}, "check": {"q": "Under w=z², what is Re(w) when z=2i?", "a": -4}, "deep": {"tip": "Make z the subject (z in terms of w), substitute into the equation of the locus in the z-plane, and then put w = u + iv and simplify. Lines and circles map to lines and circles under w = 1/z and under fractional linear maps; check a couple of individual points to confirm the image and spot any excluded point.", "examples": [{"title": "A circle through the origin under w = 1/z", "q": "Find the image of the circle |z − 1| = 1 under w = 1/z.", "steps": ["z = 1/w, so |1/w − 1| = 1.", "Multiply by |w|: |1 − w| = |w|.", "The points w are equidistant from 0 and 1.", "The image is the line Re(w) = ½ (the point z = 0 has no image)."]}, {"title": "An enlargement and translation", "q": "Find the image of |z| = 1 under w = 2z + 1 − i.", "steps": ["z = (w − 1 + i)/2.", "|(w − (1 − i))/2| = 1.", "The image is the circle |w − (1 − i)| = 2: centre 1 − i, radius 2."]}, {"title": "A sector under w = z²", "q": "Find the image of the region |z| ≤ 2, 0 ≤ arg z ≤ π/4 under w = z².", "steps": ["In polar form, |w| = |z|² and arg w = 2 arg z.", "|w| ≤ 4.", "0 ≤ arg w ≤ π/2.", "The image is the quarter disc of radius 4 in the first quadrant."]}], "fills": [{"q": "w = 3z and |z| = 2.", "lines": ["|w| = [[6]]"]}, {"q": "w = z + 4 − i, image of |z| = 1.", "lines": ["centre ([[4]], [[-1]])"]}, {"q": "w = z² and arg z = π/6.", "lines": ["arg w = π/[[3]]"]}], "exam": [{"stem": "<p>T maps z to w, where w = 1/z, z ≠ 0.</p>", "parts": [{"q": "Show that T maps the line Im(z) = 1 onto a circle, and find its centre and radius.", "m": 5, "ms": [["M1", "z = 1/w = (u − iv)/(u² + v²)"], ["M1", "imaginary part −v/(u² + v²) = 1"], ["A1", "u² + v² + v = 0"], ["M1", "completes the square"], ["A1", "centre (0, −½), radius ½"]]}, {"q": "State the point on this circle that is not the image of any point on the line.", "m": 1, "ms": [["B1", "w = 0"]]}]}, {"stem": "<p>T maps z to w, where w = (z − 1)/(z + 1), z ≠ −1.</p>", "parts": [{"q": "Show that T maps the imaginary axis onto the circle |w| = 1.", "m": 2, "ms": [["M1", "|w| = |z − 1|/|z + 1|"], ["A1", "points on the imaginary axis are equidistant from 1 and −1, so |w| = 1"]]}, {"q": "Find the image of the region Re(z) &gt; 0.", "m": 2, "ms": [["B1", "these points are closer to 1 than to −1"], ["B1", "|w| &lt; 1"]]}]}, {"stem": "<p>T maps z = x + iy to w = u + iv, where w = z².</p>", "parts": [{"q": "Show that u = x² − y² and v = 2xy.", "m": 1, "ms": [["B1", "expands (x + iy)²"]]}, {"q": "Find a Cartesian equation for the image of the line x = 1.", "m": 3, "ms": [["M1", "u = 1 − y² and v = 2y"], ["M1", "eliminates y"], ["A1", "u = 1 − v²/4, a parabola"]]}]}]}}, {"id": "fp2-euclid", "module": "fp2", "title": "Euclidean algorithm, Bézout and congruences", "refs": "5.1–5.3, 5.6", "notes": ["The division algorithm reduces the greatest-common-divisor problem to smaller remainders. Back-substitution expresses the gcd as an integer combination of the original numbers: Bézout’s identity. A multiplicative inverse of a modulo n exists exactly when gcd(a,n)=1.", "A congruence ax≡b modulo n is solvable precisely when gcd(a,n) divides b. Dividing a congruence by a common factor changes the modulus, so ordinary cancellation without checking conditions can lose solutions. Give all residue classes required by the question."], "example": {"q": "Find an inverse of 7 modulo 26.", "steps": ["26=3×7+5; 7=1×5+2; 5=2×2+1.", "1=5−2(7−5)=3×5−2×7.", "1=3(26−3×7)−2×7=3×26−11×7.", "Thus 7(−11)≡1 modulo 26.", "The least non-negative inverse is 15."]}, "practice": {"q": "Solve 5x≡3 modulo 12.", "answer": null, "steps": ["The inverse of 5 is 5 because 25≡1 modulo 12.", "Multiply to get x≡15≡3 modulo 12.", "Check 5×3=15≡3.", "The solution is x≡3 (mod 12)."]}, "check": {"q": "Find gcd(26,7).", "a": 1}, "deep": {"tip": "Run Euclid’s algorithm as a column of equations, then reverse it one line at a time to write the gcd as a combination of the original numbers. A linear congruence ax ≡ b (mod n) has solutions only if gcd(a, n) divides b, and then it has exactly gcd(a, n) solutions modulo n.", "examples": [{"title": "Euclid and Bézout", "q": "Find gcd(252, 198) and integers a and b with 252a + 198b = gcd(252, 198).", "steps": ["252 = 1 × 198 + 54; 198 = 3 × 54 + 36; 54 = 1 × 36 + 18; 36 = 2 × 18.", "gcd = 18.", "18 = 54 − 36 = 54 − (198 − 3 × 54) = 4 × 54 − 198.", "= 4(252 − 198) − 198 = 4 × 252 − 5 × 198, so a = 4 and b = −5."]}, {"title": "Solving a congruence with an inverse", "q": "Solve 11x ≡ 4 (mod 17).", "steps": ["Find the inverse of 11: 11 × 14 = 154 = 9 × 17 + 1.", "So 11⁻¹ ≡ 14 (mod 17).", "x ≡ 4 × 14 = 56 ≡ 5 (mod 17).", "Check: 11 × 5 = 55 = 3 × 17 + 4."]}, {"title": "A congruence with several solutions", "q": "Solve 6x ≡ 9 (mod 15).", "steps": ["gcd(6, 15) = 3 divides 9, so there are 3 solutions modulo 15.", "Divide through by 3: 2x ≡ 3 (mod 5).", "2 × 4 = 8 ≡ 3, so x ≡ 4 (mod 5).", "x ≡ 4, 9 or 14 (mod 15)."]}], "fills": [{"q": "Euclid’s algorithm.", "lines": ["gcd(48, 18) = [[6]]"]}, {"q": "An inverse modulo 10.", "lines": ["7 × [[3]] ≡ 1 (mod 10)"]}, {"q": "A power modulo 10.", "lines": ["2¹⁰ = 1024 ≡ [[4]] (mod 10)"]}], "exam": [{"stem": "", "parts": [{"q": "Use Euclid’s algorithm to find the highest common factor of 391 and 299.", "m": 2, "ms": [["M1", "391 = 1 × 299 + 92 and 299 = 3 × 92 + 23"], ["A1", "92 = 4 × 23, so hcf = 23"]], "ans": {"a": 23.0, "tol": 0.001, "unit": ""}}, {"q": "Hence find integers a and b such that 391a + 299b = 23.", "m": 3, "ms": [["M1", "23 = 299 − 3 × 92"], ["M1", "substitutes 92 = 391 − 299"], ["A1", "a = −3, b = 4"]]}]}, {"stem": "", "parts": [{"q": "Solve the congruence 23x ≡ 5 (mod 40).", "m": 3, "ms": [["M1", "finds the inverse of 23 modulo 40 by Euclid or trial"], ["A1", "23⁻¹ ≡ 7"], ["A1", "x ≡ 35 (mod 40)"]]}]}, {"stem": "", "parts": [{"q": "Find all solutions of 8x ≡ 6 (mod 14), with 0 ≤ x &lt; 14.", "m": 3, "ms": [["M1", "gcd(8, 14) = 2 divides 6"], ["M1", "4x ≡ 3 (mod 7), so x ≡ 6 (mod 7)"], ["A1", "x = 6 and x = 13"]]}, {"q": "Explain why 8x ≡ 5 (mod 14) has no solutions.", "m": 1, "ms": [["B1", "gcd(8, 14) = 2 does not divide 5"]]}]}]}}, {"id": "fp2-count", "module": "fp2", "title": "Fermat, divisibility and combinatorial counting", "refs": "5.4–5.7", "notes": ["For prime p and a not divisible by p, Fermat’s little theorem gives a^(p−1)≡1 modulo p. Reduce the exponent only after checking that condition. Divisibility tests use place-value congruences; for 11, alternating digit sums arise from 10≡−1 modulo 11.", "Use permutations when positions or order matter and combinations when only membership matters. Complement counting is often simpler than listing overlaps; inclusion–exclusion avoids double-counting. State whether repetitions and leading zeroes are allowed before forming a product."], "example": {"q": "Find the least non-negative residue of 3²⁰ modulo 7 and count 3-person teams from 8 people.", "steps": ["3⁶≡1 modulo 7.", "20=3×6+2, so 3²⁰≡3²≡2 modulo 7.", "For a team, order does not matter.", "The count is 8C3=56, rather than 8P3=336."]}, "practice": {"q": "How many length-3 digit strings contain at least one 7, if leading zeroes and repeats are allowed?", "answer": 271, "steps": ["There are 10³=1000 total strings.", "There are 9³=729 with no 7.", "The complement count is 1000−729=271.", "This counts strings, not necessarily three-digit integers."]}, "check": {"q": "Find the least non-negative residue of 3²⁰ modulo 7.", "a": 2}, "deep": {"tip": "For powers, reduce the exponent using Fermat’s little theorem (aᵖ⁻¹ ≡ 1 mod p when p is prime and does not divide a) before calculating. For counting, decide whether order matters and whether items repeat; divide by the factorials of repeated letters, and handle restrictions by fixing the restricted positions first.", "examples": [{"title": "Fermat’s little theorem", "q": "Find the remainder when 5¹⁰⁰ is divided by 13.", "steps": ["13 is prime and does not divide 5, so 5¹² ≡ 1 (mod 13).", "100 = 8 × 12 + 4, so 5¹⁰⁰ ≡ 5⁴ (mod 13).", "5⁴ = 625 = 48 × 13 + 1.", "The remainder is 1."]}, {"title": "A divisibility test", "q": "Use the divisibility test for 11 to decide whether 7392 is divisible by 11.", "steps": ["10 ≡ −1 (mod 11), so a number is congruent to the alternating sum of its digits.", "From the units digit: 2 − 9 + 3 − 7 = −11.", "−11 ≡ 0 (mod 11), so 7392 is divisible by 11 (7392 = 11 × 672)."]}, {"title": "Arrangements with repeated letters", "q": "How many different arrangements are there of the letters of BANANA?", "steps": ["6 letters with A repeated 3 times and N repeated twice.", "6!/(3! × 2!) = 720/12.", "60 arrangements."]}], "fills": [{"q": "Fermat’s little theorem.", "lines": ["2⁶ ≡ [[1]] (mod 7)"]}, {"q": "Subsets of a 5-element set.", "lines": ["2⁵ = [[32]]"]}, {"q": "Choosing 2 from 7.", "lines": ["⁷C₂ = [[21]]"]}], "exam": [{"stem": "", "parts": [{"q": "Use Fermat’s little theorem to find the remainder when 3¹⁰² is divided by 11.", "m": 3, "ms": [["M1", "3¹⁰ ≡ 1 (mod 11)"], ["M1", "3¹⁰² = (3¹⁰)¹⁰ × 3²"], ["A1", "9"]], "ans": {"a": 9.0, "tol": 0.001, "unit": ""}}, {"q": "Prove that n⁵ − n is divisible by 5 for every integer n.", "m": 2, "ms": [["B1", "if 5 ∤ n, Fermat gives n⁴ ≡ 1, so n⁵ ≡ n"], ["B1", "if 5 | n, both terms are multiples of 5; so 5 | n⁵ − n for all n"]]}]}, {"stem": "<p>The letters of the word STATISTICS are arranged in a line.</p>", "parts": [{"q": "Find the number of different arrangements.", "m": 2, "ms": [["M1", "10!/(3! 3! 2!)"], ["A1", "50 400"]], "ans": {"a": 50400.0, "tol": 0.001, "unit": ""}}, {"q": "Find the number of arrangements that begin and end with S.", "m": 2, "ms": [["M1", "arranges the remaining 8 letters: 8!/(3! 2!)"], ["A1", "3360"]], "ans": {"a": 3360.0, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "How many four-digit numbers (1000 to 9999) have four different digits?", "m": 2, "ms": [["M1", "9 × 9 × 8 × 7"], ["A1", "4536"]], "ans": {"a": 4536.0, "tol": 0.001, "unit": ""}}, {"q": "How many of these are divisible by 5?", "m": 3, "ms": [["M1", "last digit 0: 9 × 8 × 7 = 504"], ["M1", "last digit 5: 8 × 8 × 7 = 448"], ["A1", "952"]], "ans": {"a": 952.0, "tol": 0.001, "unit": ""}}]}]}}, {"id": "fp2-recurrence", "module": "fp2", "title": "First- and second-order recurrences and induction", "refs": "6", "notes": ["A linear recurrence combines a homogeneous solution with a particular solution. A constant equilibrium solves L=aL+b for uₙ₊₁=auₙ+b when a≠1. Subtracting that equilibrium reduces the recurrence to geometric form.", "For a second-order recurrence, solve its characteristic equation and apply the two starting values. A repeated root needs a factor linear in n. Prove a proposed formula by checking the required initial cases and substituting it into the recurrence; a finite list of matching values is not a proof."], "example": {"q": "Solve uₙ₊₁=2uₙ+3 with u₀=1.", "steps": ["An equilibrium satisfies L=2L+3, giving L=−3.", "Let vₙ=uₙ+3. Then vₙ₊₁=2vₙ.", "v₀=4, so vₙ=4×2ⁿ.", "uₙ=4×2ⁿ−3."]}, "practice": {"q": "Solve uₙ₊₂=3uₙ₊₁−2uₙ with u₀=0 and u₁=1.", "answer": null, "steps": ["Characteristic roots satisfy r²−3r+2=0, so r=1,2.", "uₙ=A+B2ⁿ.", "A+B=0 and A+2B=1 give A=−1, B=1.", "uₙ=2ⁿ−1.", "Check the initial values and substitution into the recurrence."]}, "check": {"q": "If uₙ=2ⁿ−1, find u₄.", "a": 15}, "deep": {"tip": "For a homogeneous linear recurrence, solve the auxiliary equation and choose the form that matches its roots (distinct, repeated or complex). For a non-homogeneous one, add a particular solution shaped like the extra term, then use the initial terms on the complete general solution; check one term directly from the recurrence.", "examples": [{"title": "A repeated auxiliary root", "q": "Solve uₙ₊₂ = 4uₙ₊₁ − 4uₙ with u₀ = 1 and u₁ = 4.", "steps": ["Auxiliary equation m² − 4m + 4 = 0 has the repeated root 2.", "uₙ = (A + Bn)2ⁿ.", "u₀ = 1 gives A = 1; u₁ = 2(1 + B) = 4 gives B = 1.", "uₙ = (n + 1)2ⁿ; check u₂ = 16 − 4 = 12 = 3 × 4."]}, {"title": "A first-order recurrence with a linear term", "q": "Solve uₙ₊₁ = 3uₙ + 2n with u₀ = 1.", "steps": ["Complementary solution C × 3ⁿ.", "Try uₙ = an + b: a(n + 1) + b = 3an + 3b + 2n gives a = −1 and b = −½.", "uₙ = C × 3ⁿ − n − ½, and u₀ = 1 gives C = 3/2.", "uₙ = (3ⁿ⁺¹ − 2n − 1)/2; check u₁ = 3 from the recurrence."]}], "fills": [{"q": "uₙ₊₁ = 2uₙ with u₀ = 3.", "lines": ["u₄ = [[48]]"]}, {"q": "uₙ₊₂ = 5uₙ₊₁ − 6uₙ.", "lines": ["auxiliary roots [[2]] and [[3]]"]}, {"q": "Fibonacci with F₁ = F₂ = 1.", "lines": ["F₇ = [[13]]"]}], "exam": [{"stem": "<p>uₙ₊₂ = uₙ₊₁ + 6uₙ, with u₀ = 2 and u₁ = 1.</p>", "parts": [{"q": "Find uₙ in terms of n.", "m": 5, "ms": [["M1", "auxiliary equation m² − m − 6 = 0"], ["A1", "m = 3 or m = −2"], ["M1", "uₙ = A3ⁿ + B(−2)ⁿ"], ["M1", "A + B = 2 and 3A − 2B = 1"], ["A1", "uₙ = 3ⁿ + (−2)ⁿ"]]}, {"q": "Find u₅.", "m": 1, "ms": [["B1", "211"]], "ans": {"a": 211.0, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>A population is modelled by Pₙ₊₁ = 1.05Pₙ − 200, where Pₙ is the population n years after the start and P₀ = 5000.</p>", "parts": [{"q": "Find Pₙ in terms of n.", "m": 4, "ms": [["M1", "constant solution: P = 1.05P − 200 gives 4000"], ["M1", "Pₙ = 4000 + C(1.05)ⁿ"], ["A1", "C = 1000"], ["A1", "Pₙ = 4000 + 1000(1.05)ⁿ"]]}, {"q": "Find the first year in which the population exceeds 6000.", "m": 2, "ms": [["M1", "1.05ⁿ &gt; 2, so n &gt; ln 2/ln 1.05 = 14.2"], ["A1", "n = 15"]], "ans": {"a": 15.0, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>uₙ₊₁ = 2uₙ + 3ⁿ, with u₀ = 0.</p>", "parts": [{"q": "Find uₙ in terms of n.", "m": 4, "ms": [["M1", "complementary solution A2ⁿ"], ["M1", "particular solution c3ⁿ with 3c = 2c + 1"], ["A1", "c = 1"], ["A1", "uₙ = 3ⁿ − 2ⁿ"]]}, {"q": "Prove your result by induction.", "m": 3, "ms": [["B1", "u₀ = 1 − 1 = 0"], ["M1", "assumes uₖ = 3ᵏ − 2ᵏ and substitutes"], ["A1", "uₖ₊₁ = 2(3ᵏ − 2ᵏ) + 3ᵏ = 3ᵏ⁺¹ − 2ᵏ⁺¹, with a conclusion"]]}]}]}}, {"id": "fs1-discrete", "module": "fs1", "title": "Discrete distributions, expectation and variance", "refs": "1", "notes": ["A discrete probability distribution assigns non-negative probabilities summing to one. Compute E(X)=Σxp(x) and Var(X)=E(X²)−E(X)²; square the outcomes in the first term, not the probabilities. A transformation changes both the possible values and their probabilities.", "For Y=aX+b, the mean becomes aE(X)+b and the variance becomes a²Var(X). Adding a constant shifts every outcome without changing the spread. Independence is not needed for this single-variable transformation, but matters when combining different variables."], "example": {"q": "X takes 0,1,2 with probabilities 1/4,1/2,1/4. Find its mean and variance.", "steps": ["E(X)=0+1/2+2/4=1.", "E(X²)=0+1/2+4/4=3/2.", "Var(X)=3/2−1²=1/2.", "For Y=3X−2, E(Y)=1 and Var(Y)=9/2."]}, "practice": {"q": "X takes 1,2,3 with probabilities 1/2,1/3,1/6. Find E(X) and Var(X).", "answer": null, "steps": ["The probabilities sum to 1.", "E(X)=1/2+2/3+3/6=5/3.", "E(X²)=1/2+4/3+9/6=10/3.", "Var(X)=10/3−25/9=5/9."]}, "check": {"q": "A variable takes 0,1,2 with probabilities 1/4,1/2,1/4. Find its mean.", "a": 1}, "deep": {"tip": "Use ΣP(X = x) = 1 first to find any unknown probability. Work out E(X) and E(X²) in a table, then Var(X) = E(X²) − [E(X)]². For a linear function, the constant shifts the mean only and the multiplier is squared in the variance.", "examples": [{"title": "An unknown constant", "q": "P(X = x) = kx for x = 1, 2, 3, 4. Find k, E(X) and Var(X).", "steps": ["k(1 + 2 + 3 + 4) = 1, so k = 1/10.", "E(X) = Σx × kx = k(1 + 4 + 9 + 16) = 3.", "E(X²) = Σx² × kx = k(1 + 8 + 27 + 64) = 10.", "Var(X) = 10 − 3² = 1."]}, {"title": "Expectation of a function", "q": "For the distribution in the previous example, find E(1/X) and Var(2X + 5).", "steps": ["E(1/X) = Σ(1/x) × kx = 4k.", "E(1/X) = 0.4; note that this is not 1/E(X).", "Var(2X + 5) = 2² Var(X).", "= 4."]}], "fills": [{"q": "E(X) = 4.", "lines": ["E(3X + 2) = [[14]]"]}, {"q": "Var(X) = 2.", "lines": ["Var(3X + 2) = [[18]]"]}, {"q": "Probabilities 0.2, 0.5 and p.", "lines": ["p = [[0.3]]"]}], "exam": [{"stem": "<p>X takes the values −1, 0, 1, 2 with probabilities 0.1, a, 0.3, b respectively, and E(X) = 0.8.</p>", "parts": [{"q": "Find the values of a and b.", "m": 3, "ms": [["M1", "a + b = 0.6"], ["M1", "−0.1 + 0.3 + 2b = 0.8"], ["A1", "a = 0.3 and b = 0.3"]]}, {"q": "Find Var(X).", "m": 3, "ms": [["M1", "E(X²) = 0.1 + 0.3 + 1.2 = 1.6"], ["M1", "1.6 − 0.8²"], ["A1", "0.96"]], "ans": {"a": 0.96, "tol": 0.001, "unit": ""}}, {"q": "Find Var(5 − 2X).", "m": 1, "ms": [["B1", "4 × 0.96 = 3.84"]], "ans": {"a": 3.84, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>In a game a fair six-sided die is rolled. If the score is even the player wins that number of pounds; if it is odd the player loses £3.</p>", "parts": [{"q": "Find the expected profit for one game.", "m": 3, "ms": [["M1", "profit −3 with probability ½ and 2, 4, 6 each with probability ⅙"], ["M1", "−1.5 + 12/6"], ["A1", "£0.50"]], "ans": {"a": 0.5, "tol": 0.001, "unit": "£"}}, {"q": "Find the variance of the profit.", "m": 3, "ms": [["M1", "E(X²) = 4.5 + 56/6"], ["A1", "13.83…"], ["A1", "163/12 ≈ 13.58"]], "ans": {"a": 13.5833333333, "tol": 0.002, "unit": ""}}]}, {"stem": "<p>E(X) = 10 and Var(X) = 4. The variable Y = aX + b, where a &gt; 0, has mean 0 and variance 1.</p>", "parts": [{"q": "Find the values of a and b.", "m": 3, "ms": [["M1", "4a² = 1"], ["M1", "10a + b = 0"], ["A1", "a = ½ and b = −5"]]}]}]}}, {"id": "fs1-poisson", "module": "fs1", "title": "Poisson models and binomial approximation", "refs": "2", "notes": ["A Poisson model counts events in a specified interval with constant average rate and independent occurrences. Its mean and variance are both λ, and P(X=k)=e⁻λ λᵏ/k!. Scale λ when changing the interval before evaluating a probability.", "A Poisson approximation to Bin(n,p) uses λ=np when n is large and p is small. Check the context and approximation quality rather than treating a rule of thumb as a theorem. Independent Poisson counts add their rates; a difference of counts is not generally Poisson."], "example": {"q": "Calls arrive at a mean rate of 2 per hour. Under a Poisson model, find P(no calls in 30 minutes).", "steps": ["The half-hour rate is λ=1.", "P(X=0)=e⁻¹×1⁰/0!=e⁻¹.", "The probability is approximately 0.3679.", "The model assumes the rate is stable and occurrences are independent."]}, "practice": {"q": "If X~Poisson(3), find P(X≤1).", "answer": null, "steps": ["P(X≤1)=P(0)+P(1).", "The sum is e⁻³+3e⁻³=4e⁻³.", "This is approximately 0.1991.", "Both values 0 and 1 are included."]}, "check": {"q": "A Poisson rate is 6 per hour. What is λ for 20 minutes?", "a": 2}, "deep": {"tip": "Scale the mean to the interval in the question before calculating anything, and write the event as an inequality so the cumulative probability you need is clear. Poisson modelling needs events that occur singly, independently and at a constant average rate; the approximation to a binomial needs n large and p small.", "examples": [{"title": "An upper tail", "q": "X ~ Po(4.5). Find P(X ≥ 3).", "steps": ["P(X ≥ 3) = 1 − P(X ≤ 2).", "P(X ≤ 2) = e^(−4.5)(1 + 4.5 + 4.5²/2) = e^(−4.5) × 15.625.", "= 0.1736.", "P(X ≥ 3) = 0.8264."]}, {"title": "Adding independent Poisson variables", "q": "Flaws of type A occur at a rate of 1.2 per metre and flaws of type B at 0.8 per metre, independently. Find the probability of exactly 2 flaws in a metre.", "steps": ["The total number of flaws is Po(1.2 + 0.8) = Po(2).", "P(T = 2) = e^(−2) × 2²/2!.", "= 2e^(−2) = 0.2707."]}, {"title": "Approximating a binomial", "q": "X ~ B(200, 0.015). Use a Poisson approximation to find P(X ≤ 2).", "steps": ["n is large and p is small, so X ≈ Po(np) = Po(3).", "P(X ≤ 2) = e^(−3)(1 + 3 + 4.5).", "= 0.4232."]}], "fills": [{"q": "X ~ Po(6).", "lines": ["Var(X) = [[6]]"]}, {"q": "A rate of 3 per hour.", "lines": ["mean number in 20 minutes = [[1]]"]}, {"q": "B(500, 0.004) is approximated by", "lines": ["Po([[2]])"]}], "exam": [{"stem": "<p>Emails arrive at an average rate of 2.4 per 10 minutes and are modelled by a Poisson distribution.</p>", "parts": [{"q": "Find the probability of exactly 3 emails in a 10-minute period.", "m": 2, "ms": [["M1", "e^(−2.4) × 2.4³/3!"], ["A1", "0.2090"]], "ans": {"a": 0.209, "tol": 0.0005, "unit": ""}}, {"q": "Find the probability of at least 2 emails in a 5-minute period.", "m": 3, "ms": [["B1", "mean 1.2"], ["M1", "1 − e^(−1.2)(1 + 1.2)"], ["A1", "0.3374"]], "ans": {"a": 0.3374, "tol": 0.0005, "unit": ""}}, {"q": "State two assumptions needed for the Poisson model.", "m": 2, "ms": [["B1", "emails arrive independently of one another"], ["B1", "emails arrive singly and at a constant average rate"]]}]}, {"stem": "<p>A machine makes components, each defective with probability 0.01 independently. X is the number of defective components in a batch of 400.</p>", "parts": [{"q": "Explain why a Poisson approximation is suitable.", "m": 1, "ms": [["B1", "n = 400 is large and p = 0.01 is small"]]}, {"q": "Use the approximation to find P(X &gt; 5).", "m": 3, "ms": [["B1", "Po(4)"], ["M1", "1 − P(X ≤ 5)"], ["A1", "0.2149"]], "ans": {"a": 0.2149, "tol": 0.0005, "unit": ""}}]}, {"stem": "<p>X ~ Po(λ) and P(X = 2) = 3P(X = 0).</p>", "parts": [{"q": "Find the exact value of λ.", "m": 3, "ms": [["M1", "e^(−λ)λ²/2 = 3e^(−λ)"], ["A1", "λ² = 6"], ["A1", "λ = √6"]], "ans": {"a": 2.4494897428, "tol": 0.001, "unit": ""}}, {"q": "Find P(X = 1), to 4 decimal places.", "m": 2, "ms": [["M1", "√6 e^(−√6)"], ["A1", "0.2115"]], "ans": {"a": 0.2115, "tol": 0.0005, "unit": ""}}]}]}}, {"id": "fs1-geometric", "module": "fs1", "title": "Geometric and negative binomial waiting times", "refs": "3", "notes": ["With independent trials and success probability p, the geometric variable counting trials to the first success has support 1,2,… and P(X=k)=(1−p)^(k−1)p. Its mean is 1/p and variance (1−p)/p². State the counting convention before applying a formula.", "For the trial number X of the rth success, P(X=k)=C(k−1,r−1)pʳ(1−p)^(k−r), k≥r. The final trial must be a success; the preceding k−1 trials contain r−1 successes. The mean and variance are r/p and r(1−p)/p²."], "example": {"q": "Success probability is 1/4. Find the probability that the first success is on trial 3 and the mean waiting time.", "steps": ["P(X=3)=(3/4)²(1/4)=9/64.", "E(X)=1/p=4.", "The variance is (3/4)/(1/4)²=12.", "These counts include the successful trial."]}, "practice": {"q": "For independent fair trials with success probability 1/2, find the probability that the third success occurs on trial 5.", "answer": 0.1875, "steps": ["Trial 5 is a success.", "Choose 2 successes among the first 4 trials: C(4,2)=6.", "Probability=6(1/2)³(1/2)²=6/32=3/16."]}, "check": {"q": "For a geometric waiting time counting the successful trial, p=0.2. Find E(X).", "a": 5}, "deep": {"tip": "Decide what is being counted: the number of trials up to and including the first success is geometric, and up to and including the rth success is negative binomial. For the negative binomial the final trial must be a success, so the binomial coefficient counts arrangements of the earlier r − 1 successes only.", "examples": [{"title": "Geometric probabilities", "q": "X ~ Geo(0.2). Find P(X ≤ 4), P(X > 6) and Var(X).", "steps": ["P(X > n) = (1 − p)ⁿ, since the first n trials all fail.", "P(X ≤ 4) = 1 − 0.8⁴ = 0.5904.", "P(X > 6) = 0.8⁶ = 0.2621.", "Var(X) = (1 − p)/p² = 0.8/0.04 = 20."]}, {"title": "A negative binomial probability", "q": "Each trial succeeds with probability 0.3. Find the probability that the third success occurs on the eighth trial, and the mean and variance of the number of trials needed.", "steps": ["Two successes in the first 7 trials, then a success on trial 8.", "⁷C₂ × 0.3² × 0.7⁵ × 0.3 = 21 × 0.3³ × 0.7⁵.", "= 0.0953.", "Mean = r/p = 10; variance = r(1 − p)/p² = 2.1/0.09 = 23.3."]}], "fills": [{"q": "X ~ Geo(0.25).", "lines": ["E(X) = [[4]]"]}, {"q": "X ~ Geo(0.5).", "lines": ["P(X = 3) = [[0.125]]"]}, {"q": "Number of trials to the 4th success with p = 0.5.", "lines": ["mean = [[8]]"]}], "exam": [{"stem": "<p>A fair six-sided die is thrown repeatedly until a six is obtained.</p>", "parts": [{"q": "Find the probability that the first six occurs on the fourth throw.", "m": 2, "ms": [["M1", "(5/6)³ × (1/6)"], ["A1", "0.0965"]], "ans": {"a": 0.0965, "tol": 0.001, "unit": ""}}, {"q": "Find the probability that more than five throws are needed.", "m": 2, "ms": [["M1", "(5/6)⁵"], ["A1", "0.4019"]], "ans": {"a": 0.4019, "tol": 0.0005, "unit": ""}}, {"q": "Write down the mean and the variance of the number of throws.", "m": 2, "ms": [["B1", "mean 6"], ["B1", "variance 30"]]}]}, {"stem": "<p>An archer hits the target with probability 0.4 on each shot, independently.</p>", "parts": [{"q": "Find the probability that her second hit is on her fifth shot.", "m": 3, "ms": [["M1", "one hit in the first four shots, then a hit"], ["M1", "⁴C₁ × 0.4 × 0.6³ × 0.4"], ["A1", "0.1382"]], "ans": {"a": 0.13824, "tol": 0.001, "unit": ""}}, {"q": "Find the expected number of shots needed to obtain three hits.", "m": 1, "ms": [["B1", "3/0.4 = 7.5"]], "ans": {"a": 7.5, "tol": 0.001, "unit": ""}}, {"q": "Find the variance of the number of shots needed to obtain three hits.", "m": 1, "ms": [["B1", "3 × 0.6/0.4² = 11.25"]], "ans": {"a": 11.25, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>X ~ Geo(p), where p &lt; 0.5, and P(X = 2) = 0.21.</p>", "parts": [{"q": "Find the value of p.", "m": 3, "ms": [["M1", "p(1 − p) = 0.21"], ["A1", "p = 0.3 or p = 0.7"], ["A1", "p = 0.3"]], "ans": {"a": 0.3, "tol": 0.001, "unit": ""}}, {"q": "Find P(X ≥ 3).", "m": 2, "ms": [["M1", "(1 − p)²"], ["A1", "0.49"]], "ans": {"a": 0.49, "tol": 0.001, "unit": ""}}]}]}}, {"id": "fs1-tests", "module": "fs1", "title": "Hypothesis tests for discrete distributions", "refs": "4", "notes": ["State a null model and an alternative before calculating a tail probability. A one-sided alternative chooses one tail; a two-sided alternative requires both directions to be handled using the specified testing convention. A p-value is calculated assuming the null hypothesis, not the probability that the null is true.", "A critical region contains outcomes causing rejection, and its actual probability under the null is the test’s size. A discrete model may not permit an exact nominal size. Report the decision in context and distinguish insufficient evidence from proof of the null."], "example": {"q": "Under H₀, X~Poisson(1). For H₁: λ>1, assess an observed count of 4 at the 5% level.", "steps": ["The relevant tail is P(X≥4).", "P(X≥4)=1−e⁻¹(1+1+1/2+1/6).", "This is approximately 0.01899.", "It is below 0.05, so reject H₀.", "There is evidence of an increased mean count under the model assumptions."]}, "practice": {"q": "Under H₀, X~Bin(4,1/2). For H₁:p>1/2, assess X=4 at the 5% level.", "answer": null, "steps": ["The upper tail is P(X≥4)=1/16=0.0625.", "0.0625 exceeds 0.05.", "Do not reject H₀ at 5%.", "The maximum observed count does not automatically imply a significant result."]}, "check": {"q": "Under Bin(4,1/2), find P(X=4).", "a": 0.0625}, "deep": {"tip": "State the hypotheses in terms of the parameter, and give the distribution of the test statistic under H₀ with the mean scaled to the period observed. Compare a tail probability (the observed value or more extreme) with the significance level, never a single-value probability, and word the conclusion in context without claiming proof.", "examples": [{"title": "A one-tailed Poisson test", "q": "Faults occur at a rate of 5 per week. After maintenance there is 1 fault in a week. Test at the 5% level whether the rate has decreased.", "steps": ["H₀: λ = 5, H₁: λ < 5, with X ~ Po(5) under H₀.", "P(X ≤ 1) = e^(−5)(1 + 5) = 0.0404.", "0.0404 < 0.05, so reject H₀.", "There is evidence at the 5% level that the rate of faults has decreased."]}, {"title": "A two-tailed critical region", "q": "X ~ Po(λ). Find the critical region for testing H₀: λ = 8 against H₁: λ ≠ 8 at the 5% level, with at most 2.5% in each tail, and state the actual significance level.", "steps": ["Lower tail: P(X ≤ 2) = 0.0138 and P(X ≤ 3) = 0.0424, so the region is X ≤ 2.", "Upper tail: P(X ≥ 14) = 0.0342 and P(X ≥ 15) = 0.0173, so the region is X ≥ 15.", "Critical region: X ≤ 2 or X ≥ 15.", "Actual significance level = 0.01375 + 0.01726 = 0.0310."]}], "fills": [{"q": "A one-tailed test at the 5% level.", "lines": ["reject H₀ when the tail probability is less than [[0.05]]"]}, {"q": "X ~ Po(2).", "lines": ["P(X = 0) = e^(−2) = [[0.1353]]"]}, {"q": "A two-tailed test at the 10% level.", "lines": ["each tail has at most [[5]]%"]}], "exam": [{"stem": "<p>Accidents at a junction occurred at a mean rate of 3 per month. After new signs are installed there are 9 accidents in 6 months.</p>", "parts": [{"q": "Test, at the 5% level of significance, whether the mean rate of accidents has decreased. State your hypotheses clearly.", "m": 5, "ms": [["B1", "H₀: λ = 3, H₁: λ < 3 (per month)"], ["B1", "under H₀ the 6-month count is Po(18)"], ["M1", "P(X ≤ 9)"], ["A1", "0.0154"], ["A1", "0.0154 < 0.05: reject H₀; evidence that the rate has decreased"]]}]}, {"stem": "<p>X is the number of attempts needed to obtain a first success, so X ~ Geo(p). A test of H₀: p = 0.2 against H₁: p &lt; 0.2 is carried out at the 5% level.</p>", "parts": [{"q": "Find the critical region.", "m": 3, "ms": [["M1", "P(X ≥ c) = 0.8^(c − 1)"], ["M1", "0.8¹³ = 0.0550 and 0.8¹⁴ = 0.0440"], ["A1", "X ≥ 15"]]}, {"q": "The first success occurs on the 12th attempt. State the conclusion of the test.", "m": 1, "ms": [["B1", "12 is not in the critical region: insufficient evidence that p is less than 0.2"]]}]}, {"stem": "<p>X ~ Po(λ). A test of H₀: λ = 4 against H₁: λ &gt; 4 is carried out at the 1% level.</p>", "parts": [{"q": "Find the critical region.", "m": 3, "ms": [["M1", "P(X ≥ 9) = 0.0214"], ["M1", "P(X ≥ 10) = 0.0081"], ["A1", "X ≥ 10"]]}, {"q": "State the actual significance level of the test.", "m": 1, "ms": [["B1", "0.0081"]], "ans": {"a": 0.0081, "tol": 0.02, "unit": ""}}]}]}}, {"id": "fs1-clt", "module": "fs1", "title": "The central limit theorem and sample means", "refs": "5", "notes": ["For independent identically distributed observations with finite mean μ and variance σ², the sample mean has mean μ and variance σ²/n. The central limit theorem gives an approximate normal distribution for a sufficiently large sample, with the adequacy depending on the population’s shape.", "The standard deviation of a sample mean is σ/√n, not σ/n. For a sum, multiply the mean by n and the variance by n. Check independence and whether a few extreme observations undermine a small-sample approximation. The theorem concerns the sampling distribution, not the shape of the original data."], "example": {"q": "A population has mean 50 and standard deviation 12. Approximate P(sample mean >54) for n=36 independent observations.", "steps": ["The sample mean is approximately N(50,4).", "Its standard deviation is 12/6=2.", "Standardise: z=(54−50)/2=2.", "The upper-tail probability is approximately 0.0228."]}, "practice": {"q": "A population has variance 81. Find the standard deviation of the mean of 25 independent observations.", "answer": 1.8, "steps": ["The sampling variance is 81/25.", "The sampling standard deviation is 9/5=1.8.", "The normal approximation, if used, needs an additional adequacy check."]}, "check": {"q": "If σ=12 and n=36, find the standard deviation of the sample mean.", "a": 2}, "deep": {"tip": "Write down the mean and variance of the population first, then the distribution of the sample mean: mean μ and variance σ²/n. The central limit theorem is what allows a normal model when the population is not normal, and it needs a large sample; say so when you use it.", "examples": [{"title": "Sample mean of Poisson data", "q": "X ~ Po(2.5). A random sample of 40 observations is taken. Estimate the probability that the sample mean exceeds 2.9.", "steps": ["The population has mean 2.5 and variance 2.5.", "By the central limit theorem the sample mean is approximately N(2.5, 2.5/40) = N(2.5, 0.0625).", "z = (2.9 − 2.5)/0.25 = 1.6.", "P(Z > 1.6) = 0.0548."]}, {"title": "Scores on a die", "q": "A fair die is rolled 50 times. Estimate the probability that the mean score is at least 3.8.", "steps": ["One roll has mean 3.5 and variance 35/12.", "The sample mean is approximately N(3.5, 35/600), with standard error 0.2415.", "z = (3.8 − 3.5)/0.2415 = 1.24.", "P(Z ≥ 1.24) ≈ 0.107."]}], "fills": [{"q": "σ = 10 and n = 25.", "lines": ["standard error of the mean = [[2]]"]}, {"q": "σ² = 36 and n = 9.", "lines": ["variance of the sample mean = [[4]]"]}, {"q": "X ~ Po(4) and n = 100.", "lines": ["variance of the sample mean = [[0.04]]"]}], "exam": [{"stem": "<p>X ~ Geo(0.25), so that E(X) = 4 and Var(X) = 12. A random sample of 48 observations of X is taken.</p>", "parts": [{"q": "State the approximate distribution of the sample mean.", "m": 2, "ms": [["B1", "normal with mean 4"], ["B1", "variance 12/48 = 0.25"]]}, {"q": "Estimate the probability that the sample mean is less than 3.5.", "m": 2, "ms": [["M1", "z = (3.5 − 4)/0.5 = −1"], ["A1", "0.1587"]], "ans": {"a": 0.1587, "tol": 0.001, "unit": ""}}, {"q": "Explain why the normal approximation is appropriate.", "m": 1, "ms": [["B1", "the sample is large, so the central limit theorem applies"]]}]}, {"stem": "", "parts": [{"q": "The masses of loaves have mean 250 g and standard deviation 8 g. Estimate the probability that the mean mass of a random sample of 64 loaves lies between 248 g and 251 g.", "m": 4, "ms": [["M1", "standard error 8/√64 = 1"], ["M1", "standardises both values: z = −2 and z = 1"], ["A1", "Φ(1) − Φ(−2)"], ["A1", "0.8186"]], "ans": {"a": 0.8186, "tol": 0.001, "unit": ""}}]}, {"stem": "", "parts": [{"q": "A population has standard deviation 6. Find the smallest sample size for which the probability that the sample mean lies within 1 of the population mean is at least 0.95.", "m": 3, "ms": [["M1", "uses z = 1.96"], ["M1", "1.96 × 6/√n ≤ 1"], ["A1", "n = 139"]], "ans": {"a": 139.0, "tol": 0.001, "unit": ""}}]}]}}, {"id": "fs1-chi", "module": "fs1", "title": "Chi-squared goodness-of-fit and independence", "refs": "6", "notes": ["The chi-squared statistic is Σ(O−E)²/E. Expected counts come from the null model, not from rounding observed proportions to convenient values. For independence in a contingency table, E=(row total×column total)/grand total.", "Use suitable expected frequencies, combining categories where justified before testing. Degrees of freedom for a goodness-of-fit test are categories−1−parameters estimated from the data; for an r×c independence table they are (r−1)(c−1). Reject for sufficiently large values of the statistic and state the evidence in context."], "example": {"q": "Four equally likely categories have observed counts 18,22,16,24. Calculate the chi-squared statistic.", "steps": ["Total=80, so every expected count is 20.", "Contributions are 4/20,4/20,16/20,16/20.", "The statistic is 2.", "There are 4−1=3 degrees of freedom if no parameters were estimated.", "A test decision requires the chosen significance level and its critical value."]}, "practice": {"q": "A 2×3 contingency table has suitable expected counts. State its degrees of freedom and explain how each expected count is found.", "answer": null, "steps": ["Degrees of freedom=(2−1)(3−1)=2.", "Each expected count is row total times column total divided by grand total.", "Use observed counts only in the numerator of each (O−E)²/E contribution.", "The null hypothesis is independence of the two categorical variables."]}, "check": {"q": "A goodness-of-fit test has 5 categories and estimates no parameters. Find its degrees of freedom.", "a": 4}, "deep": {"tip": "Expected frequencies come from the null hypothesis and must add up to the observed total; combine classes until each expected frequency is at least 5. Degrees of freedom are the number of classes after combining, minus 1, minus one more for each parameter estimated from the data; for a contingency table use (rows − 1)(columns − 1).", "examples": [{"title": "Goodness of fit for a die", "q": "A die is rolled 60 times, giving frequencies 8, 12, 9, 11, 6, 14 for the scores 1 to 6. Test at the 5% level whether the die is fair.", "steps": ["H₀: each score has probability ⅙. Each expected frequency is 10.", "Σ(O − E)²/E = (4 + 4 + 1 + 1 + 16 + 16)/10 = 4.2.", "Degrees of freedom = 6 − 1 = 5; the 5% critical value is 11.070.", "4.2 < 11.070: do not reject H₀; the data are consistent with a fair die."]}, {"title": "A 2 × 2 contingency table", "q": "Of 50 people given treatment A, 30 improved; of 50 given treatment B, 10 improved. Test at the 5% level whether improvement is independent of treatment.", "steps": ["H₀: improvement is independent of treatment. Column totals are 40 improved and 60 not.", "Expected: 50 × 40/100 = 20 improved and 30 not improved in each row.", "Σ(O − E)²/E = 100/20 + 100/30 + 100/20 + 100/30 = 16.67.", "Degrees of freedom = 1; critical value 3.841.", "16.67 > 3.841: reject H₀; improvement is associated with treatment."]}], "fills": [{"q": "A 3 × 4 contingency table.", "lines": ["degrees of freedom = [[6]]"]}, {"q": "Row total 40, column total 30, grand total 120.", "lines": ["expected frequency = [[10]]"]}, {"q": "Five classes with one parameter estimated from the data.", "lines": ["degrees of freedom = [[3]]"]}], "exam": [{"stem": "<p>The number of goals scored in each of 100 matches was recorded: 0 goals in 22 matches, 1 in 34, 2 in 26, 3 in 12, and 4 or more in 6. The mean of the data is 1.5. A Poisson model is to be tested.</p>", "parts": [{"q": "Show that the expected frequency for 2 goals is 25.10.", "m": 2, "ms": [["M1", "100 × e^(−1.5) × 1.5²/2"], ["A1", "25.10"]]}, {"q": "Explain why there are 3 degrees of freedom.", "m": 2, "ms": [["B1", "5 classes, each with expected frequency at least 5"], ["B1", "5 − 1 − 1, because the totals agree and the mean was estimated"]]}, {"q": "The other expected frequencies are 22.31, 33.47, 12.55 and 6.56. Calculate the test statistic.", "m": 3, "ms": [["M1", "Σ(O − E)²/E"], ["A1", "at least three correct contributions"], ["A1", "0.118"]], "ans": {"a": 0.1176101776, "tol": 0.02, "unit": ""}}, {"q": "Complete the test at the 5% level.", "m": 1, "ms": [["B1", "0.118 < 7.815: do not reject H₀; a Poisson model is consistent with the data"]]}]}, {"stem": "<p>120 students were classified by year group and by the lunch option they chose. Year 12: 20 hot, 30 cold, 10 none. Year 13: 10 hot, 20 cold, 30 none.</p>", "parts": [{"q": "Test, at the 5% level of significance, whether choice of lunch is independent of year group.", "m": 6, "ms": [["B1", "H₀: lunch choice is independent of year group"], ["M1", "expected = row total × column total ÷ 120"], ["A1", "15, 25 and 20 in each row"], ["M1", "Σ(O − E)²/E"], ["A1", "15.33"], ["A1", "2 degrees of freedom, 15.33 > 5.991: reject H₀; choice depends on year group"]], "ans": {"a": 15.3333333333, "tol": 0.002, "unit": ""}}]}, {"stem": "", "parts": [{"q": "In a goodness-of-fit test the last class has expected frequency 3.2. State what should be done and the effect on the number of degrees of freedom.", "m": 2, "ms": [["B1", "combine it with the adjacent class so that the expected frequency is at least 5"], ["B1", "the number of degrees of freedom is reduced by 1"]]}]}]}}, {"id": "fs1-pgf", "module": "fs1", "title": "Probability generating functions and sums", "refs": "7", "notes": ["For a non-negative integer-valued variable, G(t)=E(tˣ)=Σpₖtᵏ. The coefficient of tᵏ is P(X=k), so the powers encode outcomes and the coefficients encode their probabilities. G(1)=1, G′(1)=E(X), and G″(1)=E[X(X−1)]. Therefore Var(X)=G″(1)+G′(1)−[G′(1)]².", "Independent sums have a generating function equal to the product of the individual generating functions. This product rule depends on independence. Obtain probabilities from coefficients or derivatives at zero, not from substituting the outcome into G."], "example": {"q": "For G(t)=(1+2t+t²)/4, find the mean and variance.", "steps": ["G′(t)=(2+2t)/4, so G′(1)=1.", "G″(t)=1/2, so G″(1)=1/2.", "Variance=1/2+1−1²=1/2.", "The coefficients are valid probabilities and G(1)=1."]}, "practice": {"q": "Independent X and Y have PGFs (1+t)/2 and (1+t²)/2. Find the distribution of X+Y.", "answer": null, "steps": ["Multiply the PGFs: (1+t+t²+t³)/4.", "The possible values are 0,1,2,3.", "Each has probability 1/4.", "Check that the probabilities sum to one."]}, "check": {"q": "What must a valid probability generating function equal at t=1?", "a": 1}, "deep": {"tip": "The coefficient of tˣ in G(t) is P(X = x), so G(1) = 1 always. Use E(X) = G′(1) and Var(X) = G″(1) + G′(1) − [G′(1)]². For a sum of independent variables multiply the generating functions; multiplying is only valid when the variables are independent.", "examples": [{"title": "Mean and variance from a PGF", "q": "X has probability generating function G(t) = (0.4 + 0.6t)³. Find P(X = 2), E(X) and Var(X).", "steps": ["The t² coefficient is 3 × 0.4 × 0.6² = 0.432, so P(X = 2) = 0.432.", "G′(t) = 1.8(0.4 + 0.6t)², so E(X) = G′(1) = 1.8.", "G″(t) = 2.16(0.4 + 0.6t), so G″(1) = 2.16.", "Var(X) = 2.16 + 1.8 − 1.8² = 0.72, as expected for B(3, 0.6)."]}, {"title": "Sum of independent Poisson variables", "q": "X ~ Po(2) and Y ~ Po(3) are independent. Use generating functions to find the distribution of X + Y.", "steps": ["G_X(t) = e^(2(t − 1)) and G_Y(t) = e^(3(t − 1)).", "For independent variables, G_(X+Y)(t) = G_X(t) G_Y(t).", "= e^(5(t − 1)).", "This is the generating function of Po(5), so X + Y ~ Po(5)."]}, {"title": "A linear function", "q": "X has generating function G_X(t). Find the generating function of Y = 3X + 2.", "steps": ["G_Y(t) = E(t^Y) = E(t^(3X + 2)).", "= t² E((t³)^X).", "G_Y(t) = t² G_X(t³)."]}], "fills": [{"q": "Every probability generating function.", "lines": ["G(1) = [[1]]"]}, {"q": "G(t) = (1 + t)²/4.", "lines": ["G′(1) = [[1]]"]}, {"q": "G(t) = 0.2 + 0.5t + 0.3t².", "lines": ["P(X = 1) = [[0.5]]"]}], "exam": [{"stem": "<p>X has probability generating function G(t) = k(2 + t)³.</p>", "parts": [{"q": "Find the value of k.", "m": 1, "ms": [["B1", "G(1) = 27k = 1, so k = 1/27"]]}, {"q": "Find P(X = 1).", "m": 2, "ms": [["M1", "coefficient of t: 3 × 2² × k"], ["A1", "4/9"]], "ans": {"a": 0.4444444444, "tol": 0.001, "unit": ""}}, {"q": "Find E(X).", "m": 2, "ms": [["M1", "G′(t) = 3k(2 + t)²"], ["A1", "G′(1) = 1"]], "ans": {"a": 1.0, "tol": 0.001, "unit": ""}}, {"q": "Find Var(X).", "m": 3, "ms": [["M1", "G″(1) = 6k × 3 = ⅔"], ["M1", "G″(1) + G′(1) − [G′(1)]²"], ["A1", "⅔"]], "ans": {"a": 0.6666666667, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>X ~ Geo(p) has probability generating function G(t) = pt/(1 − qt), where q = 1 − p.</p>", "parts": [{"q": "Use G(t) to show that E(X) = 1/p.", "m": 3, "ms": [["M1", "differentiates with the quotient rule"], ["A1", "G′(t) = p/(1 − qt)²"], ["A1", "G′(1) = p/p² = 1/p"]]}, {"q": "Given p = 0.25, use the expansion of G(t) to find P(X = 3).", "m": 2, "ms": [["M1", "pt(1 + qt + q²t² + …): coefficient of t³ is pq²"], ["A1", "0.1406"]], "ans": {"a": 0.140625, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>X and Y are independent with G_X(t) = e^(2(t − 1)) and G_Y(t) = (0.5 + 0.5t)².</p>", "parts": [{"q": "Find E(X + Y).", "m": 3, "ms": [["M1", "G(t) = G_X(t)G_Y(t), or adds the two means"], ["M1", "G′(1) = 2 + 1"], ["A1", "3"]], "ans": {"a": 3.0, "tol": 0.001, "unit": ""}}, {"q": "Find P(X + Y = 0).", "m": 2, "ms": [["M1", "G(0) = e^(−2) × 0.25"], ["A1", "0.0338"]], "ans": {"a": 0.0338, "tol": 0.003, "unit": ""}}]}]}}, {"id": "fs1-power", "module": "fs1", "title": "Size, Type I and Type II errors, and power", "refs": "8", "notes": ["A Type I error rejects a true null hypothesis; its probability is the size of the test. A Type II error fails to reject a false null, and its probability depends on a specified alternative parameter value. Power at that alternative is one minus the Type II error probability.", "Use the same fixed critical region when calculating size and power, but change the probability model to the null or specified alternative as appropriate. Increasing the sample size can improve power without increasing the nominal size. A high p-value is not evidence that the Type II error probability is small."], "example": {"q": "A test observes X~Bin(4,p) and rejects H₀:p=1/2 only if X=4. Find its size and power at p=0.8.", "steps": ["Size=P(X=4|p=1/2)=(1/2)⁴=0.0625.", "Power at p=0.8 is P(X=4|p=0.8)=0.8⁴=0.4096.", "The Type II error probability there is 1−0.4096=0.5904.", "This is a 6.25% size test, not a 5% test."]}, "practice": {"q": "For the same rejection rule, find the power at p=0.9.", "answer": 0.6561, "steps": ["Reject only at X=4.", "Use the alternative probability p=0.9.", "Power=0.9⁴=0.6561."]}, "check": {"q": "If a test has Type II error probability 0.3 at an alternative, what is its power there?", "a": 0.7}, "deep": {"tip": "Fix the critical region first: size and power are both probabilities of landing in that region, calculated under different parameter values. Size uses the value in H₀; power uses a particular value from H₁; and P(Type II error) = 1 − power. A power function is the same calculation left in terms of the parameter.", "examples": [{"title": "Size and power of a Poisson test", "q": "X ~ Po(λ). H₀: λ = 3 is tested against H₁: λ > 3 and H₀ is rejected when X ≥ 7. Find the size of the test and its power when λ = 6.", "steps": ["Size = P(X ≥ 7 | λ = 3) = 1 − P(X ≤ 6) = 1 − 0.9665.", "Size = 0.0335.", "Power = P(X ≥ 7 | λ = 6) = 1 − 0.6063.", "Power = 0.3937, so P(Type II error) = 0.6063."]}, {"title": "A power function", "q": "X ~ B(10, p). H₀: p = 0.5 is tested against H₁: p < 0.5 and H₀ is rejected when X ≤ 1. Find the size, the power function, and the power when p = 0.2.", "steps": ["Size = P(X ≤ 1 | p = 0.5) = 11/1024 = 0.0107.", "Power function = P(X ≤ 1 | p) = (1 − p)¹⁰ + 10p(1 − p)⁹.", "At p = 0.2: 0.8¹⁰ + 2 × 0.8⁹ = 0.1074 + 0.2684.", "Power = 0.3758."]}], "fills": [{"q": "P(Type II error) = 0.35.", "lines": ["power = [[0.65]]"]}, {"q": "X ~ B(5, 0.5) and H₀ is rejected only when X = 5.", "lines": ["size = [[0.03125]]"]}, {"q": "X ~ Po(3) and H₀ is rejected only when X = 0.", "lines": ["size = e^(−3) = [[0.0498]]"]}], "exam": [{"stem": "<p>X ~ B(12, p). H₀: p = 0.4 is tested against H₁: p &gt; 0.4, and H₀ is rejected when X ≥ 9.</p>", "parts": [{"q": "Find the size of the test.", "m": 2, "ms": [["M1", "1 − P(X ≤ 8 | p = 0.4)"], ["A1", "0.0153"]], "ans": {"a": 0.0152672666, "tol": 0.002, "unit": ""}}, {"q": "Find the power of the test when p = 0.7.", "m": 2, "ms": [["M1", "1 − P(X ≤ 8 | p = 0.7)"], ["A1", "0.4925"]], "ans": {"a": 0.4925157734, "tol": 0.001, "unit": ""}}, {"q": "Write down the probability of a Type II error when p = 0.7.", "m": 1, "ms": [["B1", "0.5075"]], "ans": {"a": 0.5074842266, "tol": 0.001, "unit": ""}}, {"q": "Suggest one way of increasing the power of the test.", "m": 1, "ms": [["B1", "use a larger sample, or a larger significance level"]]}]}, {"stem": "<p>X ~ Geo(p). H₀: p = 0.5 is tested against H₁: p &lt; 0.5, and H₀ is rejected when X ≥ 6.</p>", "parts": [{"q": "Find the size of the test.", "m": 2, "ms": [["M1", "P(X ≥ 6) = 0.5⁵"], ["A1", "0.03125"]], "ans": {"a": 0.03125, "tol": 0.001, "unit": ""}}, {"q": "Find the power function of the test.", "m": 2, "ms": [["M1", "the first five attempts all fail"], ["A1", "(1 − p)⁵"]]}, {"q": "Find the power when p = 0.2.", "m": 1, "ms": [["B1", "0.8⁵ = 0.3277"]], "ans": {"a": 0.32768, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>The number of calls in an hour is X ~ Po(λ). H₀: λ = 5 is tested against H₁: λ &lt; 5, and H₀ is rejected when X ≤ 1.</p>", "parts": [{"q": "Find the size of the test.", "m": 2, "ms": [["M1", "e^(−5)(1 + 5)"], ["A1", "0.0404"]], "ans": {"a": 0.0404, "tol": 0.003, "unit": ""}}, {"q": "Find the power of the test when λ = 2.", "m": 2, "ms": [["M1", "e^(−2)(1 + 2)"], ["A1", "0.4060"]], "ans": {"a": 0.406, "tol": 0.001, "unit": ""}}, {"q": "Describe a Type II error in this context.", "m": 1, "ms": [["B1", "concluding that the rate of calls has not fallen when in fact it has"]]}]}]}}, {"id": "fs2-regression", "module": "fs2", "title": "Least squares, residuals and regression inference", "refs": "1", "notes": ["A least-squares line of y on x minimises the sum of squared vertical residuals. Its slope is Sxy/Sxx and it passes through (x̄,ȳ). The regression of x on y minimises different residuals and is not generally obtained by rearranging the first line.", "Residual plots can reveal curvature or changing variability. Inference for a slope requires a suitable linear-error model, normally with independent errors of constant variance and normality for small-sample t procedures. Distinguish prediction within the observed range from unsupported extrapolation."], "example": {"q": "Given x̄=4, ȳ=9, Sxx=10 and Sxy=25, find the regression line and the residual at (5,13).", "steps": ["Slope b=25/10=2.5.", "Intercept a=9−2.5×4=−1.", "The fitted line is y=−1+2.5x.", "At x=5 the fitted value is 11.5.", "Residual=observed−fitted=13−11.5=1.5."]}, "practice": {"q": "Given x̄=2, ȳ=7, Sxx=8 and Sxy=12, find the regression of y on x.", "answer": null, "steps": ["b=12/8=1.5.", "a=7−1.5×2=4.", "The line is y=4+1.5x.", "It passes through (2,7)."]}, "check": {"q": "Given Sxy=25 and Sxx=10, find the slope of the least-squares line of y on x.", "a": 2.5}}, {"id": "fs2-continuous", "module": "fs2", "title": "Densities, distribution functions and continuous models", "refs": "2", "notes": ["A density is non-negative and has total integral one. Probabilities are areas, so P(X=x)=0 for an individual value in a continuous model. A distribution function F(x)=P(X≤x) is non-decreasing and includes the appropriate constant pieces outside the support.", "Moments are obtained by integrating x f(x) and x² f(x), and Var(X)=E(X²)−E(X)². Uniform and exponential models have specific support and assumptions. For Y=g(X), transform probability events or the CDF carefully; a non-monotonic mapping can have more than one inverse branch."], "example": {"q": "For f(x)=2x on 0≤x≤1 and zero elsewhere, find F(x) on the support and E(X).", "steps": ["The density integrates to [x²]₀¹=1.", "For 0≤x≤1, F(x)=∫₀ˣ2t dt=x².", "F(x)=0 below 0 and F(x)=1 above 1.", "E(X)=∫₀¹2x² dx=2/3."]}, "practice": {"q": "For the same density, find Var(X) and P(X>1/2).", "answer": null, "steps": ["E(X²)=∫₀¹2x³ dx=1/2.", "Variance=1/2−(2/3)²=1/18.", "P(X>1/2)=1−F(1/2)=1−1/4=3/4.", "A point endpoint has zero probability."]}, "check": {"q": "For f(x)=2x on [0,1], find F(1/2).", "a": 0.25}}, {"id": "fs2-correlation", "module": "fs2", "title": "Product moment, rank correlation and tests", "refs": "3", "notes": ["The product moment correlation coefficient measures linear association using centred products; Spearman’s coefficient measures monotonic association through ranks. With no ties, Spearman’s formula is 1−6Σd²/[n(n²−1)]. With tied observations use appropriate average ranks and the required method.", "A significance test needs the correct null model, alternative, sample size and critical value or p-value. Statistical association does not establish causation. Population bivariate normal assumptions matter for standard small-sample inference about Pearson correlation, and a scatter plot can reveal a misleading outlier."], "example": {"q": "For four untied paired ranks, Σd²=2. Find Spearman’s coefficient.", "steps": ["n=4, so n(n²−1)=4×15=60.", "rₛ=1−6×2/60.", "rₛ=0.8.", "This indicates positive rank association, not proof of a causal relationship."]}, "practice": {"q": "For five untied paired ranks, Σd²=4. Calculate Spearman’s coefficient.", "answer": 0.8, "steps": ["Denominator=5(25−1)=120.", "rₛ=1−24/120=0.8.", "A significance conclusion needs a specified test and critical value."]}, "check": {"q": "For n=4 untied ranks with Σd²=2, find Spearman correlation.", "a": 0.8}}, {"id": "fs2-combinations", "module": "fs2", "title": "Linear combinations of random variables", "refs": "4", "notes": ["Expectation is linear whether or not variables are independent. Variance includes covariance: Var(aX+bY)=a²Var(X)+b²Var(Y)+2abCov(X,Y). For independent variables the covariance term is zero; subtracting variables still adds their variances in that case.", "Independent normal variables have normal linear combinations. For other populations, an exact normal conclusion needs justification or an adequate approximation. State independence explicitly when using a sum of variances, and use standard deviations only after calculating the variance."], "example": {"q": "Independent X~N(10,4) and Y~N(3,1). Find the distribution of 2X−Y.", "steps": ["Mean=2×10−3=17.", "Variance=2²×4+(−1)²×1=17.", "The combination is normal.", "Therefore 2X−Y~N(17,17), where the second parameter is variance."]}, "practice": {"q": "X and Y have variances 9 and 4 and covariance 2. Find Var(X−2Y).", "answer": 17, "steps": ["Use 1²×9+(−2)²×4+2×1×(−2)×2.", "The result is 9+16−8=17.", "Ignoring covariance would give the incorrect value 25."]}, "check": {"q": "Independent X and Y have variances 4 and 1. Find Var(2X−Y).", "a": 17}}, {"id": "fs2-normal-ci", "module": "fs2", "title": "Normal means, confidence intervals and two-sample tests", "refs": "5", "notes": ["For independent observations from a normal population with known variance, standardise a sample mean using σ/√n. A two-sided 95% confidence interval is x̄±1.96σ/√n. Confidence describes the long-run coverage of the procedure, not a posterior probability assigned to a fixed population mean.", "For two independent means, the variance of their difference is σ₁²/n₁+σ₂²/n₂. Large-sample approximations may replace unknown variances by sample estimates when justified. Do not use an independent-samples formula for paired observations from the same individuals."], "example": {"q": "A normal population has known σ=6. A sample of 36 has mean 20. Find a 95% interval for μ.", "steps": ["Standard error=6/√36=1.", "Margin=1.96×1=1.96.", "The interval is (18.04,21.96).", "This procedure has 95% coverage under the stated model."]}, "practice": {"q": "Independent means have sample sizes 25 and 16, with known population variances 9 and 4. Find the standard error of their difference.", "answer": null, "steps": ["Variance=9/25+4/16=0.36+0.25=0.61.", "The standard error is √0.61≈0.7810.", "Both samples must be independent for this calculation.", "Use this standard error with the appropriate normal critical value."]}, "check": {"q": "If known σ=6 and n=36, find the normal-theory standard error.", "a": 1}}, {"id": "fs2-variance", "module": "fs2", "title": "Inference for variances and variance ratios", "refs": "6", "notes": ["For a random sample of size n from a normal population, (n−1)S²/σ² has a chi-squared distribution with n−1 degrees of freedom when S² uses denominator n−1. Rearrange the pivot carefully to form variance confidence limits; reciprocals reverse the critical-value order.", "The ratio of two independent sample variances from normal populations can be tested with an F distribution. Preserve the numerator and denominator degrees of freedom associated with the chosen ratio. These exact procedures depend strongly on normality and independence."], "example": {"q": "For n=10 and S²=10, test H₀:σ²=4 against σ²>4 at 5%, using the supplied critical value 16.919.", "steps": ["Statistic=(10−1)×10/4=22.5.", "Under H₀ it is χ² with 9 degrees of freedom.", "The upper-tail critical value is 16.919.", "22.5 exceeds 16.919, so reject H₀.", "There is evidence of a larger variance under the normal model."]}, "practice": {"q": "Independent normal samples of sizes 8 and 11 have sample variances 12 and 4. Give the F statistic and its degrees of freedom for their ratio.", "answer": null, "steps": ["Use S₁²/S₂²=12/4=3.", "Numerator degrees of freedom=8−1=7.", "Denominator degrees of freedom=11−1=10.", "Under equal population variances, the statistic has F(7,10)."]}, "check": {"q": "For a normal sample of n=10, what are the degrees of freedom of the variance chi-squared pivot?", "a": 9}}, {"id": "fs2-t", "module": "fs2", "title": "Student t, paired tests and pooled variances", "refs": "7", "notes": ["When a normal population variance is unknown, a one-sample mean statistic uses t=(x̄−μ₀)/(S/√n) with n−1 degrees of freedom. A paired test applies this procedure to the within-pair differences; the pairs, rather than all individual observations, form the independent sample.", "A pooled two-sample t procedure assumes independent normal populations with equal variances. Pool using degrees-of-freedom weights, not a simple average unless sample sizes agree. Match the tail of the critical value to the alternative and keep a non-rejection conclusion appropriately cautious."], "example": {"q": "A normal sample of n=9 has mean 12 and S=3. Test μ=10 against μ≠10 at 5%, using critical value 2.306.", "steps": ["Standard error=3/√9=1.", "t=(12−10)/1=2, with 8 degrees of freedom.", "|2|<2.306, so do not reject H₀.", "There is insufficient evidence of a difference at 5%; this does not prove μ=10."]}, "practice": {"q": "Ten paired differences have mean 2 and standard deviation 3. Calculate the test statistic for a zero population mean difference.", "answer": null, "steps": ["The standard error is 3/√10.", "t=2/(3/√10)=2√10/3≈2.108.", "Use 9 degrees of freedom.", "The analysis is on paired differences, not 20 independent measurements."]}, "check": {"q": "A one-sample t test uses 9 independent observations. Find its degrees of freedom.", "a": 8}}, {"id": "fm1-impulse", "module": "fm1", "title": "Momentum, impulse and vector change", "refs": "1", "notes": ["Momentum is the vector mv, and impulse equals the change in momentum. Draw or state the positive direction before subtracting velocities. A force–time graph gives impulse as signed area; for a variable force use its time integral.", "In an isolated collision, internal impulses cancel and total momentum is conserved over the short impact. Kinetic energy need not be conserved. In vector problems, apply the impulse–momentum relation component by component and report the impulse direction, not only its magnitude."], "example": {"q": "A 0.5 kg particle changes velocity from (4,−2) to (−2,6) m/s. Find the impulse.", "steps": ["Velocity change=(−2−4,6−(−2))=(−6,8).", "Impulse=0.5(−6,8)=(−3,4) N s.", "Magnitude=√(9+16)=5 N s.", "The vector specifies the impulse direction."]}, "practice": {"q": "A 2 kg particle moving at +3 m/s rebounds at −1 m/s. Find its impulse.", "answer": -8, "steps": ["Change in velocity=−1−3=−4 m/s.", "Impulse=2×(−4)=−8 N s.", "The impulse acts opposite to the original positive direction."]}, "check": {"q": "A 0.5 kg particle has velocity change (−6,8) m/s. Find impulse magnitude in N s.", "a": 5}, "deep": {"tip": "Choose a positive direction (or use vectors) and keep the signs of every velocity; impulse equals the change in momentum, m(v − u). In a collision or explosion, total momentum is conserved but kinetic energy usually is not, so find the velocities with momentum before you discuss energy.", "examples": [{"title": "A rebounding ball", "q": "A ball of mass 0.2 kg hits the ground at 8 m s⁻¹ and rebounds at 5 m s⁻¹. Find the impulse exerted by the ground.", "steps": ["Take upwards as positive: u = −8 and v = 5.", "I = m(v − u) = 0.2(5 − (−8)).", "I = 2.6 N s, upwards."]}, {"title": "Impulse as a vector", "q": "A particle of mass 0.4 kg moving with velocity (5i + 2j) m s⁻¹ receives an impulse of (−3i + 4j) N s. Find its new velocity and speed.", "steps": ["I = m(v − u), so v = u + I/m.", "v = (5i + 2j) + (−7.5i + 10j).", "v = (−2.5i + 12j) m s⁻¹.", "Speed = √(6.25 + 144) = 12.26 m s⁻¹."]}, {"title": "Coalescing particles", "q": "A particle of mass 3 kg moving at 4 m s⁻¹ collides with a particle of mass 2 kg moving at 1 m s⁻¹ in the opposite direction, and they coalesce. Find their common velocity and the loss of kinetic energy.", "steps": ["Momentum: 3(4) + 2(−1) = 5v.", "v = 2 m s⁻¹ in the original direction of the 3 kg particle.", "Kinetic energy before = 24 + 1 = 25 J; after = ½ × 5 × 2² = 10 J.", "Loss = 15 J."]}], "fills": [{"q": "A force of 6 N acts for 0.5 s.", "lines": ["impulse = [[3]] N s"]}, {"q": "A 2 kg particle speeds up from 3 to 7 m s⁻¹ in a straight line.", "lines": ["impulse = [[8]] N s"]}, {"q": "A 4 kg particle moving at 2.5 m s⁻¹.", "lines": ["momentum = [[10]] N s"]}], "exam": [{"stem": "<p>A ball of mass 0.15 kg moving horizontally at 20 m s⁻¹ is hit by a bat and moves back along the same line at 30 m s⁻¹.</p>", "parts": [{"q": "Find the magnitude of the impulse on the ball.", "m": 2, "ms": [["M1", "0.15(30 − (−20))"], ["A1", "7.5 N s"]], "ans": {"a": 7.5, "tol": 0.001, "unit": "N s"}}, {"q": "The ball is in contact with the bat for 0.05 s. Find the average force on the ball.", "m": 1, "ms": [["B1", "150 N"]], "ans": {"a": 150.0, "tol": 0.001, "unit": "N"}}]}, {"stem": "<p>A particle P of mass 0.5 kg moving with velocity (4i − 3j) m s⁻¹ receives an impulse of (−2i + 5j) N s.</p>", "parts": [{"q": "Find the velocity of P immediately after the impulse.", "m": 2, "ms": [["M1", "u + I/m"], ["A1", "7j m s⁻¹"]]}, {"q": "Find the gain in kinetic energy of P.", "m": 3, "ms": [["M1", "initial kinetic energy ½ × 0.5 × 25 = 6.25 J"], ["M1", "final kinetic energy ½ × 0.5 × 49 = 12.25 J"], ["A1", "6 J"]], "ans": {"a": 6.0, "tol": 0.001, "unit": "J"}}]}, {"stem": "<p>A gun of mass 1200 kg fires a shell of mass 8 kg horizontally at 300 m s⁻¹. The gun is free to recoil horizontally.</p>", "parts": [{"q": "Find the speed of recoil of the gun.", "m": 2, "ms": [["M1", "conservation of momentum: 1200v = 8 × 300"], ["A1", "2 m s⁻¹"]], "ans": {"a": 2.0, "tol": 0.001, "unit": "m s⁻¹"}}, {"q": "The gun is brought to rest in 0.5 m by a constant resisting force. Find the size of the force.", "m": 3, "ms": [["M1", "kinetic energy ½ × 1200 × 2² = 2400 J"], ["M1", "work done: F × 0.5 = 2400"], ["A1", "4800 N"]], "ans": {"a": 4800.0, "tol": 0.001, "unit": "N"}}]}]}}, {"id": "fm1-energy", "module": "fm1", "title": "Work, energy and power", "refs": "2", "notes": ["Work by a constant force is the scalar product of force and displacement. For a variable force along a line, work is ∫F dx. The work–energy relation accounts for all relevant forces: a gain in kinetic energy is not necessarily equal to the work by the driving force alone.", "Instantaneous power is F·v. A constant-power model therefore gives driving force P/v away from zero speed and may be unrealistic at rest. Include changes in gravitational potential energy and work against resistance with consistent signs."], "example": {"q": "A 2 kg particle speeds from 3 to 5 m/s while a resistance does 8 J of negative work. Find the work by the driving force.", "steps": ["Change in kinetic energy=(1/2)×2×(25−9)=16 J.", "Net work=driving work−8.", "Driving work−8=16.", "Driving work=24 J."]}, "practice": {"q": "A force F(x)=3x² N acts along a displacement from x=0 to x=2 m. Find its work.", "answer": 8, "steps": ["Work=∫₀²3x² dx.", "The antiderivative is x³.", "Work=8 J."]}, "check": {"q": "Find the kinetic energy increase for 2 kg changing speed from 3 to 5 m/s, in joules.", "a": 16}, "deep": {"tip": "Write the work–energy principle as one equation: initial energy + work by driving forces = final energy + work against resistances, with each term in joules. For power, use P = Fv with the driving force F, then Newton’s second law for acceleration; maximum speed occurs when the driving force equals the total resistance.", "examples": [{"title": "Power and acceleration", "q": "A car of mass 900 kg moves on a level road against a resistance of 600 N. Its engine works at 18 kW. Find its acceleration when its speed is 15 m s⁻¹, and its maximum speed.", "steps": ["Driving force F = P/v = 18 000/15 = 1200 N.", "Newton’s second law: 1200 − 600 = 900a.", "a = ⅔ m s⁻².", "At maximum speed F = 600, so v = 18 000/600 = 30 m s⁻¹."]}, {"title": "Work–energy on a rough slope", "q": "A particle of mass 5 kg is released from rest and slides 4 m down a rough plane inclined at 30°. The coefficient of friction is 0.2. Find its speed.", "steps": ["Loss of potential energy = 5g × 4 sin 30° = 98 J.", "R = 5g cos 30° = 42.4 N, so friction = 0.2R = 8.49 N, doing 33.9 J of work.", "½ × 5v² = 98 − 33.9 = 64.1.", "v = 5.06 m s⁻¹."]}], "fills": [{"q": "A driving force of 400 N at 25 m s⁻¹.", "lines": ["power = [[10000]] W"]}, {"q": "A 3 kg particle moving at 4 m s⁻¹.", "lines": ["kinetic energy = [[24]] J"]}, {"q": "A 2 kg mass raised 5 m (g = 9.8).", "lines": ["gain in potential energy = [[98]] J"]}], "exam": [{"stem": "<p>A lorry of mass 4000 kg moves up a straight road inclined at α to the horizontal, where sin α = 1/20. The resistance to motion is 1500 N. The lorry moves at a constant speed of 12 m s⁻¹.</p>", "parts": [{"q": "Find the power of the engine.", "m": 3, "ms": [["M1", "driving force = 1500 + 4000g sin α"], ["A1", "3460 N"], ["A1", "41.5 kW"]], "ans": {"a": 41520.0, "tol": 0.002, "unit": "W"}}, {"q": "The lorry reaches a level road. The power and the resistance are unchanged. Find the acceleration of the lorry at the instant its speed is 12 m s⁻¹.", "m": 3, "ms": [["M1", "driving force 41 520/12 = 3460 N"], ["M1", "3460 − 1500 = 4000a"], ["A1", "0.49 m s⁻²"]], "ans": {"a": 0.49, "tol": 0.001, "unit": "m s⁻²"}}]}, {"stem": "", "parts": [{"q": "A particle of mass 2 kg is projected up a line of greatest slope of a rough plane inclined at 30° with speed 6 m s⁻¹. The coefficient of friction is 0.25. Use the work–energy principle to find how far up the plane the particle moves before coming to rest.", "m": 4, "ms": [["M1", "friction = 0.25 × 2g cos 30° = 4.24 N"], ["M1", "kinetic energy ½ × 2 × 36 = 36 J"], ["M1", "36 = (2g sin 30° + 4.24)d"], ["A1", "d = 2.56 m"]], "ans": {"a": 2.5634590558, "tol": 0.003, "unit": "m"}}]}, {"stem": "", "parts": [{"q": "A pump raises 50 kg of water per second through a height of 12 m and ejects it at 8 m s⁻¹. Find the power of the pump.", "m": 3, "ms": [["M1", "potential energy per second 50g × 12 = 5880 J"], ["M1", "kinetic energy per second ½ × 50 × 8² = 1600 J"], ["A1", "7480 W"]], "ans": {"a": 7480.0, "tol": 0.001, "unit": "W"}}]}]}}, {"id": "fm1-elastic", "module": "fm1", "title": "Elastic strings, springs and energy", "refs": "3", "notes": ["For a light elastic string of natural length l and modulus λ, tension is λx/l when extension x>0. A string is slack when compressed, whereas an ideal spring can push as well as pull. Elastic energy stored at extension x is λx²/(2l).", "Choose the energy reference for gravitational potential and account for any slack stage before the string becomes taut. At a turning point the instantaneous speed is zero, but acceleration need not be zero. Check whether the calculated extension lies in the physical regime assumed."], "example": {"q": "A string has natural length 2 m and modulus 40 N. Find tension and elastic energy at extension 0.3 m.", "steps": ["Tension=40×0.3/2=6 N.", "Elastic energy=40×0.3²/(2×2).", "The energy is 0.9 J.", "The total length is 2.3 m; extension is not the total length."]}, "practice": {"q": "An elastic spring has natural length 0.5 m and modulus 30 N. Find the energy stored when stretched to length 0.7 m.", "answer": 1.2, "steps": ["Extension=0.7−0.5=0.2 m.", "Energy=30×0.2²/(2×0.5).", "Energy=1.2 J."]}, "check": {"q": "For natural length 2 m, modulus 40 N and extension 0.3 m, find string tension in newtons.", "a": 6}, "deep": {"tip": "Use Hooke’s law T = λx/l for forces and E = λx²/2l for energy, where x is the extension, not the stretched length. In energy problems list every form at the start and at the end: kinetic, gravitational and elastic. Remember that a string is slack (no tension) once it is shorter than its natural length.", "examples": [{"title": "Equilibrium on an elastic string", "q": "A particle of mass 2 kg hangs in equilibrium on an elastic string of natural length 1.5 m and modulus 49 N. Find the extension.", "steps": ["Equilibrium: T = mg = 19.6 N.", "Hooke’s law: 49x/1.5 = 19.6.", "x = 0.6 m."]}, {"title": "Released from a spring", "q": "A particle of mass 0.5 kg on a smooth horizontal table is attached to a spring of natural length 0.8 m and modulus 20 N. It is pulled out to an extension of 0.2 m and released. Find its speed as it passes through the natural length.", "steps": ["Elastic energy at release = 20 × 0.2²/(2 × 0.8) = 0.5 J.", "At the natural length all of this is kinetic energy.", "½ × 0.5v² = 0.5, so v² = 2.", "v = √2 ≈ 1.41 m s⁻¹."]}, {"title": "Falling on an elastic string", "q": "A particle of mass 1 kg is attached to one end of a light elastic string of natural length 1 m and modulus 4g N, whose other end is fixed at O. The particle is dropped from O. Find its greatest extension.", "steps": ["At the lowest point the particle is at rest, having fallen 1 + x metres.", "Loss of potential energy = elastic energy: g(1 + x) = 4gx²/2.", "2x² − x − 1 = 0, so (2x + 1)(x − 1) = 0.", "Greatest extension x = 1 m."]}], "fills": [{"q": "λ = 20 N, l = 1.5 m, extension 0.3 m.", "lines": ["tension = [[4]] N"]}, {"q": "λ = 30 N, l = 0.5 m, extension 0.2 m.", "lines": ["elastic energy = [[1.2]] J"]}, {"q": "A 3 kg mass hangs on a string with λ = 147 N, l = 2 m (g = 9.8).", "lines": ["extension = [[0.4]] m"]}], "exam": [{"stem": "<p>A particle of mass 0.4 kg hangs on a light elastic string of natural length 0.8 m and modulus 9.8 N, attached to a fixed point.</p>", "parts": [{"q": "Find the extension of the string in equilibrium.", "m": 2, "ms": [["M1", "0.4g = 9.8x/0.8"], ["A1", "0.32 m"]], "ans": {"a": 0.32, "tol": 0.001, "unit": "m"}}, {"q": "The particle is pulled down a further 0.1 m and released from rest. Find its speed as it passes through the equilibrium position.", "m": 4, "ms": [["M1", "elastic energy at extensions 0.42 m and 0.32 m"], ["M1", "includes the gain in potential energy 0.4g × 0.1"], ["M1", "½ × 0.4v² = 0.453 − 0.392"], ["A1", "0.553 m s⁻¹"]], "ans": {"a": 0.5533985905, "tol": 0.003, "unit": "m s⁻¹"}}]}, {"stem": "", "parts": [{"q": "A particle of mass 1.5 kg on a smooth horizontal surface is held against a spring of natural length 0.5 m and modulus 60 N, compressing it by 0.15 m. It is released. Find the speed with which it leaves the spring.", "m": 3, "ms": [["M1", "elastic energy 60 × 0.15²/(2 × 0.5)"], ["A1", "1.35 J"], ["A1", "1.34 m s⁻¹"]], "ans": {"a": 1.3416407865, "tol": 0.003, "unit": "m s⁻¹"}}]}, {"stem": "<p>A bungee jumper of mass 70 kg is attached to an elastic rope of natural length 20 m. The other end is fixed to a bridge. She falls from rest at the bridge and first comes to instantaneous rest 45 m below it.</p>", "parts": [{"q": "Find the modulus of elasticity of the rope.", "m": 3, "ms": [["M1", "energy equation: loss of potential energy = elastic energy"], ["M1", "70g × 45 = λ × 25²/(2 × 20)"], ["A1", "λ = 1980 N (3 s.f.)"]], "ans": {"a": 1975.68, "tol": 0.003, "unit": "N"}}, {"q": "State one modelling assumption you have made.", "m": 1, "ms": [["B1", "the jumper is a particle, or air resistance is negligible, or the rope is light"]]}]}]}}, {"id": "fm1-direct", "module": "fm1", "title": "Direct collisions and Newton’s law of restitution", "refs": "4", "notes": ["For a direct collision use momentum conservation together with speed of separation=e×speed of approach. Write a signed velocity equation consistent with the ordering of the particles; using unsigned speeds too early can conceal a rebound.", "The restitution coefficient satisfies 0≤e≤1 for the usual model. For successive collisions, finish the first event, update positions and velocities and check whether the next proposed collision can actually occur. Kinetic energy loss is non-negative in the ordinary two-particle model."], "example": {"q": "A 2 kg particle at 3 m/s strikes a stationary 1 kg particle. The coefficient of restitution is 1/2. Find velocities after impact.", "steps": ["Momentum: 2v₁+v₂=6.", "Restitution: v₂−v₁=(1/2)(3−0)=1.5.", "Substitute v₂=v₁+1.5 into momentum.", "3v₁=4.5 gives v₁=1.5 and v₂=3 m/s.", "The particles separate since v₂>v₁."]}, "practice": {"q": "Two equal masses collide directly. Initial velocities are 4 and 0 m/s and e=1/2. Find the final velocities.", "answer": null, "steps": ["Momentum gives v₁+v₂=4.", "Restitution gives v₂−v₁=2.", "Solve to get v₁=1 and v₂=3 m/s.", "Check momentum and speed of separation."]}, "check": {"q": "Equal masses collide with u₁=4, u₂=0 and e=1/2. Find the speed of separation.", "a": 2}, "deep": {"tip": "Draw before-and-after diagrams with every velocity arrow in the same positive direction, so an answer that comes out negative tells you the particle moves the other way. Use two equations: conservation of momentum and Newton’s law of restitution, written as separation speed = e × approach speed.", "examples": [{"title": "A head-on collision", "q": "A particle of mass 3 kg moving at 5 m s⁻¹ collides directly with a particle of mass 2 kg moving at 2 m s⁻¹ in the opposite direction. The coefficient of restitution is 0.4. Find their velocities after the collision and the kinetic energy lost.", "steps": ["Momentum: 3(5) + 2(−2) = 3v₁ + 2v₂, so 3v₁ + 2v₂ = 11.", "Restitution: v₂ − v₁ = 0.4 × (5 + 2) = 2.8.", "Solving: v₁ = 1.08 m s⁻¹ and v₂ = 3.88 m s⁻¹, both in the original direction of the 3 kg particle.", "Kinetic energy before = 41.5 J and after = 16.80 J, so 24.7 J is lost."]}, {"title": "Rebounding from a wall", "q": "A sphere hits a smooth wall at right angles with speed 6 m s⁻¹ and e = ⅔. Find its speed after the impact and after a second impact with a parallel wall.", "steps": ["After the first impact: ⅔ × 6 = 4 m s⁻¹.", "Its speed is unchanged until it reaches the second wall.", "After the second impact: ⅔ × 4 = 8/3 m s⁻¹."]}], "fills": [{"q": "Equal masses, e = 1: A at 5 m s⁻¹ hits B at rest.", "lines": ["B moves at [[5]] m s⁻¹"]}, {"q": "A ball hits a wall at 10 m s⁻¹ with e = 0.6.", "lines": ["rebound speed = [[6]] m s⁻¹"]}, {"q": "Approach speed 8 m s⁻¹, e = 0.25.", "lines": ["separation speed = [[2]] m s⁻¹"]}], "exam": [{"stem": "<p>Particles P and Q, of masses 2 kg and 4 kg, move in the same direction along a straight line with speeds 6 m s⁻¹ and 1 m s⁻¹. P collides with Q. The coefficient of restitution is 0.5.</p>", "parts": [{"q": "Find the speeds of P and Q after the collision.", "m": 5, "ms": [["M1", "conservation of momentum: 2v₁ + 4v₂ = 16"], ["M1", "restitution: v₂ − v₁ = 0.5 × 5"], ["M1", "solves the simultaneous equations"], ["A1", "P: 1 m s⁻¹"], ["A1", "Q: 3.5 m s⁻¹"]]}, {"q": "Find the kinetic energy lost in the collision.", "m": 2, "ms": [["M1", "38 − (1 + 24.5)"], ["A1", "12.5 J"]], "ans": {"a": 12.5, "tol": 0.001, "unit": "J"}}, {"q": "Q then hits a fixed wall at right angles, with coefficient of restitution 0.4. Show that P and Q collide again.", "m": 2, "ms": [["M1", "Q rebounds at 1.4 m s⁻¹"], ["A1", "P moves towards the wall and Q towards P, so they approach each other"]]}]}, {"stem": "<p>A particle A of mass m moving with speed u collides directly with a particle B of mass 2m at rest. The coefficient of restitution is e.</p>", "parts": [{"q": "Show that the speed of B after the collision is u(1 + e)/3.", "m": 3, "ms": [["M1", "momentum: mu = mv_A + 2mv_B"], ["M1", "restitution: v_B − v_A = eu"], ["A1", "eliminates v_A to obtain the given result"]]}, {"q": "Find the velocity of A after the collision, and the range of values of e for which A reverses its direction.", "m": 2, "ms": [["A1", "v_A = u(1 − 2e)/3"], ["B1", "reverses if e &gt; ½"]]}]}, {"stem": "<p>A ball of mass 0.3 kg moving horizontally at 8 m s⁻¹ hits a fixed vertical wall at right angles and rebounds at 5 m s⁻¹.</p>", "parts": [{"q": "Find the coefficient of restitution between the ball and the wall.", "m": 1, "ms": [["B1", "e = 5/8"]], "ans": {"a": 0.625, "tol": 0.001, "unit": ""}}, {"q": "Find the magnitude of the impulse exerted by the wall.", "m": 2, "ms": [["M1", "0.3 × (5 − (−8))"], ["A1", "3.9 N s"]], "ans": {"a": 3.9, "tol": 0.001, "unit": "N s"}}, {"q": "Find the kinetic energy lost in the impact.", "m": 2, "ms": [["M1", "½ × 0.3 × (64 − 25)"], ["A1", "5.85 J"]], "ans": {"a": 5.85, "tol": 0.001, "unit": "J"}}]}]}}, {"id": "fm1-oblique", "module": "fm1", "title": "Oblique impacts and successive rebounds", "refs": "5", "notes": ["For impact with a smooth fixed plane, resolve velocity normal and parallel to the plane. The parallel component is unchanged; the normal component reverses and is multiplied by e. Recombine the components to obtain speed and angle after impact.", "An impulsive force from a smooth surface acts normally. The energy loss arises from the normal component, not the whole incident speed. For successive impacts, use the new direction and check the geometry before applying the next normal–tangential decomposition."], "example": {"q": "A particle has velocity (3,−4) m/s and strikes the horizontal smooth line y=0. Let e=1/2. Find the rebound velocity.", "steps": ["The tangential component is 3.", "The incident normal component is −4.", "The outgoing normal component is −e(−4)=2.", "The new velocity is (3,2) m/s.", "Its speed is √13 m/s."]}, "practice": {"q": "A particle with velocity (−6,8) strikes the vertical smooth line x=0 with e=1/3. Find the rebound velocity and speed.", "answer": null, "steps": ["The normal x-component reverses and scales: −(1/3)(−6)=2.", "The parallel y-component remains 8.", "The velocity is (2,8) m/s.", "The speed is √68=2√17 m/s."]}, "check": {"q": "A normal velocity component −4 rebounds from a smooth fixed wall with e=1/2. Find the outgoing normal component.", "a": 2}, "deep": {"tip": "Resolve every velocity parallel and perpendicular to the surface, or along and perpendicular to the line of centres. Smooth contact means the parallel components are unchanged; restitution and (for two spheres) momentum act only along the normal or line of centres. Recombine at the end for speed and direction.", "examples": [{"title": "Oblique impact with a wall", "q": "A smooth sphere hits a smooth wall with speed 10 m s⁻¹ at 60° to the wall. The coefficient of restitution is 0.5. Find its speed and direction after the impact.", "steps": ["Parallel component 10 cos 60° = 5, unchanged.", "Perpendicular component 10 sin 60° = 8.66, reversed and multiplied by 0.5: 4.33.", "Speed = √(5² + 4.33²) = 6.61 m s⁻¹.", "Angle with the wall = arctan(4.33/5) = 40.9°."]}, {"title": "Using vectors", "q": "A particle of mass 0.5 kg moving with velocity (4i − 6j) m s⁻¹ hits a smooth fixed surface whose normal is parallel to j. The coefficient of restitution is 0.5. Find its velocity after impact, the impulse and the loss of kinetic energy.", "steps": ["The i-component is unchanged; the j-component becomes +0.5 × 6 = 3.", "v = (4i + 3j) m s⁻¹.", "Impulse = 0.5 × (3 − (−6))j = 4.5j N s.", "Kinetic energy loss = ½ × 0.5 × (52 − 25) = 6.75 J."]}, {"title": "Two spheres", "q": "Smooth spheres A and B have equal mass. A moves with velocity (3i + 4j) m s⁻¹ and hits B, which is at rest. At impact the line of centres is parallel to i and e = ½. Find their velocities after the collision.", "steps": ["Perpendicular to the line of centres, A keeps 4j and B has 0j.", "Along i: momentum 3 = a + b; restitution b − a = ½ × 3.", "b = 2.25 and a = 0.75.", "A: (0.75i + 4j) m s⁻¹; B: 2.25i m s⁻¹."]}], "fills": [{"q": "Perpendicular component 6 m s⁻¹, e = 0.5.", "lines": ["after impact: [[3]] m s⁻¹"]}, {"q": "A smooth surface: parallel component 8 m s⁻¹.", "lines": ["after impact: [[8]] m s⁻¹"]}, {"q": "Components 3 and 4 after impact.", "lines": ["speed = [[5]] m s⁻¹"]}], "exam": [{"stem": "<p>A ball strikes a smooth horizontal floor with speed 12 m s⁻¹ at an angle of 30° to the floor. The coefficient of restitution is 0.6.</p>", "parts": [{"q": "Find the speed of the ball immediately after the impact.", "m": 3, "ms": [["M1", "horizontal 12 cos 30° unchanged"], ["M1", "vertical 0.6 × 12 sin 30° = 3.6"], ["A1", "11.0 m s⁻¹"]], "ans": {"a": 10.9981816679, "tol": 0.003, "unit": "m s⁻¹"}}, {"q": "Find the angle between the ball’s path and the floor after the impact.", "m": 2, "ms": [["M1", "tan θ = 3.6/(12 cos 30°)"], ["A1", "19.1°"]], "ans": {"a": 19.1, "tol": 0.003, "unit": "°"}}, {"q": "Find the fraction of the ball’s kinetic energy lost.", "m": 2, "ms": [["M1", "1 − 121/144"], ["A1", "0.16"]], "ans": {"a": 0.16, "tol": 0.001, "unit": ""}}]}, {"stem": "<p>Smooth spheres A (mass 2 kg) and B (mass 1 kg) have velocities (5i + 2j) m s⁻¹ and (−i + 3j) m s⁻¹. When they collide the line of centres is parallel to i, and e = ½.</p>", "parts": [{"q": "Find the velocities of A and B immediately after the collision.", "m": 5, "ms": [["B1", "j-components unchanged: 2j and 3j"], ["M1", "momentum along i: 2a + b = 9"], ["M1", "restitution: b − a = ½ × 6"], ["A1", "a = 2, b = 5"], ["A1", "A: (2i + 2j), B: (5i + 3j)"]]}, {"q": "Find the impulse on B.", "m": 2, "ms": [["M1", "1 × (5 − (−1))i"], ["A1", "6i N s"]]}]}, {"stem": "<p>A particle of mass 0.2 kg moving with velocity (8i + 6j) m s⁻¹ hits a smooth fixed wall whose normal is parallel to i. Its speed after the impact is 6.5 m s⁻¹.</p>", "parts": [{"q": "Find the coefficient of restitution.", "m": 3, "ms": [["M1", "velocity after (−8e i + 6j)"], ["M1", "64e² + 36 = 6.5²"], ["A1", "e = 5/16"]], "ans": {"a": 0.3125, "tol": 0.001, "unit": ""}}, {"q": "Find the magnitude of the impulse on the particle.", "m": 2, "ms": [["M1", "0.2 × 8(1 + e)"], ["A1", "2.1 N s"]], "ans": {"a": 2.1, "tol": 0.001, "unit": "N s"}}]}]}}, {"id": "fm2-circular", "module": "fm2", "title": "Uniform and vertical circular motion", "refs": "1", "notes": ["Angular speed ω and tangential speed satisfy v=rω. The radial acceleration is v²/r towards the centre, so resolve forces in that inward direction rather than introducing a separate physical “centripetal force”. Gravity’s radial component changes around a vertical circle.", "Combine energy conservation with the radial equation when speed varies with height. A string requires non-negative tension and a surface contact requires a non-negative normal reaction. The limiting loss-of-contact condition is found by setting that force to zero, then checking where it occurs."], "example": {"q": "A 0.5 kg particle moves on a horizontal smooth table in a circle of radius 2 m at speed 4 m/s, held by a string. Find tension.", "steps": ["Radial acceleration=v²/r=16/2=8 m/s².", "The string supplies the horizontal radial force.", "T=ma=0.5×8=4 N."]}, "practice": {"q": "A particle on a light string completes a vertical circle of radius r. State the least speed at the top for a taut-string model.", "answer": null, "steps": ["At the top, inward forces give T+mg=mv²/r.", "The limiting taut condition is T=0.", "Then v²=gr, so v=√(gr).", "Other positions must also satisfy the physical constraints."]}, "check": {"q": "Find radial acceleration for speed 4 m/s and radius 2 m, in m/s².", "a": 8}}, {"id": "fm2-centres", "module": "fm2", "title": "Centres of mass of particles, rods and laminae", "refs": "2, 3.1", "notes": ["A centre of mass is a mass-weighted position: x̄=Σmᵢxᵢ/Σmᵢ. For a continuous body replace the sums by integrals with the appropriate density and area or length element. Symmetry can establish one coordinate, but only if the mass distribution has that symmetry.", "For composite laminae, treat a removed region as negative mass at its own centre. Distinguish the geometric centre from the centre of mass of a non-uniform body. When integrating a rod, include its linear density in both the mass integral and the first moment."], "example": {"q": "A rod occupies 0≤x≤2 with linear density ρ(x)=kx, k>0. Find its centre of mass.", "steps": ["Mass M=∫₀²kx dx=2k.", "First moment=∫₀²kx² dx=8k/3.", "x̄=(8k/3)/(2k)=4/3.", "The centre lies towards the denser right end."]}, "practice": {"q": "Particles of masses 2,3 and 5 kg lie at x=0,2 and 4 m. Find their centre of mass.", "answer": 2.6, "steps": ["Total mass=10 kg.", "First moment=2×0+3×2+5×4=26.", "x̄=26/10=2.6 m."]}, "check": {"q": "Find the centre-of-mass x-coordinate of equal masses at x=2 and x=8.", "a": 5}}, {"id": "fm2-equilibrium", "module": "fm2", "title": "Rigid-body equilibrium, sliding and toppling", "refs": "2.1, 3.2–3.3", "notes": ["A rigid body in equilibrium has zero resultant force and zero resultant moment. Choose a pivot that eliminates unknown forces where possible. At impending sliding use the limiting friction law F=μR; at impending toppling the resultant contact force acts through an edge.", "Compare the conditions for both possible failures. A body does not necessarily topple just because a toppling angle has been calculated: it may slide first. The centre-of-mass projection must remain within the support base for static stability."], "example": {"q": "A uniform rectangular block has base width 0.6 m and height 0.8 m. Find the tilt angle at impending toppling on a rough plane, assuming no sliding.", "steps": ["The centre is 0.3 m horizontally and 0.4 m vertically from the lower edge.", "At toppling, the weight line passes through that edge.", "tanθ=0.3/0.4=3/4.", "θ≈36.9°.", "The no-sliding assumption must be checked against friction if μ is supplied."]}, "practice": {"q": "A uniform block has base 0.4 m and height 1 m. Give the no-sliding toppling angle condition and the minimum μ to reach it without earlier sliding.", "answer": null, "steps": ["tanθ=(0.4/2)/(1/2)=0.4.", "θ=arctan0.4≈21.8°.", "The limiting sliding condition is tanθ=μ.", "Require μ≥0.4 to avoid sliding before the toppling angle; equality is simultaneous."]}, "check": {"q": "A block has base 0.6 and height 0.8. Find tanθ at toppling, assuming no sliding.", "a": 0.75}}, {"id": "fm2-dynamics", "module": "fm2", "title": "Variable resistance and simple harmonic motion", "refs": "4", "notes": ["Write the equation of motion with an explicit positive direction. If resistance depends on velocity, acceleration may be written dv/dt or v dv/dx according to the independent variable. A terminal velocity solves the zero-acceleration equation, but the full solution determines how it is approached.", "Simple harmonic motion satisfies x″=−ω²x relative to an equilibrium position. Its period is 2π/ω and v²=ω²(A²−x²). The minus sign indicates restoring acceleration towards equilibrium. A spring system may require a shift from natural length to equilibrium extension before this form appears."], "example": {"q": "A particle satisfies x″=−9x, with x(0)=2 and x′(0)=0. Find x and the period.", "steps": ["ω=3.", "The initial conditions select x=2cos3t.", "The amplitude is 2.", "The period is 2π/3.", "Velocity is −6sin3t, consistent with rest initially."]}, "practice": {"q": "A falling body obeys dv/dt=10−2v with v(0)=0. Find v(t) and terminal velocity.", "answer": null, "steps": ["The equilibrium speed satisfies 10−2v=0, so v=5.", "Solve the linear equation to obtain v=5+Ce^(−2t).", "At t=0, C=−5.", "v(t)=5(1−e^(−2t)), approaching 5 as t increases."]}, "check": {"q": "If x″=−9x, what is the period divided by π?", "a": 0.6666666666666666}}, {"id": "fm2-kinematics", "module": "fm2", "title": "Vector kinematics and projectiles", "refs": "5", "notes": ["Differentiate a vector position to obtain velocity and then acceleration; integrate with separate constants for each component. A force depending on time changes velocity through its time integral. Speed is the magnitude of velocity and is not obtained by adding its components.", "For a projectile, resolve the initial velocity horizontally and vertically, apply the landing-height condition and select the physically relevant positive time. In three dimensions the horizontal projection can have two components, while gravity acts vertically. Check whether resistance is explicitly ignored and which vertical origin was chosen."], "example": {"q": "A particle has r(t)=(t²,3t,4−t²) m. Find velocity, acceleration and speed at t=1.", "steps": ["v(t)=(2t,3,−2t).", "a(t)=(2,0,−2).", "v(1)=(2,3,−2).", "The speed is √(4+9+4)=√17 m/s."]}, "practice": {"q": "A projectile starts at ground level with velocity (6,8) m/s in a vertical plane. With g=10 m/s² and no resistance, find flight time and horizontal range.", "answer": null, "steps": ["Vertical displacement is y=8t−5t².", "Landing at y=0 gives t=0 or t=8/5.", "The flight time is 1.6 s.", "Horizontal range=6×1.6=9.6 m."]}, "check": {"q": "For r(t)=(t²,3t,4−t²), find the y-component of velocity.", "a": 3}}, {"id": "d1-algorithms", "module": "d1", "title": "Sorting, packing and graph terminology", "refs": "1", "notes": ["An algorithm is a finite, unambiguous sequence of steps. State the version of a sorting or bin-packing algorithm, apply its tie-breaking rule consistently and show intermediate passes. An algorithm’s order describes how work grows with input size, not a fixed execution time.", "A graph has vertices and edges; distinguish a path, cycle, tree and spanning tree. Planarity concerns whether a crossing-free drawing exists, not whether the current drawing has crossings. First-fit decreasing requires sorting before packing, and a feasible packing is not automatically optimal."], "example": {"q": "Use first-fit decreasing to pack items 6,5,4,3,2 into bins of capacity 10.", "steps": ["Sort: 6,5,4,3,2.", "Place 6 in bin 1 and 5 in bin 2.", "Place 4 in bin 1, now full.", "Place 3 and then 2 in bin 2, now full.", "Two bins are used; the total size is 20, so two is also a lower bound and the packing is optimal."]}, "practice": {"q": "Use first-fit decreasing for items 8,7,3,2 with capacity 10.", "answer": null, "steps": ["Sort: 8,7,3,2.", "Bin 1 starts with 8; bin 2 starts with 7.", "3 joins 7; 2 joins 8.", "Two bins suffice and total size 20 proves optimality."]}, "check": {"q": "Items total 20 and bin capacity is 10. What is the volume-based lower bound on bin count?", "a": 2}}, {"id": "d1-graph", "module": "d1", "title": "Minimum spanning trees and shortest paths", "refs": "2", "notes": ["Kruskal’s algorithm adds eligible edges in increasing weight order without creating a cycle. Prim’s algorithm grows one connected tree. A minimum spanning tree connects every vertex with minimum total weight; it does not minimise every journey from a chosen origin.", "Dijkstra’s algorithm permanently labels the smallest tentative distance and requires non-negative edge weights. Floyd’s algorithm updates all-pairs distances by allowing intermediate vertices in a stated order. Record predecessors or route information as well as distances so the actual path can be recovered."], "example": {"q": "An undirected graph has AB=2, AC=5, BC=1, BD=4, CD=2. Find an MST and the shortest A–D route.", "steps": ["Kruskal selects BC=1, AB=2 and CD=2 without a cycle.", "The MST total is 5.", "For the A–D journey, A–B–C–D has length 2+1+2=5.", "A–B–D has length 6 and A–C–D has length 7.", "The shortest route is A–B–C–D of length 5."]}, "practice": {"q": "Why can a minimum spanning tree fail to contain a shortest route between a particular pair of vertices?", "answer": null, "steps": ["An MST optimises total connection cost for all vertices.", "A shortest path optimises one endpoint-to-endpoint journey.", "Removing a cycle can discard a shortcut useful for that journey.", "The two optimisation objectives are different."]}, "check": {"q": "How many edges does a spanning tree on 7 vertices have?", "a": 6}}, {"id": "d1-route", "module": "d1", "title": "Route inspection and travelling-salesperson bounds", "refs": "3", "notes": ["A connected undirected graph has an Eulerian circuit when every vertex has even degree. Route inspection duplicates paths to pair odd vertices at minimum additional cost, then finds a closed traversal of every original edge. When there are more than two odd vertices, compare complete pairings rather than greedily selecting one cheap pair.", "A travelling-salesperson tour visits each vertex and returns to the start; it need not traverse every edge. Nearest-neighbour tours give upper bounds. A minimum-spanning-tree construction after deleting a vertex and adding its two cheapest incident edges can give a lower bound for a tour. Distinguish a proven optimum from matching or non-matching bounds."], "example": {"q": "A connected network has total edge weight 40 and exactly two odd vertices P and Q. Their shortest connecting path has weight 7. Find the shortest closed route-inspection length.", "steps": ["Both odd degrees must be made even.", "Duplicate a shortest P–Q path.", "The added cost is 7.", "The closed route length is 40+7=47."]}, "practice": {"q": "A route-inspection network has edge total 60 and four odd vertices. The three complete-pairing costs are 12,15 and 9. Find the minimum closed route length.", "answer": 69, "steps": ["Choose the least complete pairing cost, 9.", "Add this duplicated-path cost to the original edge total.", "The minimum length is 69."]}, "check": {"q": "A route-inspection graph has edge total 40 and just two odd vertices with shortest connecting distance 7. Find the shortest closed tour length.", "a": 47}}, {"id": "d1-critical", "module": "d1", "title": "Critical paths, floats and resource scheduling", "refs": "4", "notes": ["In an activity-on-arc model, arrows represent activities and vertices represent events. Dummy activities express precedence without consuming time or resources. A forward pass uses maxima to find earliest event times; a backward pass uses minima to find latest event times.", "Total float for an activity from i to j is latest(j)−earliest(i)−duration. A critical path has zero total float throughout and determines the minimum project completion time under the precedence model. Resource limits can increase this completion time, so a critical-path calculation is not itself a feasible staff schedule."], "example": {"q": "Activities A and B start together and take 3 and 5 days. C takes 4 days after A. D takes 2 days after both B and C. Find project duration.", "steps": ["A finishes at 3 and B at 5.", "C finishes at 3+4=7.", "D starts at max(5,7)=7.", "The project finishes at 9.", "A–C–D is critical; B has 2 days of total float."]}, "practice": {"q": "A takes 4 days; B takes 3 days after A; C takes 6 days after A. D takes 2 days after both B and C. Find the duration and critical path.", "answer": null, "steps": ["A finishes at 4.", "B finishes at 7 and C at 10.", "D runs from day 10 to day 12.", "Duration=12 days; A–C–D is critical."]}, "check": {"q": "An activity from event i to j has earliest(i)=3, latest(j)=10 and duration 4. Find total float.", "a": 3}}, {"id": "d1-lp", "module": "d1", "title": "Formulating and solving linear programmes graphically", "refs": "5.1–5.2", "notes": ["Define decision variables with units, translate each resource limit into an inequality and specify non-negativity. A linear objective has parallel level lines. In a bounded feasible polygon, an optimum occurs at a vertex, or along an edge when the objective is parallel to it.", "Continuous and integer solutions are different problems. Rounding a continuous optimum may violate constraints or lose the best integer choice. Check unboundedness and infeasibility rather than assuming every diagram has one optimal corner."], "example": {"q": "Maximise 3x+2y subject to x+y≤4, x≤2 and x,y≥0.", "steps": ["The feasible vertices are (0,0),(2,0),(2,2),(0,4).", "Objective values are 0,6,10,8.", "The maximum is 10 at (2,2).", "Both x+y≤4 and x≤2 are active there."]}, "practice": {"q": "Maximise 2x+3y subject to x+y≤5, x≤3, y≤4 and x,y≥0.", "answer": null, "steps": ["Feasible corner candidates include (0,0),(3,0),(3,2),(1,4),(0,4).", "Objective values are 0,6,12,14,12.", "The maximum is 14 at (1,4).", "Check every listed point against the inequalities."]}, "check": {"q": "Evaluate objective 3x+2y at (2,2).", "a": 10}}, {"id": "d1-simplex", "module": "d1", "title": "Simplex pivots and the two-stage method", "refs": "5.3–5.4", "notes": ["The simplex method moves between basic feasible solutions. Introduce slack variables for ≤ constraints and follow one consistent objective-row convention. A positive pivot column uses the smallest eligible non-negative ratio to retain feasibility; zero or negative pivot entries do not enter that ratio test.", "Artificial variables provide a starting basis when ordinary slacks do not. In phase I minimise their sum; a positive optimal artificial sum proves infeasibility. If the minimum is zero, remove artificial variables appropriately and restore the original objective for phase II. A pivot improving an objective is not proof of optimality until the stopping criterion is met."], "example": {"q": "For maximise 3x+2y with x+y≤4 and x≤2, explain the first pivot from the slack basis.", "steps": ["Use x+y+s₁=4 and x+s₂=2.", "With x entering, eligible ratios are 4/1=4 and 2/1=2.", "The second row leaves; pivot there to obtain x=2 at y=0.", "The basis remains feasible. Further improvement can reach x=2,y=2 and objective 10."]}, "practice": {"q": "A phase-I simplex calculation minimising the sum of artificial variables finishes at value 3. What does this imply?", "answer": null, "steps": ["Artificial variables would all need to be zero for the original constraints to hold.", "Their minimum sum is positive.", "The original linear programme is infeasible.", "It is not appropriate to proceed to an ordinary phase-II optimum."]}, "check": {"q": "For entering column entries 1,2 and right-hand sides 6,8, find the minimum eligible ratio.", "a": 4}}, {"id": "d2-transport", "module": "d2", "title": "Transportation and stepping-stone improvements", "refs": "1", "notes": ["A transportation table allocates supplies to meet demands at minimum total unit cost. Balance the totals, adding an appropriate dummy source or destination if necessary. The north-west corner method constructs a feasible allocation without consulting costs, so it does not establish optimality.", "A stepping-stone loop alternates additions and subtractions through occupied cells. Its signed unit cost gives the improvement per unit moved; the smallest allocation on a subtracting corner limits the move. Degeneracy requires care with the basis so valid loops and optimality tests remain possible."], "example": {"q": "Supplies are 20,30; demands are 25,25; costs are [[2,5],[4,1]]. Find the north-west allocation and test its only unused cell.", "steps": ["Allocate x₁₁=20, x₂₁=5, x₂₂=25.", "Cost=20×2+5×4+25×1=85.", "Introducing x₁₂ changes the cost per unit by 5−2+4−1=6.", "The change is positive, so no cost reduction is possible through this loop.", "This allocation is optimal for this 2×2 problem."]}, "practice": {"q": "Use supplies 20,30 and demands 25,25 with costs [[4,1],[2,5]]. Improve the north-west allocation.", "answer": null, "steps": ["The north-west cost is 20×4+5×2+25×5=215.", "The unused-cell loop changes cost by 1−4+2−5=−6 per unit.", "Move 20 units around the loop.", "The new allocations are x₁₂=20, x₂₁=25, x₂₂=5.", "The cost is 20+50+25=95."]}, "check": {"q": "Supplies are 20 and 30, and demands are 25 and 25. What is the total supply?", "a": 50}}, {"id": "d2-assignment", "module": "d2", "title": "Hungarian allocation and linear programming models", "refs": "2", "notes": ["An assignment problem chooses one task per worker and one worker per task. In the Hungarian method for minimisation, reduce rows first and then columns. Cover all zeroes with the minimum number of lines; if too few independent zeroes exist, adjust the uncovered entries and doubly covered entries correctly.", "For a maximum-profit problem, convert to a consistent minimisation table before applying the algorithm. Add dummy rows or columns when appropriate and interpret them in context. An assignment LP uses binary decision variables with row and column sums equal to one; do not confuse a table of reduced costs with the original total cost."], "example": {"q": "Minimise assignment cost for [[4,1,3],[2,0,5],[3,2,2]].", "steps": ["Row reduction gives [[3,0,2],[2,0,5],[1,0,0]].", "Column reduction gives [[2,0,2],[1,0,5],[0,0,0]].", "Cover zeroes by column 2 and row 3. The smallest uncovered entry is 1.", "After adjustment the table is [[1,0,1],[0,0,4],[0,1,0]].", "Choose row 1→column 2, row 2→column 1, row 3→column 3.", "The original cost is 1+2+2=5."]}, "practice": {"q": "Find the minimum assignment cost for [[4,1],[2,5]].", "answer": 3, "steps": ["The diagonal assignment costs 4+5=9.", "The off-diagonal assignment costs 1+2=3.", "The minimum is 3, using worker 1→task 2 and worker 2→task 1."]}, "check": {"q": "For costs [[4,1],[2,5]], find the cost of the off-diagonal assignment.", "a": 3}}, {"id": "d2-flow", "module": "d2", "title": "Maximum flow, minimum cuts and restricted networks", "refs": "3", "notes": ["A feasible flow respects every arc capacity and conservation at intermediate vertices. Augment along a source-to-sink route in the residual network, whose backward arcs allow previous choices to be revised. A saturated-looking forward network alone does not prove maximality.", "A cut separates source from sink and its directed capacity is the sum of forward arcs crossing that separation. The max-flow min-cut theorem proves optimality when a feasible flow matches a cut capacity. Multiple sources, vertex restrictions and lower bounds require appropriate network transformations before applying the standard algorithm."], "example": {"q": "A network has arcs s→a capacity 4, a→t capacity 3, s→b capacity 2 and b→t capacity 5. Find maximum flow.", "steps": ["Send 3 along s–a–t.", "Send 2 along s–b–t.", "The feasible total is 5.", "The cut with source side {s,a} has capacity 3+2=5.", "Matching flow and cut proves a maximum of 5."]}, "practice": {"q": "A feasible network flow has value 12 and a source–sink cut has capacity 12. What can be concluded?", "answer": null, "steps": ["Every feasible flow is at most the capacity of every source–sink cut.", "The flow attains that bound.", "Its value 12 is maximal and the cut is minimal.", "Both feasibility and the directed cut calculation are essential."]}, "check": {"q": "A feasible flow of value 5 matches a cut capacity of 5. Find maximum flow.", "a": 5}}, {"id": "d2-dynamic", "module": "d2", "title": "Dynamic programming and Bellman recursions", "refs": "4", "notes": ["A staged optimisation problem uses states that contain all information needed for future choices. Define a value function for the best remaining cost or reward. Work backwards from the final stage, choosing the minimum or maximum over feasible next decisions.", "Record the decision attaining each value as well as the value itself, then trace a route forwards. A greedy choice based only on the next edge can fail because the remaining cost differs by destination. Avoid mixing a minimisation recurrence with a maximisation terminal condition."], "example": {"q": "From S choose A at cost 2 or B at cost 5. From A to T costs 8; from B to T costs 1. Find the cheapest route.", "steps": ["At the final state, V(T)=0.", "V(A)=8 and V(B)=1.", "V(S)=min(2+8,5+1)=6.", "Choose S–B–T, even though its first edge costs more."]}, "practice": {"q": "S→A costs 4, S→B costs 1, A→T costs 2 and B→T costs 7. Use a backward recurrence.", "answer": null, "steps": ["V(T)=0, V(A)=2 and V(B)=7.", "V(S)=min(4+2,1+7)=6.", "The optimal route is S–A–T.", "A locally cheapest first edge would be misleading."]}, "check": {"q": "Two candidate route costs are 2+8 and 5+1. Find their minimum.", "a": 6}}, {"id": "d2-games", "module": "d2", "title": "Zero-sum games, dominance and mixed strategies", "refs": "5", "notes": ["A payoff table must specify whose gain is shown. The row player maximises and the column player minimises that payoff in a zero-sum model. If maximin equals minimax, a saddle point gives an optimal pure strategy. Dominated strategies can be removed only with the correct inequality direction.", "For a 2×2 game without a saddle point, make the opponent indifferent between the relevant pure responses to find a mixed strategy. Check that the probabilities lie between zero and one. Larger games may be solved graphically or with a linear-programming formulation, with probabilities summing to one."], "example": {"q": "The row player’s payoffs are [[3,0],[1,2]]. Find optimal mixing probabilities and game value.", "steps": ["Row minima are 0,1; column maxima are 3,2, so there is no saddle point.", "If row 1 is used with probability p, column payoffs are 1+2p and 2−2p.", "Equating gives p=1/4 and value 3/2.", "If column 1 is used with probability q, row payoffs are 3q and 2−q.", "Equating gives q=1/2, confirming value 3/2."]}, "practice": {"q": "Find the mixed strategy for the row player in the game [[2,0],[0,4]].", "answer": null, "steps": ["If row 1 has probability p, the two column responses give 2p and 4−4p.", "Equate: 6p=4, so p=2/3.", "Use row 2 with probability 1/3.", "The value is 4/3."]}, "check": {"q": "For payoffs [[3,0],[1,2]], solve 1+2p=2−2p for row mixing probability p.", "a": 0.25}}, {"id": "d2-recurrence", "module": "d2", "title": "Recurrence models and long-run behaviour", "refs": "6", "notes": ["A recurrence specifies the timing of an update. In a population or savings model, multiplying before adding is different from adding before multiplying. Write the update in words and identify the initial index before solving the algebraic recurrence.", "For uₙ₊₁=auₙ+b, an equilibrium is b/(1−a) when a≠1. Deviations multiply by a each step, so |a|<1 gives convergence, while |a|>1 generally gives growing deviations. A formal limit must also be consistent with any physical restrictions of the model."], "example": {"q": "Solve uₙ₊₁=0.8uₙ+10 with u₀=0 and find its limit.", "steps": ["Equilibrium L=0.8L+10 gives L=50.", "Let vₙ=uₙ−50, so vₙ₊₁=0.8vₙ.", "v₀=−50.", "uₙ=50−50(0.8)ⁿ.", "Since |0.8|<1, uₙ tends to 50."]}, "practice": {"q": "A quantity obeys uₙ₊₁=0.5uₙ+6 with u₀=4. Find uₙ and its limit.", "answer": null, "steps": ["The equilibrium is 12.", "uₙ−12=(4−12)(0.5)ⁿ.", "uₙ=12−8(0.5)ⁿ.", "The limit is 12."]}, "check": {"q": "Find the equilibrium L satisfying L=0.8L+10.", "a": 50}}, {"id": "d2-decision", "module": "d2", "title": "Decision trees, conditional information and expected value", "refs": "7", "notes": ["A decision tree separates decision nodes from chance nodes. Work backwards: average at a chance node using conditional probabilities and select the best expected value at a decision node. Subtract costs at the stage where they occur; do not count them twice.", "Expected value is a model-based long-run criterion, not a guarantee for one outcome. The expected value of perfect information compares the best decision in each known state with the best current decision. For imperfect sample information, use the correct updated conditional probabilities before choosing an action."], "example": {"q": "A fictional product earns 100 units in a good market and loses 40 in a bad market. P(good)=0.6. Not launching gives 0. Find the expected value of perfect information.", "steps": ["Launch EV=0.6×100+0.4×(−40)=44.", "Without information, choose launch with EV 44.", "With perfect information, launch only in a good market.", "Perfect-information EV=0.6×100=60.", "The value of perfect information is 60−44=16 units."]}, "practice": {"q": "A fictional launch gains 50 units with probability 0.7 and loses 20 otherwise. Not launching gives 0. Find the expected value of perfect information.", "answer": 6, "steps": ["Launch EV=0.7×50−0.3×20=29.", "With perfect information, act only in the favourable state: EV=35.", "The improvement is 35−29=6 units."]}, "check": {"q": "Find the expected value of 100 with probability 0.6 and −40 otherwise.", "a": 44}}], "papers": [{"swap": {"cp-argand": {"q": "Describe the locus |z − (3 + i)| = |z + 1 − i| and find where it crosses the real axis.", "answer": null, "steps": ["The points are equally far from 3 + i and −1 + i.", "The two centres share y = 1, so the locus is a perpendicular bisector through their midpoint (1,1).", "It is the vertical line x = 1.", "It crosses the real axis at z = 1."]}}, "id": "fm-core-paper-1", "module": "core", "title": "Core Pure revision paper 1", "minutes": 90, "marks": 75, "kind": "core-paper", "lessons": ["cp-induction", "cp-complex", "cp-argand", "cp-exponential", "cp-demoivre", "cp-matrix", "cp-transform", "cp-systems", "cp-roots", "cp-series", "cp-maclaurin", "cp-improper", "cp-inverse-calculus", "cp-vector-lines", "cp-planes", "cp-polar", "cp-hyperbolic", "cp-de-first"], "reuse": "Questions are drawn from the lesson practice bank; use them for consolidation, not an unseen mock."}, {"swap": {"cp-argand": {"q": "Describe the locus |z + 3 − 2i| = 5 and find the real numbers z that lie on it.", "answer": null, "steps": ["The centre is (−3,2) and the radius is 5.", "On the real axis y = 0, so (x + 3)² + 4 = 25.", "Then (x + 3)² = 21.", "x = −3 ± √21, approximately 1.58 and −7.58."]}}, "id": "fm-core-paper-2", "module": "core", "title": "Core Pure revision paper 2", "minutes": 90, "marks": 75, "kind": "core-paper", "lessons": ["cp-coupled", "cp-de-second", "cp-de-first", "cp-hyperbolic", "cp-polar", "cp-planes", "cp-vector-lines", "cp-inverse-calculus", "cp-improper", "cp-maclaurin", "cp-series", "cp-roots", "cp-systems", "cp-transform", "cp-matrix", "cp-exponential", "cp-argand", "cp-complex"], "reuse": "Questions are drawn from the lesson practice bank; use them for consolidation, not an unseen mock."}, {"id": "fm-fp1-assessment", "module": "fp1", "title": "Further Pure Mathematics 1 · module assessment", "minutes": 37, "marks": 31, "kind": "module-assessment", "lessons": ["fp1-tformula", "fp1-taylor", "fp1-leibniz", "fp1-weierstrass", "fp1-de-series", "fp1-conics", "fp1-cross", "fp1-numerical"], "reuse": "Short original revision assessment using the module lesson practice bank. This is not a full 75-mark examination paper."}, {"id": "fm-fp2-assessment", "module": "fp2", "title": "Further Pure Mathematics 2 · module assessment", "minutes": 40, "marks": 33, "kind": "module-assessment", "lessons": ["fp2-groups", "fp2-reduction", "fp2-eigen", "fp2-cayley", "fp2-mapping", "fp2-euclid", "fp2-count", "fp2-recurrence"], "reuse": "Short original revision assessment using the module lesson practice bank. This is not a full 75-mark examination paper."}, {"id": "fm-fs1-assessment", "module": "fs1", "title": "Further Statistics 1 · module assessment", "minutes": 35, "marks": 29, "kind": "module-assessment", "lessons": ["fs1-discrete", "fs1-poisson", "fs1-geometric", "fs1-tests", "fs1-clt", "fs1-chi", "fs1-pgf", "fs1-power"], "reuse": "Short original revision assessment using the module lesson practice bank. This is not a full 75-mark examination paper."}, {"id": "fm-fs2-assessment", "module": "fs2", "title": "Further Statistics 2 · module assessment", "minutes": 31, "marks": 26, "kind": "module-assessment", "lessons": ["fs2-regression", "fs2-continuous", "fs2-correlation", "fs2-combinations", "fs2-normal-ci", "fs2-variance", "fs2-t"], "reuse": "Short original revision assessment using the module lesson practice bank. This is not a full 75-mark examination paper."}, {"id": "fm-fm1-assessment", "module": "fm1", "title": "Further Mechanics 1 · module assessment", "minutes": 20, "marks": 17, "kind": "module-assessment", "lessons": ["fm1-impulse", "fm1-energy", "fm1-elastic", "fm1-direct", "fm1-oblique"], "reuse": "Short original revision assessment using the module lesson practice bank. This is not a full 75-mark examination paper."}, {"id": "fm-fm2-assessment", "module": "fm2", "title": "Further Mechanics 2 · module assessment", "minutes": 23, "marks": 19, "kind": "module-assessment", "lessons": ["fm2-circular", "fm2-centres", "fm2-equilibrium", "fm2-dynamics", "fm2-kinematics"], "reuse": "Short original revision assessment using the module lesson practice bank. This is not a full 75-mark examination paper."}, {"id": "fm-d1-assessment", "module": "d1", "title": "Decision Mathematics 1 · module assessment", "minutes": 28, "marks": 23, "kind": "module-assessment", "lessons": ["d1-algorithms", "d1-graph", "d1-route", "d1-critical", "d1-lp", "d1-simplex"], "reuse": "Short original revision assessment using the module lesson practice bank. This is not a full 75-mark examination paper."}, {"id": "fm-d2-assessment", "module": "d2", "title": "Decision Mathematics 2 · module assessment", "minutes": 32, "marks": 27, "kind": "module-assessment", "lessons": ["d2-transport", "d2-assignment", "d2-flow", "d2-dynamic", "d2-games", "d2-recurrence", "d2-decision"], "reuse": "Short original revision assessment using the module lesson practice bank. This is not a full 75-mark examination paper."}]};
